"use client";

import React, { useMemo } from "react";
import Link from "next/link";
import Image from "next/image";
import { ArrowRight, Zap, Tag, Truck, ShieldCheck, CreditCard } from "lucide-react";
import { motion } from "framer-motion";
import ProductCard from "@/components/public/ProductCard";
import { DEFAULT_HOME_CMS, HomeCmsContent } from "@/modules/cms/types";
import { Product, Category } from "@/lib/types";

export default function HomeClient({ products, categories, latestPromo, cms }: {
  products: Product[],
  categories: Category[],
  latestPromo: any,
  cms?: HomeCmsContent,
}) {
  const content = cms || DEFAULT_HOME_CMS;
  const newArrivalsLimit = Number.parseInt(content.newArrivalsLimit, 10) || 24;
  const flashSales = useMemo(() =>
    products.filter((p: Product) => p.oldPrice && Number(p.oldPrice) > Number(p.price)).slice(0, 4)
    , [products]);

  const newArrivals = useMemo(() =>
    products.slice(0, newArrivalsLimit)
    , [products, newArrivalsLimit]);

  const featuredCategories = useMemo(() => {
    const available = categories.filter((category) => (category._count?.products || 0) > 0);
    const selected = content.featuredCategoryIds.length > 0
      ? content.featuredCategoryIds
        .map((id) => available.find((category) => category.id === id))
        .filter((category): category is Category => Boolean(category))
      : available.slice(0, 6);

    return selected.slice(0, 8);
  }, [categories, content.featuredCategoryIds]);

  const containerVars = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.1 }
    }
  };

  const itemVars = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 }
  };

  return (
    <div className="bg-white w-full overflow-x-clip font-body">
      {latestPromo && (
        <div className="bg-[#D4541C] text-white py-2 text-center text-[11px] md:text-[12px] font-medium tracking-wider">
          <Tag size={12} className="inline mr-2" />
          OFFRE : <strong>-{latestPromo.value}{latestPromo.type === "PERCENT" ? "%" : " F"}</strong> AVEC LE CODE
          <span className="bg-black/20 px-2 py-0.5 rounded font-extrabold ml-1">{latestPromo.code}</span>
        </div>
      )}

      <section className="relative h-[75vh] md:h-[90vh] min-h-[500px] md:min-h-[600px] flex items-center justify-center md:justify-start px-6 md:px-[8%] text-white bg-[#1A1614] overflow-hidden">
        <div className="absolute inset-0 z-[1] w-full h-full">
          <Image src={content.heroImage || "/images/hero_banner.png"} alt="ZangoChap Hero" fill priority className="object-cover opacity-70" sizes="100vw" />
          <div className="absolute inset-0 bg-gradient-to-r from-[#1A1614]/90 via-[#1A1614]/40 to-transparent"></div>
        </div>
        <div className="relative z-[2] max-w-[600px] w-full text-center md:text-left">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: "easeOut" }}
          >
            <span className="text-[10px] md:text-[11px] font-extrabold tracking-[0.4em] text-[#D4541C] mb-4 md:mb-6 block uppercase">
              {content.heroEyebrow}
            </span>
            <h1 className="font-display text-[38px] md:text-[72px] lg:text-[86px] font-bold leading-[1] md:leading-[0.95] mb-5 md:mb-6 uppercase">
              {renderMultiline(content.heroTitle)}
            </h1>
            <p className="text-sm md:text-lg text-white/70 mb-8 md:text-white/70 md:mb-10 leading-relaxed font-light">
              {content.heroDescription}
            </p>
            <div className="flex flex-col sm:flex-row gap-3 sm:gap-4 justify-center md:justify-start">
              <Link href={content.heroPrimaryHref || "/shop"} className="px-7 py-3.5 md:px-9 md:py-4 bg-white text-[#1A1614] text-[11px] md:text-[12px] font-bold tracking-widest rounded transition-all hover:bg-[#D4541C] hover:text-white hover:-translate-y-1">
                {content.heroPrimaryLabel}
              </Link>
              <Link href={content.heroSecondaryHref || "/shop"} className="px-7 py-3.5 md:px-9 md:py-4 bg-white/10 text-white text-[11px] md:text-[12px] font-bold tracking-widest rounded backdrop-blur-md border border-white/20 transition-all hover:bg-white/20">
                {content.heroSecondaryLabel}
              </Link>
            </div>
          </motion.div>
        </div>
      </section>

      <section className="flex flex-col md:flex-row justify-center items-center gap-4 md:gap-10 p-4 md:p-6 border-b border-[#F0F0F0] bg-[#FAF9F6]">
        <div className="flex items-center gap-2.5 text-[11px] md:text-[12px] font-semibold text-[#555]">
          <Truck size={18} />
          <span>{content.trustDelivery}</span>
        </div>
        <div className="flex items-center gap-2.5 text-[11px] md:text-[12px] font-semibold text-[#555]">
          <ShieldCheck size={18} />
          <span>{content.trustQuality}</span>
        </div>
        <div className="flex items-center gap-2.5 text-[11px] md:text-[12px] font-semibold text-[#555]">
          <CreditCard size={18} />
          <span>{content.trustPayment}</span>
        </div>
      </section>

      {content.categoriesEnabled && featuredCategories.length > 0 && (
        <section className="max-w-[1300px] mx-auto px-5 py-10 md:py-[54px]">
          <div className="mb-7 text-center">
            <span className="text-[9px] md:text-[10px] font-extrabold tracking-[0.3em] text-[#D4541C] block mb-2 uppercase">{content.categoriesEyebrow}</span>
            <h2 className="font-display text-[26px] md:text-[32px] font-bold text-[#1A1614] uppercase">{content.categoriesTitle}</h2>
            <p className="mt-3 text-[14px] text-[#777] max-w-[620px] mx-auto">{content.categoriesDescription}</p>
          </div>
          <motion.div
            variants={containerVars}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-4"
          >
            {featuredCategories.map((category) => (
              <motion.div key={category.id} variants={itemVars}>
                <Link
                  href={`/shop?category=${encodeURIComponent(category.name)}`}
                  className="group relative flex min-h-[120px] flex-col justify-between overflow-hidden rounded-sm border border-[#ECE8E2] bg-white p-5 text-[#1A1614] transition-all hover:border-[#D4541C]"
                >
                  <div className="absolute top-0 right-0 w-16 h-16 bg-[#FAF9F6] rounded-bl-full z-0 transition-transform duration-500 group-hover:scale-150 group-hover:bg-[#FFF5F0]"></div>

                  <div className="flex items-start justify-between z-10 relative">
                    <span className="font-display text-[16px] md:text-[18px] font-bold uppercase leading-tight pr-2">{category.name}</span>
                    <span className="flex items-center justify-center bg-white text-[#777] text-[10px] font-bold px-2 py-1 rounded-sm border border-[#ECE8E2] group-hover:bg-[#D4541C] group-hover:text-white group-hover:border-[#D4541C] transition-colors whitespace-nowrap shadow-sm">
                      {category._count?.products || 0}
                    </span>
                  </div>

                  <div className="mt-5 flex items-center justify-between z-10 relative">
                    <span className="text-[10px] font-extrabold uppercase tracking-[0.18em] text-[#777] group-hover:text-[#D4541C] flex items-center gap-2 transition-colors">
                      Découvrir <ArrowRight size={12} className="transition-transform group-hover:translate-x-1" />
                    </span>
                  </div>
                </Link>
              </motion.div>
            ))}
          </motion.div>
        </section>
      )}





      {content.collectionsEnabled && (
        <section className="max-w-[1300px] mx-auto px-5 py-10 md:py-[60px]">
          <div className="mb-8 md:mb-10 text-center">
            <span className="text-[9px] md:text-[10px] font-extrabold tracking-[0.3em] text-[#D4541C] block mb-2 md:mb-3 uppercase">{content.collectionsEyebrow}</span>
            <h2 className="font-display text-[26px] md:text-[32px] font-bold text-[#1A1614] mb-2 md:mb-3 uppercase">{content.collectionsTitle}</h2>
          </div>
          <div className="flex md:grid md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6 overflow-x-auto snap-x snap-mandatory pb-4 -mx-5 px-5 md:mx-0 md:px-0 md:pb-0 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
            {(content.collectionsList || []).map((collection) => (
              <Link
                key={collection.id}
                href={collection.href || "/shop"}
                className="group relative overflow-hidden rounded-sm block flex-none w-[75vw] sm:w-[45vw] md:w-auto h-[280px] sm:h-[300px] md:h-[300px] lg:h-[400px] bg-[#F3F1ED] snap-center"
              >
                {collection.image && (
                  <Image
                    src={collection.image}
                    alt={collection.title}
                    fill
                    sizes="(max-width: 768px) 75vw, (max-width: 1024px) 50vw, 33vw"
                    className="object-cover transition-transform duration-1000 group-hover:scale-105"
                  />
                )}
                <div className="absolute inset-x-0 bottom-0 p-6 md:p-8 bg-gradient-to-t from-black/80 via-black/40 to-transparent flex flex-col gap-1 md:gap-2">
                  <h3 className="font-display text-[20px] md:text-[28px] font-bold tracking-wider text-white uppercase leading-none">
                    {collection.title}
                  </h3>
                  <span className="text-[10px] md:text-[12px] font-bold tracking-[0.2em] flex items-center gap-2 opacity-80 text-white uppercase">
                    EXPLORER <ArrowRight size={12} className="transition-transform group-hover:translate-x-1" />
                  </span>
                </div>
              </Link>
            ))}
          </div>
        </section>
      )}

      {content.flashEnabled && flashSales.length > 0 && (
        <section className="max-w-[1300px] mx-auto px-6 py-[60px]">
          <div className="mb-10">
            <div className="flex items-center gap-3 mb-3">
              <Zap size={20} className="text-red-600 fill-red-600" />
              <h2 className="font-display text-[32px] font-bold text-[#1A1614] leading-none uppercase">{content.flashTitle}</h2>
              <CountdownTimer />
            </div>
            <p className="text-[15px] text-[#777] max-w-[600px]">{content.flashDescription}</p>
          </div>
          <motion.div
            variants={containerVars}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-8"
          >
            {flashSales.map((p: Product) => (
              <motion.div key={p.id} variants={itemVars}>
                <ProductCard p={p} />
              </motion.div>
            ))}
          </motion.div>
        </section>
      )}

      {content.newArrivalsEnabled && (
        <section className="max-w-[1300px] mx-auto px-6 py-[60px]">
          <div className="mb-10 text-center">
            <span className="text-[10px] font-extrabold tracking-[0.3em] text-[#D4541C] block mb-3 uppercase">{content.newArrivalsEyebrow}</span>
            <h2 className="font-display text-[32px] font-bold text-[#1A1614] mb-3 uppercase">{content.newArrivalsTitle}</h2>
            <p className="text-[15px] text-[#777] max-w-[600px] mx-auto">{content.newArrivalsDescription}</p>
          </div>
          <motion.div
            variants={containerVars}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-8"
          >
            {newArrivals.map((p: Product) => (
              <motion.div key={p.id} variants={itemVars}>
                <ProductCard p={p} />
              </motion.div>
            ))}
          </motion.div>
          <div className="mt-10 flex justify-center">
            <Link href="/shop" className="inline-block px-12 py-4 border-[1.5px] border-[#1A1614] text-[#1A1614] font-extrabold text-[12px] tracking-[0.2em] transition-all hover:bg-[#1A1614] hover:text-white uppercase">
              {content.catalogButtonLabel}
            </Link>
          </div>
        </section>
      )}
    </div>
  );
}

function renderMultiline(text: string) {
  return text.split("\n").map((line, index) => (
    <React.Fragment key={`${line}-${index}`}>
      {index > 0 && <br />}
      {line}
    </React.Fragment>
  ));
}

function CountdownTimer() {
  const [time, setTime] = React.useState({ h: 0, m: 0, s: 0 });

  React.useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      const night = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0);
      const diff = Math.floor((night.getTime() - now.getTime()) / 1000);

      const h = Math.floor(diff / 3600);
      const m = Math.floor((diff % 3600) / 60);
      const s = diff % 60;

      setTime({ h, m, s });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  return (
    <div className="flex items-center gap-1.5 ml-3">
      <div className="bg-[#1A1614] text-white px-2 py-1 text-[11px] font-extrabold rounded-sm min-w-[28px] text-center">
        {String(time.h).padStart(2, "0")}
      </div>
      <span className="font-extrabold text-[12px] text-[#1A1614] opacity-50">:</span>
      <div className="bg-[#1A1614] text-white px-2 py-1 text-[11px] font-extrabold rounded-sm min-w-[28px] text-center">
        {String(time.m).padStart(2, "0")}
      </div>
      <span className="font-extrabold text-[12px] text-[#1A1614] opacity-50">:</span>
      <div className="bg-[#1A1614] text-white px-2 py-1 text-[11px] font-extrabold rounded-sm min-w-[28px] text-center">
        {String(time.s).padStart(2, "0")}
      </div>
    </div>
  );
}

import prisma from "@/lib/prisma";
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/modules/auth/actions";

export const dynamic = "force-dynamic";

const PAGE_SIZE = 20;

export async function GET(req: NextRequest) {
  try {
    const user = await getSession();
    if (!user) return NextResponse.json({ error: "Non authentifié" }, { status: 401 });

    const q = req.nextUrl.searchParams.get("q") || "";
    const page = parseInt(req.nextUrl.searchParams.get("page") || "1");
    const category = req.nextUrl.searchParams.get("category") || "";
    const ids = req.nextUrl.searchParams.get("ids") || "";
    const allStatus = req.nextUrl.searchParams.get("allStatus") === "true";

    const where: any = {};
    if (!allStatus) {
      where.status = { not: 'DRAFT' };
    }

    if (ids) {
      where.id = { in: ids.split(",").filter(Boolean) };
    } else {
      if (q) {
        const terms = q.trim().split(/\s+/).filter(Boolean);
        if (terms.length > 0) {
          where.AND = terms.map(term => ({
            OR: [
              { name: { contains: term, mode: 'insensitive' } },
              { ref: { contains: term, mode: 'insensitive' } },
              { category: { name: { contains: term, mode: 'insensitive' } } },
              { supplier: { name: { contains: term, mode: 'insensitive' } } },
              { variants: { some: { size: { contains: term, mode: 'insensitive' } } } },
              { variants: { some: { color: { contains: term, mode: 'insensitive' } } } }
            ]
          }));
        }
      }

      if (category) {
        where.categoryId = category;
      }
    }

    const [products, total, categoryList] = await Promise.all([
      prisma.product.findMany({
        where,
        select: {
          id: true,
          name: true,
          price: true,
          emoji: true,
          categoryId: true,
          category: { select: { id: true, name: true } },
          stock: true,
          status: true,
          images: { select: { url: true }, take: 1 },
          variants: { select: { id: true, size: true, color: true, stock: true } },
        },
        orderBy: { name: 'asc' },
        take: ids ? undefined : PAGE_SIZE,
        skip: ids ? undefined : (page - 1) * PAGE_SIZE,
      }),
      ids ? prisma.product.count({ where }) : prisma.product.count({ where }),
      prisma.category.findMany({
        where: allStatus ? undefined : { products: { some: { status: { not: 'DRAFT' } } } },
        select: { id: true, name: true },
        orderBy: { name: 'asc' },
      }),
    ]);

    // Map category name onto product for client convenience
    const enrichedProducts = products.map(p => ({
      ...p,
      categoryName: p.category?.name || null,
    }));

    return NextResponse.json({
      products: JSON.parse(JSON.stringify(enrichedProducts)),
      total,
      totalPages: ids ? 1 : Math.ceil(total / PAGE_SIZE),
      page,
      categories: categoryList.map(c => ({ id: c.id, name: c.name })),
    });
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 500 });
  }
}

import prisma from "@/lib/prisma";
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/modules/auth/actions";

// Gestion des codes promo : creation/modification/suppression reservees aux
// admins. Sans cette garde, un anonyme pouvait creer un code -100% ou supprimer
// tous les codes par simple requete HTTP.
async function requireAdmin() {
  const session = await getSession();
  const role = String(session?.role || "").toLowerCase();
  if (!session || !["admin", "developer"].includes(role)) return null;
  return session;
}

export async function POST(req: NextRequest) {
  try {
    const session = await requireAdmin();
    if (!session) return NextResponse.json({ error: "Non autorise" }, { status: 401 });

    const data = await req.json();
    const { productIds, categoryIds, ...rest } = data;

    const promo = await prisma.promoCode.create({
      data: {
        code: rest.code,
        label: rest.label || rest.code,
        type: rest.type,
        value: rest.value || 0,
        giftProductId: rest.giftProductId || null,
        rule: rest.rule || 'UNLIMITED',
        minAmount: rest.minAmount || 0,
        minQuantity: rest.minQuantity || 0,
        maxGlobalUses: rest.maxGlobalUses || null,
        startDate: rest.startDate ? new Date(rest.startDate) : null,
        endDate: rest.endDate ? new Date(rest.endDate) : null,
        isActive: true,
        isAutomatic: rest.isAutomatic || false,
        // Le createur est la session courante, jamais une valeur fournie par le client.
        creatorId: session.id,
        products: productIds?.length ? {
          connect: productIds.map((id: string) => ({ id }))
        } : undefined,
        categories: categoryIds?.length ? {
          connect: categoryIds.map((id: string) => ({ id }))
        } : undefined,
      },
    });
    return NextResponse.json(promo);
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 400 });
  }
}

export async function PATCH(req: NextRequest) {
  try {
    const session = await requireAdmin();
    if (!session) return NextResponse.json({ error: "Non autorise" }, { status: 401 });

    const data = await req.json();
    const { code, productIds, categoryIds } = data;

    // Liste blanche des champs modifiables : on n'accepte plus un spread {...rest}
    // qui laissait ecrire n'importe quelle colonne (creatorId, isActive, id...).
    const updateData: Record<string, unknown> = {};
    const setIfPresent = (key: string, transform?: (value: any) => unknown) => {
      if (data[key] === undefined) return;
      updateData[key] = transform ? transform(data[key]) : data[key];
    };
    setIfPresent("label");
    setIfPresent("type");
    setIfPresent("value");
    setIfPresent("giftProductId");
    setIfPresent("rule");
    setIfPresent("minAmount");
    setIfPresent("minQuantity");
    setIfPresent("maxGlobalUses");
    setIfPresent("isActive");
    setIfPresent("isAutomatic");
    setIfPresent("startDate", (value) => (value ? new Date(value) : null));
    setIfPresent("endDate", (value) => (value ? new Date(value) : null));

    if (productIds !== undefined) {
      updateData.products = { set: productIds.map((id: string) => ({ id })) };
    }
    if (categoryIds !== undefined) {
      updateData.categories = { set: categoryIds.map((id: string) => ({ id })) };
    }

    await prisma.promoCode.update({
      where: { code },
      data: updateData,
    });
    return NextResponse.json({ success: true });
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 400 });
  }
}

export async function DELETE(req: NextRequest) {
  try {
    const session = await requireAdmin();
    if (!session) return NextResponse.json({ error: "Non autorise" }, { status: 401 });

    const code = req.nextUrl.searchParams.get('code');
    if (!code) return NextResponse.json({ error: 'Code requis' }, { status: 400 });
    await prisma.promoUsage.deleteMany({ where: { promoCode: code } });
    await prisma.promoCode.delete({ where: { code } });
    return NextResponse.json({ success: true });
  } catch (e: any) {
    return NextResponse.json({ error: e.message }, { status: 400 });
  }
}

"use client";

import React, { useState, useTransition, useEffect } from "react";
import { CartItem, useCart } from "@/lib/CartContext";
import { formatPrice } from "@/lib/constants";
import { Trash2, ShoppingBag, ArrowRight, CheckCircle2, ShieldCheck, ChevronLeft, Tag } from "lucide-react";
import Link from "next/link";
import { createPublicOrder } from "@/modules/orders/actions";
import { getAutomaticDiscountAction, validatePromoCodeAction } from "@/modules/products/actions";
import { useToast } from "@/components/Toast";
import { useSearchParams } from "next/navigation";
import { Commune } from "@/lib/types";

const onlyDigits = (value: string) => value.replace(/\D/g, '');

export default function CartPageClient({ communes = [], relayPoints = [] }: { communes?: Commune[]; relayPoints?: string[] }) {
  const { cart, removeFromCart, clearCart } = useCart();
  const { showToast } = useToast();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = useTransition();
  const [orderSuccess, setOrderSuccess] = useState(false);
  const [directItem, setDirectItem] = useState<CartItem | null>(null);
  const isBuyNow = searchParams.get("buyNow") === "1";

  // Form State
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [phone2, setPhone2] = useState("");
  const [commune, setCommune] = useState("");
  const [address, setAddress] = useState("");

  // Promo State
  const [discount, setDiscount] = useState<{ code: string | null, amount: number, label: string | null, type?: string | null, giftProductId?: string | null }>({
    code: null,
    amount: 0,
    label: null,
    type: null,
    giftProductId: null
  });
  const [promoInput, setPromoInput] = useState("");
  const [appliedPromo, setAppliedPromo] = useState<string | null>(null);
  const [showPromoInput, setShowPromoInput] = useState(false);
  const [promoError, setPromoError] = useState<string | null>(null);
  const [isValidatingPromo, setIsValidatingPromo] = useState(false);

  // Fetch automatic or manual discount
  useEffect(() => {
    const checkoutItems = directItem ? [directItem] : cart;
    if (checkoutItems.length > 0) {
      const fetchDiscount = async () => {
        if (appliedPromo) {
          const res = await validatePromoCodeAction(
            appliedPromo,
            checkoutItems.map(item => ({
              productId: item.productId,
              price: item.price,
              qty: item.qty
            })),
            phone || undefined
          );
          if (res.success && res.discount) {
            setDiscount(res.discount);
            setPromoError(null);
          } else {
            setDiscount({ code: null, amount: 0, label: null, type: null, giftProductId: null });
            setAppliedPromo(null);
            showToast(res.error || "Le code promo n'est plus applicable.", "error");
          }
        } else {
          const res = await getAutomaticDiscountAction(
            checkoutItems.map(item => ({
              productId: item.productId,
              price: item.price,
              qty: item.qty
            })),
            phone || undefined
          );
          setDiscount(res);
        }
      };
      fetchDiscount();
    } else {
      setDiscount({ code: null, amount: 0, label: null, type: null, giftProductId: null });
      setAppliedPromo(null);
    }
  }, [cart, directItem, phone, appliedPromo]);

  const handleApplyPromo = async () => {
    if (!promoInput.trim()) return;
    setIsValidatingPromo(true);
    setPromoError(null);

    try {
      const checkoutItems = directItem ? [directItem] : cart;
      const res = await validatePromoCodeAction(
        promoInput.trim(),
        checkoutItems.map(item => ({
          productId: item.productId,
          price: item.price,
          qty: item.qty
        })),
        phone || undefined
      );

      if (res.success && res.discount) {
        setAppliedPromo(res.discount.code);
        setDiscount(res.discount);
        showToast("Code promo appliqué avec succès !", "success");
        setPromoInput("");
        setPromoError(null);
      } else {
        setPromoError(res.error || "Code promo invalide.");
        showToast(res.error || "Code promo invalide.", "error");
      }
    } catch (err) {
      console.error(err);
      setPromoError("Une erreur est survenue lors de la validation.");
    } finally {
      setIsValidatingPromo(false);
    }
  };

  const handleRemovePromo = () => {
    setAppliedPromo(null);
    setDiscount({ code: null, amount: 0, label: null, type: null, giftProductId: null });
    showToast("Code promo retiré.", "success");
  };

  useEffect(() => {
    if (!isBuyNow) {
      setDirectItem(null);
      return;
    }

    const saved = sessionStorage.getItem("zangochap_buy_now");
    if (!saved) return;
    try {
      setDirectItem(JSON.parse(saved));
    } catch {
      sessionStorage.removeItem("zangochap_buy_now");
    }
  }, [isBuyNow]);



  const selectedCommuneObj = communes.find(c => c.name === commune);
  const deliveryFee = selectedCommuneObj ? selectedCommuneObj.deliveryFee : 0;
  const checkoutItems = directItem ? [directItem] : cart;
  const checkoutTotal = checkoutItems.reduce((sum, item) => sum + item.price * item.qty, 0);
  const grandTotal = Math.max(0, checkoutTotal + deliveryFee - discount.amount);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (checkoutItems.length === 0) return;
    if (!name || !phone || !commune || !address) {
      showToast("Veuillez remplir tous les champs de livraison", "error");
      return;
    }

    startTransition(async () => {
      try {
        const res = await createPublicOrder({
          customerName: name,
          customerPhone: phone,
          customerPhone2: phone2 || undefined,
          customerLocation: address,
          commune,
          deliveryFee,
          promoCode: discount.code || undefined,
          discount: discount.amount,
          items: checkoutItems.map(item => ({
            productId: item.productId,
            variantId: item.variantId,
            name: item.name,
            size: item.size,
            color: item.color,
            qty: item.qty,
            price: item.price,
            image: item.image,
          }))
        });

        if (!res.success) {
          // Le vrai motif remonte du serveur (rupture, promo expiree, point relais...).
          showToast(res.error, "error");
          return;
        }

        showToast("Commande validée avec succès !", "success");
        if (directItem) {
          sessionStorage.removeItem("zangochap_buy_now");
        } else {
          clearCart();
        }
        setOrderSuccess(true);
      } catch {
        showToast("Erreur reseau. Verifiez votre connexion et reessayez.", "error");
      }
    });
  };

  if (orderSuccess) {
    return (
      <div className="flex items-center justify-center min-h-[60vh] px-6 py-[60px]">
        <div className="text-center max-w-[460px] animate-[fadeUp_0.5s_ease]">
          <div className="mb-7"><CheckCircle2 size={56} color="#2D8A4E" strokeWidth={1.5} /></div>
          <h1 className="text-[22px] font-light tracking-[0.2em] mb-4 text-[#1A1614]">COMMANDE CONFIRMÉE</h1>
          <p className="text-sm text-[#888] leading-relaxed mb-9">Merci pour votre confiance. Notre équipe vous contactera dans les prochaines minutes pour organiser la livraison.</p>
          <Link href="/" className="inline-block px-12 py-4 bg-[#1A1614] text-white no-underline text-[11px] font-semibold tracking-[0.15em] transition-all hover:bg-[#333] hover:-translate-y-0.5">CONTINUER MES ACHATS</Link>
        </div>
      </div>
    );
  }

  if (checkoutItems.length === 0) {
    // L'achat direct s'appuie sur sessionStorage : en navigation privee ou apres
    // un vidage, l'article peut etre perdu. On l'explique au lieu de laisser croire
    // a un panier vide inexplicable.
    const buyNowLost = isBuyNow;
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] px-6 py-20 text-center animate-[fadeUp_0.5s_ease]">
        <ShoppingBag size={56} color="#ddd" strokeWidth={1.2} />
        <h1 className="text-xl font-light tracking-[0.2em] mt-6 mb-3 text-[#1A1614]">
          {buyNowLost ? "ARTICLE INDISPONIBLE" : "VOTRE PANIER EST VIDE"}
        </h1>
        <p className="text-sm text-[#999] mb-8">
          {buyNowLost
            ? "Nous n'avons pas pu retrouver l'article. Retournez sur la boutique et cliquez a nouveau sur Acheter."
            : "Parcourez notre collection et trouvez la pièce parfaite."}
        </p>
        <Link href="/" className="inline-block px-12 py-4 bg-[#1A1614] text-white no-underline text-[11px] font-semibold tracking-[0.15em] transition-all hover:bg-[#333]">DÉCOUVRIR LA BOUTIQUE</Link>
      </div>
    );
  }

  return (
    <div className="max-w-[1200px] mx-auto px-6 md:px-10 py-6 pb-20 animate-[fadeUp_0.4s_ease] font-body w-full">
      <div className="mb-5">
        <Link href="/" className="no-underline text-[#999] text-[12px] inline-flex items-center gap-1 font-medium tracking-wider transition-colors hover:text-[#1A1614]">
          <ChevronLeft size={14} /> Continuer mes achats
        </Link>
      </div>
      <h1 className="text-2xl font-light tracking-[0.2em] text-[#1A1614] mb-10 uppercase">
        {directItem ? "ACHAT DIRECT" : "PANIER"} <span className="text-[#bbb]">({checkoutItems.length})</span>
      </h1>

      <div className="grid grid-cols-1 lg:grid-cols-[1fr_380px] gap-[60px] items-start">
        {/* ═══ ITEMS ═══ */}
        <div className="flex flex-col gap-0">
          {checkoutItems.map((item: any) => (
            <div key={item.variantId} className="flex items-center gap-6 py-7 border-b border-[#f0f0f0]">
              <div className="w-[90px] h-[110px] bg-[#F5F3EF] flex-shrink-0 overflow-hidden">
                {item.image ? (
                  <img src={item.image} alt="" className="w-full h-full object-cover" />
                ) : (
                  <span className="w-full h-full flex items-center justify-center text-2xl font-thin text-[#D5D0C8]">Z</span>
                )}
              </div>
              <div className="flex-1">
                <h3 className="text-sm font-medium text-[#1A1614] mb-1 tracking-wide">{item.name}</h3>
                <p className="text-[12px] text-[#aaa] mb-1.5">{item.size} · {item.color}</p>
                <p className="text-[13px] text-[#888] font-medium">{formatPrice(item.price)}</p>
              </div>
              <div className="hidden md:block text-[12px] text-[#888] font-medium">
                <span>Qté: {item.qty}</span>
              </div>
              <div className="text-[15px] font-semibold text-[#1A1614] min-w-[80px] text-right">
                {formatPrice(item.price * item.qty)}
              </div>
              {!directItem && (
                <button 
                  className="w-9 h-9 flex items-center justify-center bg-none border border-[#f0f0f0] cursor-pointer text-[#ccc] transition-all hover:border-[#C23616] hover:text-[#C23616]" 
                  onClick={() => removeFromCart(item.variantId)} 
                  aria-label="Supprimer"
                >
                  <Trash2 size={16} />
                </button>
              )}
            </div>
          ))}
        </div>

        {/* ═══ CHECKOUT SIDEBAR ═══ */}
        <div className="bg-[#FAFAF8] p-9 sticky top-[100px] border border-[#f0f0f0] rounded-sm">
          <h2 className="text-[13px] font-normal tracking-[0.2em] mb-7 text-[#1A1614] uppercase">LIVRAISON</h2>
          <form onSubmit={handleSubmit} className="flex flex-col gap-5">
            <div className="space-y-2">
              <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">NOM COMPLET</label>
              <input 
                value={name} 
                onChange={e => setName(e.target.value)} 
                placeholder="Aminata Traoré" 
                required 
                className="w-full p-3.5 border border-[#e8e8e4] bg-white text-sm text-[#1A1614] outline-none transition-colors focus:border-[#1A1614]"
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">TÉLÉPHONE</label>
              <input 
                value={phone}
                onChange={e => setPhone(onlyDigits(e.target.value))}
                placeholder="0700000000"
                inputMode="numeric"
                autoComplete="off"
                maxLength={15}
                required
                className="w-full p-3.5 border border-[#e8e8e4] bg-white text-sm text-[#1A1614] outline-none transition-colors focus:border-[#1A1614]"
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">DEUXIÈME TÉLÉPHONE (FACULTATIF)</label>
              <input 
                value={phone2}
                onChange={e => setPhone2(onlyDigits(e.target.value))}
                placeholder="0500000000"
                inputMode="numeric"
                autoComplete="off"
                maxLength={15}
                className="w-full p-3.5 border border-[#e8e8e4] bg-white text-sm text-[#1A1614] outline-none transition-colors focus:border-[#1A1614]"
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">COMMUNE</label>
              <select 
                value={commune} 
                onChange={e => {
                  const nextCommune = e.target.value;
                  if (nextCommune === 'Boutique' || commune === 'Boutique') setAddress('');
                  setCommune(nextCommune);
                }}
                required
                className="w-full p-3.5 border border-[#e8e8e4] bg-white text-sm text-[#1A1614] outline-none transition-colors focus:border-[#1A1614]"
              >
                <option value="">Sélectionner</option>
                {communes.map((c: Commune) => <option key={c.id} value={c.name}>{c.name} (+{c.deliveryFee.toLocaleString()} F)</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">{commune === 'Boutique' ? 'POINT RELAIS' : 'ADRESSE PRÉCISE'}</label>
              {commune === 'Boutique' ? (
                <select value={address} onChange={e => setAddress(e.target.value)} required className="w-full p-3.5 border border-[#e8e8e4] bg-white text-sm text-[#1A1614] outline-none transition-colors focus:border-[#1A1614]">
                  <option value="">Sélectionner un point relais</option>
                  {relayPoints.map((relayPoint) => <option key={relayPoint} value={relayPoint}>{relayPoint}</option>)}
                </select>
              ) : (
                <textarea value={address} onChange={e => setAddress(e.target.value)} placeholder="Quartier, rue, repères..." rows={3} required className="w-full p-3.5 border border-[#e8e8e4] bg-white text-sm text-[#1A1614] outline-none transition-colors focus:border-[#1A1614] resize-vertical font-inherit" />
              )}
            </div>

            {/* Saisie de code promo */}
            <div className="border-t border-[#e8e8e4] pt-4 mt-2">
              {!appliedPromo ? (
                <div>
                  {!showPromoInput ? (
                    <button
                      type="button"
                      onClick={() => setShowPromoInput(true)}
                      className="text-[11px] font-semibold tracking-[0.12em] text-[#1A1614] hover:text-[#D4541C] transition-colors flex items-center gap-1.5 uppercase bg-none border-none p-0 cursor-pointer"
                    >
                      <Tag size={13} /> J'ai un code promo
                    </button>
                  ) : (
                    <div className="space-y-2 animate-[fadeIn_0.3s_ease]">
                      <div className="flex justify-between items-center">
                        <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">CODE PROMO</label>
                        <button
                          type="button"
                          onClick={() => { setShowPromoInput(false); setPromoError(null); }}
                          className="text-[10px] text-[#aaa] hover:text-[#1A1614] bg-none border-none p-0 cursor-pointer"
                        >
                          Annuler
                        </button>
                      </div>
                      <div className="flex gap-2">
                        <input
                          value={promoInput}
                          onChange={e => setPromoInput(e.target.value.toUpperCase())}
                          placeholder="EX: SUMMER20"
                          className="flex-1 p-2.5 border border-[#e8e8e4] bg-white text-xs text-[#1A1614] uppercase outline-none focus:border-[#1A1614] tracking-wider"
                          disabled={isValidatingPromo}
                        />
                        <button
                          type="button"
                          onClick={handleApplyPromo}
                          disabled={isValidatingPromo || !promoInput.trim()}
                          className="px-4 bg-[#1A1614] text-white border-none text-[10px] font-bold tracking-[0.1em] cursor-pointer hover:bg-[#333] disabled:opacity-40 transition-colors uppercase"
                        >
                          {isValidatingPromo ? "..." : "APPLIQUER"}
                        </button>
                      </div>
                      {promoError && (
                        <p className="text-[11px] text-[#C23616] mt-1 font-medium">{promoError}</p>
                      )}
                    </div>
                  )}
                </div>
              ) : (
                <div className="flex items-center justify-between bg-[#F1EFEA] px-3.5 py-2.5 border border-[#E4E0D5] animate-[fadeIn_0.3s_ease]">
                  <div className="flex items-center gap-2">
                    <Tag size={13} className="text-[#D4541C]" />
                    <span className="text-xs font-semibold tracking-wider text-[#1A1614] uppercase">{appliedPromo}</span>
                    <span className="text-[10px] text-[#888] font-medium">({discount.label || 'Appliqué'})</span>
                  </div>
                  <button
                    type="button"
                    onClick={handleRemovePromo}
                    className="text-[10px] font-semibold text-[#C23616] hover:text-[#9c250b] bg-none border-none p-0 cursor-pointer tracking-wider uppercase"
                  >
                    Retirer
                  </button>
                </div>
              )}
            </div>

            <div className="border-t border-[#e8e8e4] pt-5 flex flex-col gap-3">
              <div className="flex justify-between text-[13px] text-[#888] font-normal"><span>Sous-total</span><span>{formatPrice(checkoutTotal)}</span></div>
              <div className="flex justify-between text-[13px] text-[#888] font-normal"><span>Livraison</span><span>{deliveryFee > 0 ? formatPrice(deliveryFee) : '—'}</span></div>
              
              {discount.amount > 0 && (
                <div className="flex justify-between text-[13px] text-[#D4541C] font-semibold animate-pulse">
                  <span className="flex items-center gap-1.5"><Tag size={14} /> {discount.label || 'Remise automatique'}</span>
                  <span>-{formatPrice(discount.amount)}</span>
                </div>
              )}

              {discount.type === 'GIFT' && (
                <div className="flex justify-between text-[13px] text-green-600 font-semibold animate-pulse">
                  <span className="flex items-center gap-1.5">🎁 Cadeau inclus ({discount.label})</span>
                  <span>Offert</span>
                </div>
              )}

              <div className="flex justify-between text-lg font-semibold text-[#1A1614] pt-3 border-t border-[#e8e8e4] mt-1"><span>Total</span><span>{formatPrice(grandTotal)}</span></div>
            </div>

            <button 
              className="w-full h-[52px] bg-[#1A1614] text-white border-none text-[12px] font-semibold tracking-[0.15em] cursor-pointer flex items-center justify-center gap-2.5 transition-all duration-350 hover:enabled:bg-[#333] hover:enabled:-translate-y-0.5 hover:enabled:shadow-[0_8px_24px_rgba(0,0,0,0.1)] disabled:opacity-50 disabled:cursor-not-allowed" 
              type="submit" 
              disabled={isPending}
            >
              {isPending ? "TRAITEMENT..." : "CONFIRMER LA COMMANDE"}
              {!isPending && <ArrowRight size={16} />}
            </button>

            <div className="flex items-center justify-center gap-1.5 text-[11px] text-[#bbb] mt-1">
              <ShieldCheck size={14} /> Paiement sécurisé · Livraison suivie
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import PublicLayout from "@/components/public/PublicLayout";
import { User, Mail, Phone, Lock, ArrowRight, ShoppingBag, MapPin, Eye, EyeOff } from "lucide-react";
import { loginCustomer, registerCustomer } from "@/modules/auth/customer-actions";
import { useToast } from "@/components/Toast";
import { useRouter } from "next/navigation";

type Tab = "login" | "register";

export default function ComptePage() {
  const router = useRouter();
  const { showToast } = useToast();
  const [tab, setTab] = useState<Tab>("login");
  const [showPassword, setShowPassword] = useState(false);

  // Login state
  const [loginPhone, setLoginPhone] = useState("");
  const [loginPassword, setLoginPassword] = useState("");

  // Register state
  const [regName, setRegName] = useState("");
  const [regPhone, setRegPhone] = useState("");
  const [regEmail, setRegEmail] = useState("");
  const [regPassword, setRegPassword] = useState("");

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await loginCustomer(loginPhone, loginPassword);
      if (res.success) {
        showToast("Heureux de vous revoir !", "success");
        router.push("/");
      }
    } catch (err: any) {
      showToast(err.message, "error");
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await registerCustomer({
        name: regName,
        phone: regPhone,
        email: regEmail,
        password: regPassword
      });
      if (res.success) {
        showToast("Bienvenue chez Zangochap !", "success");
        router.push("/");
      }
    } catch (err: any) {
      showToast(err.message, "error");
    }
  };

  return (
    <PublicLayout>
      <div className="flex justify-center px-6 py-[60px] pb-[100px] animate-[fadeUp_0.5s_ease] font-body">
        <div className="w-full max-w-[440px]">
          {/* HEADER */}
          <div className="text-center mb-10">
            <h1 className="text-2xl font-extralight tracking-[0.25em] text-[#1A1614] mb-3 uppercase">MON COMPTE</h1>
            <p className="text-[13px] text-[#999] leading-relaxed">Connectez-vous pour suivre vos commandes et profiter d'avantages exclusifs.</p>
          </div>

          {/* TAB SWITCHER */}
          <div className="flex border-b border-[#e8e8e4] mb-9">
            <button 
              className={`flex-1 bg-none border-none py-4 text-[11px] font-medium tracking-[0.15em] cursor-pointer relative transition-colors ${tab === "login" ? "text-[#1A1614]" : "text-[#bbb]"}`} 
              onClick={() => setTab("login")}
            >
              CONNEXION
              {tab === "login" && <span className="absolute -bottom-px left-[20%] right-[20%] h-0.5 bg-[#1A1614]" />}
            </button>
            <button 
              className={`flex-1 bg-none border-none py-4 text-[11px] font-medium tracking-[0.15em] cursor-pointer relative transition-colors ${tab === "register" ? "text-[#1A1614]" : "text-[#bbb]"}`} 
              onClick={() => setTab("register")}
            >
              CRÉER UN COMPTE
              {tab === "register" && <span className="absolute -bottom-px left-[20%] right-[20%] h-0.5 bg-[#1A1614]" />}
            </button>
          </div>

          {/* LOGIN FORM */}
          {tab === "login" && (
            <form onSubmit={handleLogin} className="flex flex-col gap-5.5 animate-[fadeUp_0.3s_ease]">
              <div className="space-y-2">
                <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">TÉLÉPHONE</label>
                <div className="flex items-center gap-3 border border-[#e8e8e4] px-4 h-[52px] transition-colors focus-within:border-[#1A1614] focus-within:text-[#1A1614] text-[#bbb]">
                  <Phone size={16} />
                  <input
                    type="tel"
                    value={loginPhone}
                    onChange={e => setLoginPhone(e.target.value)}
                    placeholder="07 00 00 00 00"
                    required
                    className="flex-1 border-none outline-none text-sm text-[#1A1614] bg-transparent font-inherit"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">MOT DE PASSE</label>
                <div className="flex items-center gap-3 border border-[#e8e8e4] px-4 h-[52px] transition-colors focus-within:border-[#1A1614] focus-within:text-[#1A1614] text-[#bbb]">
                  <Lock size={16} />
                  <input
                    type={showPassword ? "text" : "password"}
                    value={loginPassword}
                    onChange={e => setLoginPassword(e.target.value)}
                    placeholder="Votre mot de passe"
                    required
                    className="flex-1 border-none outline-none text-sm text-[#1A1614] bg-transparent font-inherit"
                  />
                  <button type="button" className="bg-none border-none cursor-pointer text-[#ccc] p-1 transition-colors hover:text-[#1A1614]" onClick={() => setShowPassword(!showPassword)}>
                    {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                  </button>
                </div>
              </div>

              <button type="submit" className="w-full h-[52px] bg-[#1A1614] text-white border-none text-[12px] font-semibold tracking-[0.15em] cursor-pointer flex items-center justify-center gap-2.5 mt-2 transition-all duration-350 hover:bg-[#333] hover:-translate-y-0.5 hover:shadow-[0_8_24px_rgba(0,0,0,0.1)]">
                SE CONNECTER <ArrowRight size={16} />
              </button>

              <button type="button" className="bg-none border-none text-[#999] text-[12px] cursor-pointer text-center transition-colors hover:text-[#1A1614] tracking-wide">Mot de passe oublié ?</button>
            </form>
          )}

          {/* REGISTER FORM */}
          {tab === "register" && (
            <form onSubmit={handleRegister} className="flex flex-col gap-5.5 animate-[fadeUp_0.3s_ease]">
              <div className="space-y-2">
                <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">NOM COMPLET</label>
                <div className="flex items-center gap-3 border border-[#e8e8e4] px-4 h-[52px] transition-colors focus-within:border-[#1A1614] focus-within:text-[#1A1614] text-[#bbb]">
                  <User size={16} />
                  <input
                    type="text"
                    value={regName}
                    onChange={e => setRegName(e.target.value)}
                    placeholder="Aminata Traoré"
                    required
                    className="flex-1 border-none outline-none text-sm text-[#1A1614] bg-transparent font-inherit"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">TÉLÉPHONE</label>
                <div className="flex items-center gap-3 border border-[#e8e8e4] px-4 h-[52px] transition-colors focus-within:border-[#1A1614] focus-within:text-[#1A1614] text-[#bbb]">
                  <Phone size={16} />
                  <input
                    type="tel"
                    value={regPhone}
                    onChange={e => setRegPhone(e.target.value)}
                    placeholder="07 00 00 00 00"
                    required
                    className="flex-1 border-none outline-none text-sm text-[#1A1614] bg-transparent font-inherit"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">EMAIL <span className="text-[#ccc] normal-case tracking-normal">(optionnel)</span></label>
                <div className="flex items-center gap-3 border border-[#e8e8e4] px-4 h-[52px] transition-colors focus-within:border-[#1A1614] focus-within:text-[#1A1614] text-[#bbb]">
                  <Mail size={16} />
                  <input
                    type="email"
                    value={regEmail}
                    onChange={e => setRegEmail(e.target.value)}
                    placeholder="email@exemple.com"
                    className="flex-1 border-none outline-none text-sm text-[#1A1614] bg-transparent font-inherit"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-medium tracking-[0.12em] text-[#999] uppercase">MOT DE PASSE</label>
                <div className="flex items-center gap-3 border border-[#e8e8e4] px-4 h-[52px] transition-colors focus-within:border-[#1A1614] focus-within:text-[#1A1614] text-[#bbb]">
                  <Lock size={16} />
                  <input
                    type={showPassword ? "text" : "password"}
                    value={regPassword}
                    onChange={e => setRegPassword(e.target.value)}
                    placeholder="Créer un mot de passe"
                    required
                    minLength={6}
                    className="flex-1 border-none outline-none text-sm text-[#1A1614] bg-transparent font-inherit"
                  />
                  <button type="button" className="bg-none border-none cursor-pointer text-[#ccc] p-1 transition-colors hover:text-[#1A1614]" onClick={() => setShowPassword(!showPassword)}>
                    {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                  </button>
                </div>
              </div>

              <button type="submit" className="w-full h-[52px] bg-[#1A1614] text-white border-none text-[12px] font-semibold tracking-[0.15em] cursor-pointer flex items-center justify-center gap-2.5 mt-2 transition-all duration-350 hover:bg-[#333] hover:-translate-y-0.5 hover:shadow-[0_8_24px_rgba(0,0,0,0.1)]">
                CRÉER MON COMPTE <ArrowRight size={16} />
              </button>
            </form>
          )}

          {/* ADVANTAGES */}
          <div className="mt-[60px] pt-10 border-t border-[#f0f0f0]">
            <h3 className="text-[11px] font-normal tracking-[0.2em] text-[#bbb] text-center mb-7 uppercase">POURQUOI CRÉER UN COMPTE ?</h3>
            <div className="flex flex-col gap-5">
              <div className="flex items-center gap-4 p-5 border border-[#f0f0f0] text-[#1A1614]">
                <ShoppingBag size={20} strokeWidth={1.3} />
                <div>
                  <strong className="block text-[13px] font-medium mb-0.5">Suivi de commandes</strong>
                  <span className="text-[12px] text-[#aaa]">Suivez vos achats en temps réel</span>
                </div>
              </div>
              <div className="flex items-center gap-4 p-5 border border-[#f0f0f0] text-[#1A1614]">
                <MapPin size={20} strokeWidth={1.3} />
                <div>
                  <strong className="block text-[13px] font-medium mb-0.5">Adresses sauvegardées</strong>
                  <span className="text-[12px] text-[#aaa]">Commandez plus rapidement</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

    </PublicLayout>
  );
}

