  const hasGoogleAnalytics = isGoogleAnalyticsId(googleAnalyticsId);
  const hasFacebookPixel = isFacebookPixelId(facebookPixelId);

  return (
    <html lang="fr" className={cn("font-sans", geist.variable)} suppressHydrationWarning>
      <head>
