            <span style={{ color: 'var(--line)' }}>→</span>
            <input 
              type="date" 
              style={selectStyle}
              value={currentFilters.dateTo || ''} 
              onChange={e => updateFilters({ dateTo: e.target.value })}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

import React from "react";
import prisma from "@/lib/prisma";
import Topbar from "@/components/Topbar";
import { TableCard, StatCard } from "@/components/UI";
import { formatPrice, STATUS_LABELS } from "@/lib/constants";
import { getSession } from "@/modules/auth/actions";
import TopProductsFilters from "./TopProductsFilters";

export const dynamic = "force-dynamic";

export default async function TopProductsPage({
  searchParams
}: {
  searchParams: Promise<{
    commercialId?: string,
    type?: string,
    status?: string,
    dateFrom?: string,
    dateTo?: string
  }>
}) {
  const user = await getSession();
  if (user?.role !== 'admin' && user?.role !== 'developer') {
    return <div className="content"><div className="empty"><h4>Accès refusé</h4></div></div>;
  }

  const { commercialId, type, status, dateFrom, dateTo } = await searchParams;

  const where: any = {};
  if (commercialId) where.commercialId = commercialId;
  if (type) where.type = type;
  if (status) where.status = status;
  else where.status = { not: 'CANCELLED' };

  if (dateFrom || dateTo) {
    where.createdAt = {};
    if (dateFrom) where.createdAt.gte = new Date(dateFrom);
    if (dateTo) where.createdAt.lte = new Date(dateTo + 'T23:59:59');
  }

  const orders = await prisma.order.findMany({
    where,
    include: { items: true },
  });

  const commercials = await prisma.user.findMany({
    where: { role: 'COMMERCIAL' },
    select: { id: true, name: true }
  });

  // Get distinct types and statuses for filters
  const allTypes = ['Standard', 'Echange', 'Vente Directe', 'Stock'];

  // Aggregate product sales
  const salesMap = new Map<string, { name: string; emoji: string; totalQty: number; totalRevenue: number; orderCount: Set<string> }>();
  for (const order of orders) {
    for (const item of order.items) {
      const key = item.name;
      if (!salesMap.has(key)) {
        salesMap.set(key, { name: item.name, emoji: item.emoji || '📦', totalQty: 0, totalRevenue: 0, orderCount: new Set() });
      }
      const data = salesMap.get(key)!;
      data.totalQty += item.qty;
      data.totalRevenue += item.price * item.qty;
      data.orderCount.add(order.id);
    }
  }

  const sorted = Array.from(salesMap.values())
    .map(d => ({ ...d, orderCount: d.orderCount.size }))
    .sort((a, b) => b.totalRevenue - a.totalRevenue);

  const totalRevenue = sorted.reduce((s, p) => s + p.totalRevenue, 0);
  const totalQty = sorted.reduce((s, p) => s + p.totalQty, 0);

  return (
    <>
      <Topbar title="Top" subtitle="produits" />
      <div className="content animate-fade-in">
        <div className="stats-grid" style={{ marginBottom: 24 }}>
          <StatCard label="Revenu généré" value={formatPrice(totalRevenue)} accent />
          <StatCard label="Articles vendus" value={totalQty} />
          <StatCard label="Produits uniques" value={sorted.length} />
          <StatCard label="Commandes incluses" value={orders.length} />
        </div>

        <TopProductsFilters
          commercials={commercials}
          types={allTypes}
          statuses={Object.entries(STATUS_LABELS)}
          currentFilters={{ commercialId, type, status, dateFrom, dateTo }}
        />

        <TableCard title="Classement des ventes" meta={`${sorted.length} produits trouvés`}>
          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Produit</th>
                <th style={{ textAlign: 'center' }}>Qté</th>
                <th style={{ textAlign: 'right' }}>Revenu</th>
                <th style={{ textAlign: 'center' }}>Commandes</th>
                <th>Performance</th>
              </tr>
            </thead>
            <tbody>
              {sorted.length === 0 ? (
                <tr><td colSpan={6} style={{ textAlign: 'center', padding: 40, color: 'var(--brown-soft)' }}>Aucune donnée pour ces filtres</td></tr>
              ) : sorted.slice(0, 50).map((p, i) => {
                const pct = totalRevenue > 0 ? Math.round(p.totalRevenue / totalRevenue * 100) : 0;
                return (
                  <tr key={i}>
                    <td>
                      <div style={{ width: 24, height: 24, borderRadius: '50%', background: i < 3 ? 'var(--orange)' : 'var(--cream-2)', color: i < 3 ? 'white' : 'var(--brown)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, fontSize: 11 }}>
                        {i + 1}
                      </div>
                    </td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span style={{ fontSize: 18 }}>{p.emoji}</span>
                        <span className="cell-strong">{p.name}</span>
                      </div>
                    </td>
                    <td style={{ textAlign: 'center' }}><strong>{p.totalQty}</strong></td>
                    <td style={{ textAlign: 'right' }}><span className="cell-price">{formatPrice(p.totalRevenue)}</span></td>
                    <td style={{ textAlign: 'center' }}>{p.orderCount}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                        <div style={{ flex: 1, height: 6, borderRadius: 3, background: 'var(--cream-2)', minWidth: 60 }}>
                          <div style={{ width: `${Math.min(pct, 100)}%`, height: '100%', borderRadius: 3, background: 'var(--orange)' }} />
                        </div>
                        <span style={{ fontSize: 11, fontWeight: 700, width: 35 }}>{pct}%</span>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </TableCard>
      </div>
    </>
  );
}

import React from "react";
import prisma from "@/lib/prisma";
import { StatCard, TableCard, EmptyState } from "@/components/UI";
import Topbar from "@/components/Topbar";
import { shouldShowInCollectionQueue } from "@/modules/logistics/collection/helpers";
import "./dashboard.css";

export default async function CollectionDashboard({ user }: { user: any }) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const orders = await prisma.order.findMany({
    where: { deletedAt: null, status: { notIn: ["CANCELLED", "DELIVERED"] } },
    include: { items: true },
    orderBy: { createdAt: "desc" },
  });
  const products = await prisma.product.findMany({ include: { variants: true, supplier: true } });
  const productMap = new Map(products.map(p => [p.id, p]));

  const toCollect: Array<{ order: any; item: any; product: any }> = [];
  for (const order of orders) {
    for (const item of order.items) {
      if (!item.productId) {
        toCollect.push({
          order,
          item,
          product: { id: "CUSTOM", name: item.name, supplier: null, variants: [], stock: 0, isCustom: true },
        });
        continue;
      }
      const product = productMap.get(item.productId);
      if (!product) continue;
      if (shouldShowInCollectionQueue(order, item, product)) toCollect.push({ order, item, product });
    }
  }

  const allRecords = await prisma.collectionRecord.findMany({
    orderBy: { createdAt: "desc" },
  });
  const myRecords = allRecords.filter(r => r.byName === user.name);
  const myToday = myRecords.filter(r => new Date(r.createdAt) >= today);
  const myCollected = myRecords.filter(r => r.status === "collected");
  const myUnavailable = myRecords.filter(r => r.status === "unavailable");
  const myAlternative = myRecords.filter(r => r.status === "alternative");
  const teamCollected = allRecords.filter(r => r.status === "collected");

  return (
    <>
      <Topbar title="Bord" subtitle="collecte" />
      <div className="content animate-fade-in">
        <div className="stats-grid">
          <StatCard label="Collectes du jour" value={myToday.filter(r => r.status === "collected").length} trend={`${myCollected.length} au total`} accent />
          <StatCard label="Alternatives" value={myAlternative.length} color="var(--blue)" trend="Solutions trouvees" />
          <StatCard label="Non collectes" value={myUnavailable.length} color="var(--red)" trend="Indispos fournisseur" trendDir="down" />
          <StatCard
            label="Taux de collecte"
            value={`${myRecords.length ? Math.round((myCollected.length / myRecords.length) * 100) : 0}%`}
            trend="Mes performances"
            trendDir="up"
          />
        </div>

        <div className="stats-grid" style={{ marginTop: 16 }}>
          <StatCard label="File collecte" value={toCollect.length} color="var(--amber)" />
          <StatCard label="Equipe collecte" value={teamCollected.length} color="var(--green)" />
        </div>

        <TableCard
          title="A collecter chez les fournisseurs"
          meta={`${toCollect.length} article(s) en manque`}
          actions={<a href="/zangochap-manager/logistics/collection" className="btn-primary-sm">Tout voir</a>}
        >
          {toCollect.length === 0 ? (
            <EmptyState icon="OK" title="Tout est en stock" description="Aucune collecte necessaire." />
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Commande</th>
                  <th>Produit</th>
                  <th>Variation</th>
                  <th>Fournisseur</th>
                </tr>
              </thead>
              <tbody>
                {toCollect.slice(0, 6).map(({ order, item, product }, i) => (
                  <tr key={i}>
                    <td>
                      <span className="cell-mono">{order.ref}</span>
                      <div className="cell-muted">{order.customerName}</div>
                    </td>
                    <td><span className="cell-strong">{item.name}</span></td>
                    <td>
                      <span className="size-dot">{item.size}</span>{" "}
                      <strong style={{ fontSize: 11 }}>{item.color}</strong> x {item.qty}
                    </td>
                    <td><strong>{product.supplier?.name || "-"}</strong></td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </TableCard>
      </div>
    </>
  );
}

import React from "react";
import prisma from "@/lib/prisma";
import { StatCard, TableCard, StatusBadge, SectionLabel, EmptyState } from "@/components/UI";
import { formatPrice, formatDay } from "@/lib/constants";
import Link from "next/link";
import Topbar from "@/components/Topbar";
import "./dashboard.css";

export default async function PackingDashboard({ user }: { user: any }) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Orders to pack (confirmed)
  const toPack = await prisma.order.findMany({
    where: { deletedAt: null, status: 'CONFIRMED' },
    include: { items: true },
    orderBy: { createdAt: 'asc' },
  });

  // My packed orders
  const myPacked = await prisma.order.findMany({
    where: { deletedAt: null, packedByName: user.name, status: { in: ['PACKED', 'PARTIAL', 'DELIVERED'] } },
    include: { items: true },
    orderBy: { packedAt: 'desc' },
  });

  const myPackedToday = myPacked.filter(o => o.packedAt && new Date(o.packedAt) >= today);
  const myPartial = myPacked.filter(o => o.status === 'PARTIAL');

  // Total queue
  const allPacked = await prisma.order.count({ where: { deletedAt: null, status: { in: ['PACKED', 'PARTIAL'] } } });

  return (
    <>
      <Topbar title="Bord" subtitle="emballage" />
      <div className="content animate-fade-in">
        <SectionLabel>Mes statistiques personnelles</SectionLabel>
        <div className="stats-grid">
          <StatCard label="Emballé (jour)" value={myPackedToday.length} trend={`${myPacked.length} au total`} accent />
          <StatCard label="En file d'attente" value={toPack.length} color="var(--amber)" trend="À emballer" trendDir="down" />
          <StatCard label="Emballage partiel" value={myPartial.length} color="var(--blue)" />
          <StatCard
            label="Mon taux de réussite"
            value={`${myPacked.length ? Math.round((myPacked.length - myPartial.length) / myPacked.length * 100) : 0}%`}
            trend="Complètement emballé"
            trendDir="up"
          />
        </div>

        <SectionLabel spaced>Vue globale du service</SectionLabel>
        <div className="stats-grid">
          <StatCard label="Total emballés" value={allPacked} />
          <StatCard label="En attente" value={toPack.length} color="var(--amber)" />
        </div>

        <TableCard
          title="File d'attente — À emballer"
          meta={`${toPack.length} commande(s)`}
          actions={<Link href="/zangochap-manager/logistics/packing" className="btn-primary-sm">Commencer →</Link>}
        >
          {toPack.length === 0 ? (
            <EmptyState icon="✓" title="Tout est emballé" description="La file est vide." />
          ) : (
            <table>
              <thead>
                <tr><th>Réf.</th><th>Articles</th><th>Commune</th><th>Statut</th><th>Créé le</th></tr>
              </thead>
              <tbody>
                {toPack.slice(0, 6).map(order => (
                  <tr key={order.id}>
                    <td>
                      <span className="cell-mono">{order.ref}</span>
                      <div className="cell-muted">{order.customerName}</div>
                    </td>
                    <td>
                      {order.items.map((item, i) => (
                        <div key={i} style={{ fontSize: 11, display: 'flex', alignItems: 'center', gap: 4, margin: '2px 0' }}>
                          <span>{item.emoji || '📦'}</span>
                          <span>{item.name}</span>
                          <span className="size-dot">{item.size}</span>
                          <strong style={{ fontSize: 10 }}>{item.color}</strong>
                          <span>× {item.qty}</span>
                        </div>
                      ))}
                    </td>
                    <td><span className="cell-muted">{order.commune || '—'}</span></td>
                    <td><StatusBadge status={order.status} /></td>
                    <td><span className="cell-muted">{formatDay(order.createdAt)}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </TableCard>
      </div>
    </>
  );
}

import React from "react";
import prisma from "@/lib/prisma";
import { StatCard, TableCard, StatusBadge, SectionLabel, EmptyState } from "@/components/UI";
import { formatPrice, formatDay } from "@/lib/constants";
import Topbar from "@/components/Topbar";
import "./dashboard.css";

export default async function StockDashboard({ user }: { user: any }) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const products = await prisma.product.findMany({
    include: { createdBy: true, variants: true, supplier: true },
    orderBy: { createdAt: 'desc' },
  });

  const totalProducts = products.length;
  const totalUnits = products.reduce((s, p) => s + p.stock, 0);
  const oos = products.filter(p => p.stock === 0);
  const low = products.filter(p => p.stock > 0 && p.stock < 5);

  // Personal stats
  const myProducts = products.filter(p => p.createdBy.name === user.name);
  const myProductsToday = myProducts.filter(p => new Date(p.createdAt) >= today);

  return (
    <>
      <Topbar title="Bord" subtitle="stock" />
      <div className="content animate-fade-in">
        <SectionLabel>Mes statistiques personnelles</SectionLabel>
        <div className="stats-grid">
          <StatCard label="Produits ajoutés (jour)" value={myProductsToday.length} trend={`${myProducts.length} au total`} accent />
          <StatCard label="Mes unités gérées" value={myProducts.reduce((s, p) => s + p.stock, 0)} />
        </div>

        <SectionLabel spaced>Vue globale du catalogue</SectionLabel>
        <div className="stats-grid">
          <StatCard label="Produits référencés" value={totalProducts} />
          <StatCard label="Unités en stock" value={totalUnits} />
          <StatCard label="Stock faible" value={low.length} color="var(--amber)" trend="Moins de 5 unités" trendDir="down" />
          <StatCard label="En rupture" value={oos.length} color="var(--red)" />
        </div>

        <TableCard
          title="Catalogue produits"
          actions={<a href="/zangochap-manager/products/new" className="btn-orange">+ Ajouter un produit</a>}
        >
          {products.length === 0 ? (
            <EmptyState icon="📦" title="Aucun produit" description="Commencez par ajouter un produit." />
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Produit</th>
                  <th>Prix</th>
                  <th>Variations</th>
                  <th>Fournisseur</th>
                  <th>Stock</th>
                </tr>
              </thead>
              <tbody>
                {products.slice(0, 8).map((p) => (
                  <tr key={p.id}>
                    <td>
                      <div className="cell-strong">{p.name}</div>
                      <div className="cell-muted">{p.material || '—'}</div>
                    </td>
                    <td><span className="cell-price">{formatPrice(Number(p.price))}</span></td>
                    <td><span className="cell-muted">{p.variants.length} variante(s)</span></td>
                    <td><span className="cell-muted">{p.supplier?.name || '—'}</span></td>
                    <td>
                      <strong style={{
                        color: p.stock === 0 ? 'var(--red)' : p.stock < 5 ? 'var(--amber)' : 'var(--green)'
                      }}>{p.stock}</strong>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </TableCard>
      </div>
    </>
  );
}

import React from "react";
import Topbar from "@/components/Topbar";
import AdminDashboard from "./AdminDashboard";
import CommercialDashboard from "./CommercialDashboard";
import PackingDashboard from "./PackingDashboard";
import CollectionDashboard from "./CollectionDashboard";
import StockDashboard from "./StockDashboard";
import { getSession } from "@/modules/auth/actions";

export const dynamic = "force-dynamic";

const GREETINGS: Record<string, string> = {
  commercial: "bord commercial",
  packing: "bord emballage",
  collection: "bord collecte",
  stock: "bord stock",
  admin: "bord admin",
};

export default async function DashboardPage() {
  const user = await getSession();
  const firstName = user?.name?.split(' ')[0] || '';
  const subtitle = user?.role ? (GREETINGS[user.role] || 'bord') : 'bord';

  const dashboards: Record<string, any> = {
    admin: AdminDashboard,
    commercial: CommercialDashboard,
    packing: PackingDashboard,
    collection: CollectionDashboard,
    stock: StockDashboard,
  };

  if (user?.role?.toUpperCase() === 'LIVREUR') {
    const { redirect } = await import("next/navigation");
    redirect("/zangochap-rider");
  }

  if (user?.role?.toUpperCase() === 'COMPTABLE') {
    const { redirect } = await import("next/navigation");
    redirect("/zangochap-manager/accounting");
  }

  if (user?.role?.toUpperCase() === 'POINT_RELAIS') {
    const { redirect } = await import("next/navigation");
    redirect("/zangochap-manager/boutique");
  }

  const DashboardView = user?.role ? (dashboards[user.role] || AdminDashboard) : AdminDashboard;

  const serializedUser = JSON.parse(JSON.stringify(user));

  return (
    <DashboardView user={serializedUser} />
  );
}

