                            <span className="font-extrabold text-[10px] uppercase tracking-wider block">Fichier validé avec succès !</span>
                            <span className="font-mono text-[9px] text-indigo-600 block mt-0.5">Origine : {modal.data.fileName}</span>
                          </div>
                        </div>
