  Link as LinkIcon,
  Pencil,
  Pin,
  PinOff,
  Plus,
  RefreshCcw,
  StickyNote,
  Trash2,
  X,
} from "lucide-react";
import { useToast } from "@/components/Toast";
import { playReminderAlarmSound, showBrowserNotification } from "@/lib/client-alerts";
import { cn } from "@/lib/utils";
import {
  deleteMyStaffNote,
  getMyStaffNotes,
  patchMyStaffNote,
  upsertMyStaffNote,
} from "@/modules/notes/actions";
