              <Link href="/downloads" className="no-underline text-[#1A1614] text-base font-normal py-4 border-b border-gray-100 tracking-wider transition-all hover:pl-2 flex items-center gap-2" onClick={() => setMobileOpen(false)}><Smartphone size={17} /> Application</Link>
              <Link href="/cart" className="no-underline text-[#1A1614] text-base font-normal py-4 border-b border-gray-100 tracking-wider transition-all hover:pl-2" onClick={() => setMobileOpen(false)}>Mon Panier ({itemCount})</Link>
              <div className="mt-auto pt-8">
                <a href="tel:+2250757330000" className="flex items-center gap-2.5 no-underline text-gray-400 text-[13px]"><Phone size={16} /> Service Client</a>
              </div>
            </div>
          </div>
        )}
      </nav>
    </>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { formatPrice } from "@/lib/constants";
import { Product } from "@/lib/types";
import { useCart } from "@/lib/CartContext";
import { ShoppingBag, Check } from "lucide-react";
import { getImageUrl } from "@/lib/utils";
import PublicVariantModal from "./PublicVariantModal";
import { useRouter } from "next/navigation";

export default function ProductCard({ p }: { p: Product }) {
  const { addToCart } = useCart();
  const router = useRouter();
  const [added, setAdded] = useState(false);
  const [modalType, setModalType] = useState<"cart" | "buy" | null>(null);

  const discount = p.oldPrice ? Math.round((1 - Number(p.price) / Number(p.oldPrice)) * 100) : 0;
  // Produit sans choix a faire (une seule variante) : on evite le modal et on
  // agit directement, exactement comme un vrai "ajout rapide".
  const soleVariant = p.variants?.length === 1 ? p.variants[0] : null;

  const doAddToCart = (variant: any, qty: number) => {
    addToCart({
      productId: p.id,
      variantId: variant.id,
      name: p.name,
      price: Number(p.price),
      qty,
      size: variant.size,
      color: variant.color,
      image: getImageUrl(variant.image || p.images?.[0]?.url),
    });
    setModalType(null);
    setAdded(true);
    setTimeout(() => setAdded(false), 2000);
  };

  const handleBuyNow = (variant: any, qty: number) => {
    sessionStorage.setItem("zangochap_buy_now", JSON.stringify({
      productId: p.id,
      variantId: variant.id,
      name: p.name,
      price: Number(p.price),
      qty,
      size: variant.size,
      color: variant.color,
      image: getImageUrl(variant.image || p.images?.[0]?.url),
    }));
    setModalType(null);
    router.push("/cart?buyNow=1");
  };

  const handleQuickAdd = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (soleVariant) doAddToCart(soleVariant, 1);
    else setModalType("cart");
  };

  const handleBuyClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (soleVariant) handleBuyNow(soleVariant, 1);
    else setModalType("buy");
  };

  return (
    <article className="group block relative no-underline text-inherit">
      <Link href={`/product/${p.slug || p.id}`} className="block relative aspect-[3.5/4.5] bg-[#F7F6F3] overflow-hidden mb-4 rounded-sm">
        {p.images?.[0] ? (
          <img
            src={getImageUrl(p.images[0].url)}
            alt={p.name}
            loading="lazy"
            className="w-full h-full object-cover transition-transform duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:scale-105"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-4xl font-extralight text-[#D5D0C8]">Z</div>
        )}

        {discount > 0 && (
          <div className="absolute top-3 left-3 bg-[#D4541C] text-white px-2 py-1 text-[10px] font-extrabold rounded-sm">
            -{discount}%
          </div>
        )}

        <div className="absolute bottom-0 left-0 right-0 bg-white/90 text-[#1A1614] py-3 text-center text-[10px] font-extrabold tracking-widest translate-y-full transition-transform duration-300 group-hover:translate-y-0">
          VOIR LES DÉTAILS
        </div>
      </Link>

      <div className="px-1">
        <span className="text-[9px] font-bold text-[#D4541C] uppercase tracking-widest mb-1.5 block">
          {p.category?.name || 'Mode'}
        </span>
        <h3 className="text-sm font-normal text-[#333] mb-1.5 whitespace-nowrap overflow-hidden text-overflow-ellipsis">
          {p.name}
        </h3>
        <div className="flex items-center gap-2">
          <span className="text-sm font-bold text-[#1A1614]">{formatPrice(Number(p.price))}</span>
          {p.oldPrice && (
            <span className="text-xs text-[#AAA] line-through">{formatPrice(Number(p.oldPrice))}</span>
          )}
        </div>
        <div className="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2">
          <button
            onClick={handleQuickAdd}
            disabled={!p.variants?.length}
            className={`min-h-10 border px-2 text-[10px] font-bold tracking-[0.1em] transition-colors ${added ? "border-[#2D8A4E] bg-[#2D8A4E] text-white" : "border-[#1A1614] bg-white text-[#1A1614] hover:bg-[#1A1614] hover:text-white"
              }`}
          >
            <span className="inline-flex items-center gap-1.5">
              {added ? <Check size={13} /> : <ShoppingBag size={13} />} Ajouter au panier
            </span>
          </button>
          <button
            onClick={handleBuyClick}
            disabled={!p.variants?.length}
            className="min-h-10 bg-[#D4541C] px-2 text-[10px] font-bold tracking-[0.1em] text-white transition-colors hover:bg-[#B33D0E]"
          >
            Acheter
          </button>
        </div>
      </div>
      <PublicVariantModal
        product={modalType ? p : null}
        onClose={() => setModalType(null)}
        onConfirm={modalType === "buy" ? handleBuyNow : doAddToCart}
        title={modalType === "buy" ? "Acheter ce produit" : "Choisir la variante"}
        actionLabel={modalType === "buy" ? "Acheter" : "Valider le panier"}
      />
    </article>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import { X } from "lucide-react";
import { HomeCmsContent } from "@/modules/cms/types";

export default function PublicPopup({ content }: { content: HomeCmsContent }) {
  const [open, setOpen] = React.useState(false);

  React.useEffect(() => {
    if (!content.popupEnabled) return;

    const storageKey = `zangochap_popup_seen_${popupSignature(content)}`;
    if (content.popupFrequency === "session" && sessionStorage.getItem(storageKey)) return;
    if (content.popupFrequency === "once" && localStorage.getItem(storageKey)) return;

    const delay = Math.max(0, Number.parseInt(content.popupDelayMs, 10) || 0);

    const timer = window.setTimeout(() => {
      setOpen(true);
      if (content.popupFrequency === "session") sessionStorage.setItem(storageKey, "1");
      if (content.popupFrequency === "once") localStorage.setItem(storageKey, "1");
    }, delay);

    return () => window.clearTimeout(timer);
  }, [content.popupDelayMs, content.popupEnabled, content.popupFrequency, content.popupTitle]);

  if (!content.popupEnabled || !open) return null;

  const theme = getTheme(content.popupTheme);
  const shellClass = getShellClass(content.popupPosition);
  const sizeClass = getSizeClass(content.popupSize);
  const hasImage = content.popupShowImage && Boolean(content.popupImage);

  return (
    <div className={`fixed inset-0 z-[1200] flex bg-black/55 px-4 py-6 backdrop-blur-sm ${shellClass}`}>
      <div className={`relative w-full overflow-hidden rounded-lg shadow-2xl ${theme.card} ${sizeClass}`}>
        <button
          type="button"
          onClick={() => setOpen(false)}
          className={`absolute right-3 top-3 z-10 flex h-9 w-9 items-center justify-center rounded-full shadow-sm transition ${theme.close}`}
          aria-label="Fermer la popup"
        >
          <X size={18} />
        </button>

        <div className={hasImage ? "grid md:grid-cols-[0.95fr_1.05fr]" : "grid"}>
          {hasImage && (
            <div className="relative min-h-[220px] bg-[#1A1614]">
              <img
                src={content.popupImage}
                alt={content.popupTitle}
                className="h-full min-h-[220px] w-full object-cover"
              />
            </div>
          )}

          <div className="flex min-h-[280px] flex-col justify-center p-7 md:p-10">
            {content.popupEyebrow && (
              <span className={`mb-3 text-[10px] font-extrabold uppercase tracking-[0.28em] ${theme.eyebrow}`}>
                {content.popupEyebrow}
              </span>
            )}
            <h2 className={`mb-4 font-display text-[28px] font-black uppercase leading-none md:text-[38px] ${theme.title}`}>
              {content.popupTitle}
            </h2>
            <p className={`mb-7 text-sm leading-relaxed md:text-[15px] ${theme.text}`}>
              {content.popupDescription}
            </p>
            <div className="flex flex-wrap items-center gap-3">
              {content.popupButtonLabel && (
                <Link
                  href={content.popupButtonHref || "/shop"}
                  onClick={() => setOpen(false)}
                  className={`inline-flex w-fit items-center justify-center rounded px-6 py-3 text-[11px] font-extrabold uppercase tracking-[0.16em] transition ${theme.primary}`}
                >
                  {content.popupButtonLabel}
                </Link>
              )}
              {content.popupSecondaryLabel && (
                content.popupSecondaryHref ? (
                  <Link
                    href={content.popupSecondaryHref}
                    onClick={() => setOpen(false)}
                    className={`inline-flex w-fit items-center justify-center rounded px-5 py-3 text-[11px] font-extrabold uppercase tracking-[0.16em] transition ${theme.secondary}`}
                  >
                    {content.popupSecondaryLabel}
                  </Link>
                ) : (
                  <button
                    type="button"
                    onClick={() => setOpen(false)}
                    className={`inline-flex w-fit items-center justify-center rounded px-5 py-3 text-[11px] font-extrabold uppercase tracking-[0.16em] transition ${theme.secondary}`}
                  >
                    {content.popupSecondaryLabel}
                  </button>
                )
              )}
            </div>
            {content.popupCloseLabel && (
              <button
                type="button"
                onClick={() => setOpen(false)}
                className={`mt-5 w-fit text-[11px] font-bold underline-offset-4 hover:underline ${theme.closeText}`}
              >
                {content.popupCloseLabel}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function popupSignature(content: HomeCmsContent) {
  const value = `${content.popupTitle}:${content.popupButtonHref}:${content.popupDescription}:${content.popupFrequency}`;
  let hash = 0;

  for (let index = 0; index < value.length; index += 1) {
    hash = ((hash << 5) - hash + value.charCodeAt(index)) | 0;
  }

  return Math.abs(hash).toString(36);
}

function getShellClass(position: string) {
  if (position === "bottom-right") return "items-end justify-end";
  if (position === "bottom-center") return "items-end justify-center";
  return "items-center justify-center";
}

function getSizeClass(size: string) {
  if (size === "small") return "max-w-[520px]";
  if (size === "large") return "max-w-[920px]";
  return "max-w-[760px]";
}

function getTheme(theme: string) {
  if (theme === "dark") {
    return {
