export async function restoreSystemBackupAction(fileName: string) {
  await ensureAuth(["developer"]);
  try {
    ensureBackupDirectory();
    const { safeName, filePath } = resolveBackupFile(fileName);

    if (!fs.existsSync(filePath)) {
      return { success: false, error: "Fichier de sauvegarde introuvable." };
    }

    const parsed = JSON.parse(fs.readFileSync(filePath, "utf-8"));
    if (!parsed.metadata || !parsed.tables) {
      return { success: false, error: "Structure de sauvegarde invalide ou corrompue." };
    }

    const { tables } = parsed;

    // Fetch existing users to validate foreign keys that point to Users
    const existingUsers = await prisma.user.findMany({ select: { id: true } });
    const existingUserIds = new Set(existingUsers.map(u => u.id));
    const fallbackUser = existingUsers[0]?.id;

    if (!fallbackUser) {
      return { success: false, error: "Aucun utilisateur trouvé en base. Impossible d'assigner les relations sans utilisateur." };
    }

    await prisma.$transaction(async (tx) => {
      // 1. Suppression dans l'ordre pour respecter les clés étrangères
      await tx.orderItem.deleteMany();
      await tx.collectionRecord.deleteMany();
      await tx.order.deleteMany();
      await tx.stockMovement.deleteMany();
      await tx.stockLevel.deleteMany();
      await tx.productImage.deleteMany();
      await tx.productVariant.deleteMany();
      await tx.product.deleteMany();
      await tx.customer.deleteMany();
      await tx.promoUsage.deleteMany();
      await tx.promoCode.deleteMany();
      // On ne supprime pas les Users pour garder les accès.

      // 2. Restauration des données
      const customerIdMap = new Map<string, string>();
      const uniqueCustomers: BackupCustomerInput[] = [];
      const phoneSet = new Set<string>();

      if (tables.customers?.length) {
        for (const c of tables.customers) {
          const phoneStr = c.phone || `0000-${c.id}`;
          if (phoneSet.has(phoneStr)) {
            const keptCustomer = uniqueCustomers.find(uc => (uc.phone || `0000-${uc.id}`) === phoneStr);
            if (keptCustomer) {
              customerIdMap.set(c.id, keptCustomer.id);
            }
          } else {
            phoneSet.add(phoneStr);
            uniqueCustomers.push(c);
            customerIdMap.set(c.id, c.id);
          }
        }
        await tx.customer.createMany({ data: uniqueCustomers, skipDuplicates: true });
      }

      let anonymousCustomerId = null;
      
      if (tables.promos?.length) {
        await tx.promoCode.createMany({ data: tables.promos, skipDuplicates: true });
      }

      if (tables.categories?.length) {
        await tx.category.createMany({ data: tables.categories, skipDuplicates: true });
      }

      if (tables.warehouses?.length) {
        await tx.warehouse.createMany({ data: tables.warehouses, skipDuplicates: true });
      }

      if (tables.products?.length) {
        const flatProducts = [];
        const flatVariants = [];
        const flatImages = [];

        for (const p of tables.products) {
          const { variants, images, subCategoryId, supplierId, ...productData } = p;
          
          if (productData.creatorId && !existingUserIds.has(productData.creatorId)) {
            productData.creatorId = fallbackUser;
          }
          
          flatProducts.push(productData);
          
          if (variants?.length) {
            for (const v of variants) {
              const { stockLevels, stockMovements, orderItems, ...variantData } = v;
              flatVariants.push(variantData);
            }
          }
          
          if (images?.length) {
            flatImages.push(...images);
          }
        }

        await tx.product.createMany({ data: flatProducts, skipDuplicates: true });
        if (flatVariants.length) {
          await tx.productVariant.createMany({ data: flatVariants, skipDuplicates: true });
        }
        if (flatImages.length) {
          await tx.productImage.createMany({ data: flatImages, skipDuplicates: true });
        }
      }

      if (tables.orders?.length) {
        const flatOrders = [];
        const flatItems = [];

        for (const o of tables.orders) {
          const { items, ...orderData } = o;
          
          if (!orderData.customerId || !customerIdMap.has(orderData.customerId)) {
            if (!anonymousCustomerId) {
              anonymousCustomerId = `anon-${Date.now()}`;
              await tx.customer.create({
                data: { id: anonymousCustomerId, name: "Client Inconnu (Backup)", phone: `0000000000-${Date.now()}` }
              });
            }
            orderData.customerId = anonymousCustomerId;
          } else {
            orderData.customerId = customerIdMap.get(orderData.customerId);
          }

          if (orderData.commercialId && !existingUserIds.has(orderData.commercialId)) {
            orderData.commercialId = fallbackUser;
          }
          if (orderData.deliverymanId && !existingUserIds.has(orderData.deliverymanId)) {
            orderData.deliverymanId = fallbackUser;
          }
          
          flatOrders.push(orderData);
          
          if (items?.length) {
            flatItems.push(...items);
          }
        }

        await tx.order.createMany({ data: flatOrders, skipDuplicates: true });
        if (flatItems.length) {
          await tx.orderItem.createMany({ data: flatItems, skipDuplicates: true });
        }
      }

      if (tables.stockMovements?.length) {
        await tx.stockMovement.createMany({ data: tables.stockMovements, skipDuplicates: true });
      }

      if (tables.settlements?.length) {
        const safeSettlements = tables.settlements.map((s: any) => ({
          ...s,
          deliverymanId: existingUserIds.has(s.deliverymanId) ? s.deliverymanId : fallbackUser
        }));
        await tx.settlement.createMany({ data: safeSettlements, skipDuplicates: true });
      }
    }, {
      maxWait: 10000,
      timeout: 120000 // 2 minutes to allow large backup restoration
    });

    await recordDeveloperAudit("backup.restore", "success", { fileName: safeName });
    return {
      success: true,
      message: "Restauration effectuée avec succès ! Les données ont été remplacées.",
    };
  } catch (error: unknown) {
    const message = getErrorMessage(error);
    await recordDeveloperAudit("backup.restore", "failure", { fileName, error: message });
    return { success: false, error: message || "Impossible de restaurer la sauvegarde." };
  }
}

"use client"; // Refresh v1

import React, { useTransition, useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { TableCard, EmptyState, LocationBadge, DetailCard, SectionLabel } from "@/components/UI";
import { useToast } from "@/components/Toast";
import { markCollection } from "@/modules/logistics/collection/actions";
import { updateProductVariants } from "@/modules/products/actions";
import { useRouter } from "next/navigation";
import { Check, X, ArrowLeftRight, Package, Warehouse, Search, ChevronRight, Filter, Edit2 } from "lucide-react";
import Modal from "@/components/Modal";
import { useResponsiveMode } from "@/lib/hooks";
import LogisticsMobileStyles from "@/modules/logistics/components/LogisticsMobileStyles";
import { motion, AnimatePresence } from "framer-motion";
import VariantsEditorModal from "../packing/components/VariantsEditorModal";
import { getCollectionStockLevel, hasAlternativeProposalForItem, shouldShowInCollectionQueue } from "./helpers";

type DatePreset = 'today' | 'yesterday' | 'custom' | 'all';

function toLocalDateInputValue(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

const isCollectionHistoryAction = (action: string) =>
  action.includes('collection_status:') ||
  action.includes('collecté') ||
  action.includes('indisponible');

const isCollectedAction = (action: string) =>
  action.includes('collection_status:collected') ||
  (action.includes('collecté') && !action.includes('alternative'));

const isUnavailableAction = (action: string) =>
  action.includes('collection_status:unavailable') || action.includes('indisponible');

const isAlternativeAction = (action: string) =>
  action.includes('collection_status:alternative') || action.includes('alternative');

export default function CollectionClient({ toCollect, user, categories = [], warehouses = [] }: { toCollect: any[]; user: any; categories?: any[]; warehouses?: any[] }) {
  const [isPending, startTransition] = useTransition();
  const [editingVariants, setEditingVariants] = useState<any>(null);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // Filters State
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [categoryId, setCategoryId] = useState('all');
  const [warehouseId, setWarehouseId] = useState('all');
  const todayStr = toLocalDateInputValue();
  const [dateFrom, setDateFrom] = useState(todayStr);
  const [dateTo, setDateTo] = useState(todayStr);
  const [datePreset, setDatePreset] = useState<DatePreset>('today');

  const { showToast } = useToast();
  const router = useRouter();
  const { isMobile, isReady: isViewportReady } = useResponsiveMode();

  // Auto-refresh every 10s — real-time sync for call center
  useEffect(() => {
    const interval = setInterval(() => {
      if (document.visibilityState === 'visible') {
        router.refresh();
      }
    }, 10000);
    return () => clearInterval(interval);
  }, [router]);

  const handleMark = (orderId: string, productId: string, status: string, orderItemId?: string, note?: string) => {
    startTransition(async () => {
      try {
        await markCollection({ orderId, productId, status, orderItemId, note });
        const labels: Record<string, string> = {
          collected: 'Marqué collecté ✓',
          unavailable: 'Marqué indisponible',
          alternative: 'Alternative notée',
        };
        showToast(labels[status] || 'Fait', 'success');
        router.refresh();
      } catch (e: any) {
        console.error('Collection Action Error:', e);
        showToast(e?.message || 'Une erreur est survenue lors du marquage', 'error');
      }
    });
  };

  const applyDatePreset = (preset: DatePreset) => {
    setDatePreset(preset);
    if (preset === 'custom') return;
    const now = new Date();
    const today = toLocalDateInputValue(now);
    if (preset === 'today') { setDateFrom(today); setDateTo(today); }
    else if (preset === 'yesterday') {
      const yest = new Date(); yest.setDate(now.getDate() - 1);
      const d = toLocalDateInputValue(yest); setDateFrom(d); setDateTo(d);
    } else { setDateFrom(''); setDateTo(''); }
  };

  const handleDateFromChange = (value: string) => {
    setDatePreset('custom');
    setDateFrom(value);
  };

  const handleDateToChange = (value: string) => {
    setDatePreset('custom');
    setDateTo(value);
  };

  const processedData = React.useMemo(() => {
    const counts = { all: 0, collected: 0, unavailable: 0, alternative: 0 };
    const filtered = toCollect.filter(tc => {
      const h = Array.isArray(tc.order.history) ? tc.order.history : [];
      const relevantLogs = h.filter((log: any) => {
        const action = (log.action || '').toLowerCase();
        const hasIdTag = action.includes(`[item_id:${tc.item.id.toLowerCase()}]`);
        const hasNameMatch = action.includes((tc.item.name || '').toLowerCase());

        return isCollectionHistoryAction(action) && (hasIdTag || hasNameMatch);
      }).sort((a: any, b: any) => new Date(b.at).getTime() - new Date(a.at).getTime());

      const latestLog = relevantLogs[0];
      const latestAction = (latestLog?.action || '').toLowerCase();
      const hasCollected = isCollectedAction(latestAction);
      const hasUnavailable = isUnavailableAction(latestAction);
      const hasAlternative = isAlternativeAction(latestAction);

      const needsCollection = shouldShowInCollectionQueue(tc.order, tc.item, tc.product);
      const isProcessed = !!latestLog;

      if (!isProcessed && !needsCollection) return false;
      if (!isProcessed) counts.all++;
      else {
        if (hasCollected) counts.collected++;
        if (hasUnavailable) counts.unavailable++;
        if (hasAlternative) counts.alternative++;
      }

      if (filter === 'all') { if (isProcessed) return false; }
      else {
        if (filter === 'collected' && !hasCollected) return false;
        if (filter === 'unavailable' && !hasUnavailable) return false;
        if (filter === 'alternative' && !hasAlternative) return false;
      }

      if (categoryId !== 'all' && tc.product.categoryId !== categoryId) return false;
      if (warehouseId !== 'all') {
        const hasInWarehouse = tc.product.variants.some((v: any) =>
          v.size === tc.item.size && v.color === tc.item.color &&
          v.stockLevels?.some((sl: any) => sl.warehouseId === warehouseId)
        );
        if (!hasInWarehouse) return false;
      }
      if (search) {
        const s = search.toLowerCase();
        const matches = tc.order.ref.toLowerCase().includes(s) ||
          tc.item.name.toLowerCase().includes(s) ||
          tc.order.customerName.toLowerCase().includes(s);
        if (!matches) return false;
      }
      if (dateFrom || dateTo) {
        const orderDate = new Date(tc.order.createdAt);
        if (dateFrom && orderDate < new Date(dateFrom + 'T00:00:00')) return false;
        if (dateTo && orderDate > new Date(dateTo + 'T23:59:59.999')) return false;
      }
      return true;
    });
    return { filtered, counts };
  }, [toCollect, filter, search, categoryId, warehouseId, dateFrom, dateTo]);

  const { filtered: filteredToCollect, counts } = processedData;

  const stats = {
    total: toCollect.length,
    filtered: filteredToCollect.length
  };

  const viewMotion = {
    initial: { opacity: 0, y: 12, scale: 0.985 },
    animate: { opacity: 1, y: 0, scale: 1 },
    transition: { duration: 0.24, ease: [0.22, 1, 0.36, 1] },
  } as const;

  if (!isViewportReady) {
    return (
      <>
        <LogisticsMobileStyles />
        <motion.div className="content logistics-responsive-pending" {...viewMotion}>
          Chargement de l&apos;interface...
        </motion.div>
      </>
    );
  }

  if (isMobile) {
    return (
      <>
        <motion.div key="collection-mobile" className="logistics-mobile-root logistics-view-mobile !bg-[#F4F5F7]" {...viewMotion}>
          <LogisticsMobileStyles />
          <div className="bg-white px-3.5 py-3 border-b border-[#E5E7EB] shadow-[0_1px_0_rgba(17,24,39,0.02)] shrink-0">
            <div className="flex items-start justify-between gap-3 mb-3">
              <div>
                <h1 className="m-0 text-[18px] leading-[1.15] font-black text-[#111827] tracking-normal">Collecte</h1>
                <div className="mt-0.5 text-[11px] text-[#6B7280] font-semibold">File terrain et suivi fournisseur</div>
              </div>
              <div className="inline-flex min-h-[22px] items-center rounded-md bg-[#FFF7ED] px-2 py-1 text-[10px] font-extrabold text-[#9A3412]">{stats.filtered} / {stats.total}</div>
            </div>
            <div className="grid grid-cols-3 gap-2 mb-3">
              <div className="min-w-0 rounded-lg border border-[#E5E7EB] bg-[#F9FAFB] px-2.5 py-2">
                <span className="block text-[16px] leading-none font-black text-[#111827]">{counts.all}</span>
                <span className="mt-1 block text-[9px] font-extrabold uppercase tracking-[0.04em] text-[#6B7280]">À traiter</span>
              </div>
              <div className="min-w-0 rounded-lg border border-[#E5E7EB] bg-[#F9FAFB] px-2.5 py-2">
                <span className="block text-[16px] leading-none font-black text-[#111827]">{counts.collected}</span>
                <span className="mt-1 block text-[9px] font-extrabold uppercase tracking-[0.04em] text-[#6B7280]">Collectés</span>
              </div>
              <div className="min-w-0 rounded-lg border border-[#E5E7EB] bg-[#F9FAFB] px-2.5 py-2">
                <span className="block text-[16px] leading-none font-black text-[#111827]">{counts.unavailable}</span>
                <span className="mt-1 block text-[9px] font-extrabold uppercase tracking-[0.04em] text-[#6B7280]">Indispos</span>
              </div>
            </div>
            <div className="mobile-search-bar">
              <Search size={16} style={{ position: 'absolute', left: 12, top: 12, color: '#AEAEB2' }} />
              <input
                type="text"
                placeholder="Réf, produit, client..."
                className="mobile-search-input"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>

            <div className="mobile-status-tabs">
              {[
                { id: 'all', label: 'À collecter' },
                { id: 'collected', label: 'Collectés' },
                { id: 'unavailable', label: 'Indispos' },
                { id: 'alternative', label: 'Alts' }
              ].map(t => (
                <button key={t.id} onClick={() => setFilter(t.id)} className={`status-tab ${filter === t.id ? 'active' : ''}`}>
                  {t.label} ({counts[t.id as keyof typeof counts]})
                </button>
              ))}
            </div>

            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              <select
                className="filter-select"
                value={warehouseId}
                onChange={e => setWarehouseId(e.target.value)}
                style={{ flex: 1, minWidth: '45%', height: 36, borderRadius: 10, background: '#F2F2F7', border: 'none', fontSize: 11, fontWeight: 600 }}
              >
                <option value="all">🏢 Entrepôts</option>
                {warehouses.map((w: any) => <option key={w.id} value={w.id}>{w.name}</option>)}
              </select>
              <select
                className="filter-select"
                value={categoryId}
                onChange={e => setCategoryId(e.target.value)}
                style={{ flex: 1, minWidth: '45%', height: 36, borderRadius: 10, background: '#F2F2F7', border: 'none', fontSize: 11, fontWeight: 600 }}
              >
                <option value="all">📁 Catégories</option>
                {categories.map((c: any) => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
              <div style={{ display: 'flex', gap: 4, width: '100%', background: '#F2F2F7', padding: 2, borderRadius: 10 }}>
                {[
                  { label: 'Auj.', val: 'today' },
                  { label: 'Hier', val: 'yesterday' },
                  { label: 'Perso', val: 'custom' },
                  { label: 'Tout', val: 'all' },
                ].map(d => (
                  <button key={d.val} onClick={() => applyDatePreset(d.val as DatePreset)} style={{ flex: 1, height: 32, borderRadius: 8, border: 'none', background: datePreset === d.val ? 'white' : 'transparent', fontSize: 10, fontWeight: 800 }}>
                    {d.label}
                  </button>
                ))}
              </div>
              {datePreset === 'custom' && (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, width: '100%' }}>
                  <input type="date" className="filter-date" value={dateFrom} onChange={e => handleDateFromChange(e.target.value)} style={{ minWidth: 0, height: 36, borderRadius: 10, border: 'none', background: '#F2F2F7', fontSize: 11 }} />
                  <input type="date" className="filter-date" value={dateTo} onChange={e => handleDateToChange(e.target.value)} style={{ minWidth: 0, height: 36, borderRadius: 10, border: 'none', background: '#F2F2F7', fontSize: 11 }} />
                </div>
              )}
            </div>
          </div>

          <div className="logistics-mobile-content !px-3 !py-3 !pb-24">
            <AnimatePresence mode="popLayout">
              {filteredToCollect.length === 0 ? (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ padding: '40px 0', textAlign: 'center' }}>
                  <Package size={48} style={{ margin: '0 auto 12px', opacity: 0.2 }} />
                  <p style={{ color: '#8E8E93', fontSize: 14 }}>Rien à collecter</p>
                </motion.div>
              ) : (
                filteredToCollect.map((tc, idx) => {
                  const h = Array.isArray(tc.order.history) ? tc.order.history : [];
                  const lastLog = h.filter((l: any) => {
                    const act = (l.action || '').toLowerCase();
                    const hasIdTag = act.includes(`[item_id:${tc.item.id.toLowerCase()}]`);
                    const hasNameMatch = act.includes((tc.item.name || '').toLowerCase());

                    return isCollectionHistoryAction(act) && (hasIdTag || hasNameMatch);
                  }).sort((a: any, b: any) => new Date(b.at).getTime() - new Date(a.at).getTime())[0];

                  const currentStatus = (lastLog?.action || '').toLowerCase();
                  const isCollected = isCollectedAction(currentStatus);
                  const isUnavailable = isUnavailableAction(currentStatus);
                  const isAlt = isAlternativeAction(currentStatus);

                  let altNote = '';
                  if (isAlt) {
                    const match = (lastLog?.action || '').match(/\(([^)]+)\)/);
                    altNote = match ? match[1] : '';
                  }
                  const stockLevel = getCollectionStockLevel(tc.item, tc.product);
                  const requestedQty = Number(tc.item.qty) || 1;
                  const projectedStock = stockLevel - requestedQty;
                  const hasAlternativeProposal = hasAlternativeProposalForItem(tc.order, tc.item);
                  const collectionReason = !tc.item.productId || tc.product.id === 'CUSTOM'
                    ? 'Produit personnalisé'
                    : hasAlternativeProposal
                      ? 'Alternative proposée'
                      : projectedStock <= 4
                        ? `Stock bas: ${Math.max(projectedStock, 0)} restant`
                        : 'À collecter';

                  return (
                    <motion.div
                      key={idx}
                      initial={{ opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: idx * 0.05 }}
                      className="mobile-card !mb-2.5 !overflow-hidden !rounded-lg !border-[#E5E7EB] !p-0 !shadow-[0_1px_2px_rgba(17,24,39,0.04)]"
                    >
                      <div style={{ display: 'flex', padding: '12px', gap: 14 }}>
                        {/* IMAGE LEFT */}
                        <div style={{ position: 'relative', flexShrink: 0 }}>
                          <div
                            onClick={(e) => { e.stopPropagation(); setPreviewImage(tc.item.image || tc.product.images?.[0]?.url); }}
                            style={{ width: 100, height: 100, background: '#F2F2F7', borderRadius: 14, overflow: 'hidden', border: '1px solid #E5E5EA' }}
                          >
                            {tc.item.image || tc.product.images?.[0]?.url ? (
                              <img src={tc.item.image || tc.product.images[0].url} style={{ width: '100%', height: '100%', objectFit: 'cover', opacity: (isCollected || isUnavailable) ? 0.5 : 1 }} alt="" />
                            ) : (
                              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', fontSize: 32 }}>{tc.item.emoji || '📦'}</div>
                            )}
                            <div style={{ position: 'absolute', bottom: 6, right: 6, background: 'rgba(0,0,0,0.4)', borderRadius: 6, padding: 4, backdropFilter: 'blur(2px)' }}>
                              <Search size={12} color="white" strokeWidth={3} />
                            </div>
                            {isCollected && <div style={{ position: 'absolute', inset: 0, background: 'rgba(52, 199, 89, 0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Check size={40} color="white" strokeWidth={4} /></div>}
                            {isUnavailable && <div style={{ position: 'absolute', inset: 0, background: 'rgba(255, 59, 48, 0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><X size={40} color="white" strokeWidth={4} /></div>}
                          </div>
                        </div>

                        {/* INFO RIGHT */}
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 4 }}>
                            <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 800, fontSize: 13, color: '#8E8E93' }}>{tc.order.ref}</div>
                            <div style={{ fontWeight: 900, fontSize: 18, color: 'var(--orange)' }}>x{tc.item.qty}</div>
                          </div>

                          <div style={{ fontWeight: 800, fontSize: 15, color: '#1C1C1E', marginBottom: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{tc.item.name}</div>
                          <div style={{ fontSize: 11, color: '#8E8E93', fontWeight: 600, marginBottom: 4 }}>{tc.order.customerName}</div>
                          <div className="mt-2 flex flex-wrap gap-1.5">
                            <span className="inline-flex min-h-[22px] max-w-full items-center rounded-md bg-[#FFF7ED] px-2 py-0.5 text-[10px] font-extrabold text-[#9A3412]">{collectionReason}</span>
                            {isCollected && <span className="inline-flex min-h-[22px] items-center rounded-md bg-[#ECFDF5] px-2 py-0.5 text-[10px] font-extrabold text-[#047857]">Collecté</span>}
                            {isUnavailable && <span className="inline-flex min-h-[22px] items-center rounded-md bg-[#FEF2F2] px-2 py-0.5 text-[10px] font-extrabold text-[#B91C1C]">Indisponible</span>}
                            {isAlt && <span className="inline-flex min-h-[22px] items-center rounded-md bg-[#EFF6FF] px-2 py-0.5 text-[10px] font-extrabold text-[#1D4ED8]">Alternative</span>}
                          </div>

                          <div style={{ display: 'flex', gap: 6, marginBottom: 8, flexWrap: 'wrap' }}>
                            {tc.order.commercialName && <span style={{ fontSize: 9, fontWeight: 700, background: '#E8F4FD', color: '#0A84FF', padding: '2px 6px', borderRadius: 6 }}>Comm: {tc.order.commercialName}</span>}
                            {lastLog?.byName && <span style={{ fontSize: 9, fontWeight: 700, background: '#F2FBF4', color: '#34C759', padding: '2px 6px', borderRadius: 6 }}>Coll: {lastLog.byName}</span>}
                            {tc.order.packedByName && <span style={{ fontSize: 9, fontWeight: 700, background: '#FFF1F2', color: '#FF3B30', padding: '2px 6px', borderRadius: 6 }}>Emb: {tc.order.packedByName}</span>}
                          </div>

                          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8 }}>
                            <span className="size-dot" style={{ background: '#1C1C1E', color: 'white', border: 'none' }}>{tc.item.size}</span>
                            <span style={{ fontSize: 12, color: '#8E8E93', fontWeight: 700 }}>{tc.item.color}</span>
                          </div>

                          {isAlt && altNote && (
                            <div style={{ background: 'var(--orange-soft)', padding: '4px 8px', borderRadius: 8, fontSize: 11, fontWeight: 700, color: 'var(--orange)', marginBottom: 8, display: 'inline-block' }}>
                              Alt: {altNote}
                            </div>
                          )}

                          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 8 }}>
                            {tc.product.variants.find((v: any) => v.size === tc.item.size && v.color === tc.item.color)?.stockLevels?.map((sl: any) => (
                              <div key={sl.id} style={{ fontSize: 10, background: '#F2F2F7', padding: '3px 8px', borderRadius: 6, display: 'flex', alignItems: 'center', gap: 4 }}>
                                <Warehouse size={10} color="#FF6B2C" />
                                <span style={{ fontWeight: 700 }}>{sl.position || sl.warehouse.name}</span>
                              </div>
                            ))}
                          </div>

                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div style={{ fontSize: 10, color: '#8E8E93', fontWeight: 600 }}>{tc.order.customerName}</div>
                            {tc.product.id !== 'CUSTOM' && (
                              <button
                                onClick={(e) => { e.stopPropagation(); setEditingVariants({ product: tc.product, variants: tc.product.variants }); }}
                                style={{
                                  background: 'var(--orange-soft)',
                                  border: 'none',
                                  borderRadius: 10,
                                  padding: '6px 12px',
                                  fontSize: 12,
                                  fontWeight: 800,
                                  color: 'var(--orange)',
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: 6,
                                  boxShadow: '0 2px 8px rgba(255, 107, 44, 0.15)'
                                }}
                              >
                                <Edit2 size={14} /> Stock
                              </button>
                            )}
                          </div>
                        </div>
                      </div>

                      <div style={{ display: 'flex', borderTop: '1px solid #E5E5EA' }}>
                        <button
                          onClick={() => handleMark(tc.order.id, tc.product.id, 'collected', tc.item.id)}
                          style={{
                            flex: 1.5, height: 50,
                            background: isCollected ? '#28a745' : '#34C759',
                            color: 'white', border: 'none', fontWeight: 800, fontSize: 12,
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                            opacity: isCollected ? 1 : 0.8,
                            borderTop: isCollected ? '3px solid #1e7e34' : 'none'
                          }}
                        >
                          <Check size={18} strokeWidth={3} /> {isCollected ? 'COLLECTÉ' : 'COLLECTÉ'}
                        </button>
                        <button
                          onClick={() => {
                            const note = window.prompt(`Alternative pour "${tc.item.name}" :`, altNote);
                            if (note) handleMark(tc.order.id, tc.product.id, 'alternative', tc.item.id, note);
                          }}
                          style={{
                            flex: 1, height: 50,
                            background: isAlt ? '#e68a00' : '#FF9500',
                            color: 'white', border: 'none', fontWeight: 800, fontSize: 11,
                            borderLeft: '1px solid rgba(255,255,255,0.2)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            borderTop: isAlt ? '3px solid #b36b00' : 'none'
                          }}
                        >
                          {isAlt ? 'ALT ⌥' : 'ALTER.'}
                        </button>
                        <button
                          onClick={() => handleMark(tc.order.id, tc.product.id, 'unavailable', tc.item.id)}
                          style={{
                            flex: 1, height: 50,
                            background: isUnavailable ? '#dc3545' : '#FF3B30',
                            color: 'white', border: 'none', fontWeight: 800, fontSize: 11,
                            borderLeft: '1px solid rgba(255,255,255,0.2)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            borderTop: isUnavailable ? '3px solid #bd2130' : 'none'
                          }}
                        >
                          {isUnavailable ? 'INDISP ✕' : 'INDISP.'}
                        </button>
                      </div>
                    </motion.div>
                  );
                })
              )}
            </AnimatePresence>
          </div>

          {/* LIGHTBOX PORTAL */}
          {previewImage && typeof document !== 'undefined' && createPortal(
            <div
              className="lightbox-overlay"
              onClick={() => setPreviewImage(null)}
              style={{ position: 'fixed', inset: 0, zIndex: 99999, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.92)', backdropFilter: 'blur(8px)' }}
            >
              <div className="lightbox-content animate-zoom-in" onClick={e => e.stopPropagation()} style={{ position: 'relative', maxWidth: '95%', maxHeight: '95%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <img src={previewImage} alt="Preview" style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain', borderRadius: 16, boxShadow: '0 20px 60px rgba(0,0,0,0.5)' }} />
                <button onClick={() => setPreviewImage(null)} style={{ position: 'absolute', top: 20, right: 20, background: 'rgba(255,255,255,0.2)', border: 'none', color: 'white', borderRadius: '50%', width: 44, height: 44, backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><X size={28} /></button>
              </div>
            </div>,
            document.body
          )}

          {editingVariants && (
            <VariantsEditorModal
              product={editingVariants.product}
              variants={editingVariants.variants}
              onClose={() => setEditingVariants(null)}
              onSave={(vars: any[]) => {
                showToast('Variantes mises à jour ✓', 'success');
                router.refresh();
                setEditingVariants(null);
              }}
            />
          )}
        </motion.div>
      </>
    );
  }

  return (
    <motion.div key="collection-desktop" className="content logistics-view-desktop" {...viewMotion}>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16, marginBottom: 24 }}>
        <div className="stat-card" style={{ background: 'white', padding: 20, borderRadius: 16, border: '1px solid var(--line)', display: 'flex', alignItems: 'center', gap: 16 }}>
          <div style={{ width: 44, height: 44, borderRadius: 12, background: 'var(--orange-soft)', color: 'var(--orange)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Package size={22} /></div>
          <div>
            <div style={{ fontSize: 11, color: 'var(--brown-soft)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.04em' }}>Articles à collecter</div>
            <div style={{ fontSize: 24, fontWeight: 800 }}>{stats.filtered} <span style={{ fontSize: 14, color: 'var(--brown-soft)', fontWeight: 400 }}>/ {stats.total}</span></div>
          </div>
        </div>
      </div>

      <div className="command-center" style={{ background: 'white', borderRadius: 16, border: '1px solid var(--line)', marginBottom: 24, padding: '12px 16px', display: 'flex', flexDirection: 'column', gap: 12 }}>
        <div style={{ display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: 4, background: 'var(--cream)', padding: 4, borderRadius: 10, border: '1px solid var(--line)' }}>
            {[{ id: 'all', label: 'À collecter', color: 'var(--orange)' }, { id: 'collected', label: 'Collectés', color: 'var(--green)' }, { id: 'unavailable', label: 'Indispos', color: 'var(--red)' }, { id: 'alternative', label: 'Alts', color: 'var(--blue)' }].map(t => (
              <button key={t.id} onClick={() => setFilter(t.id)} className={`shortcut-btn ${filter === t.id ? 'active' : ''}`} style={{ padding: '6px 12px', fontSize: 11, color: filter === t.id ? t.color : 'var(--brown-soft)', background: filter === t.id ? 'white' : 'transparent' }}>
                {t.label} <span style={{ opacity: 0.6, marginLeft: 2 }}>({counts[t.id as keyof typeof counts]})</span>
              </button>
            ))}
          </div>
          <div style={{ position: 'relative', flex: 1, minWidth: 200 }}>
            <input type="text" className="field-input" placeholder="Rechercher réf, produit, client..." value={search} onChange={e => setSearch(e.target.value)} style={{ paddingLeft: 36, height: 38, borderRadius: 10, fontSize: 13, border: '1px solid var(--line)', background: 'var(--cream-soft)' }} />
            <div style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', opacity: 0.4 }}><Package size={14} /></div>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap', paddingTop: 8, borderTop: '1px solid var(--cream-2)' }}>
          <select className="filter-select" value={categoryId} onChange={e => setCategoryId(e.target.value)} style={{ minWidth: 140, height: 34, fontSize: 12 }}><option value="all">📁 Catégories</option>{categories.map((c: any) => <option key={c.id} value={c.id}>{c.name}</option>)}</select>
          <select className="filter-select" value={warehouseId} onChange={e => setWarehouseId(e.target.value)} style={{ minWidth: 140, height: 34, fontSize: 12 }}><option value="all">🏢 Entrepôts</option>{warehouses.map((w: any) => <option key={w.id} value={w.id}>{w.name}</option>)}</select>
          <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginLeft: 'auto', flexWrap: 'wrap', justifyContent: 'flex-end' }}>
            <div style={{ display: 'flex', gap: 4, background: 'var(--cream)', padding: 3, borderRadius: 10, border: '1px solid var(--line)' }}>
              {[
                { label: "Aujourd'hui", val: 'today' },
                { label: 'Hier', val: 'yesterday' },
                { label: 'Perso', val: 'custom' },
                { label: 'Tout', val: 'all' },
              ].map(d => (
                <button key={d.val} className={`shortcut-btn ${datePreset === d.val ? 'active' : ''}`} onClick={() => applyDatePreset(d.val as DatePreset)}>
                  {d.label}
                </button>
              ))}
            </div>
            {datePreset === 'custom' && (
              <>
                <input type="date" className="filter-date" value={dateFrom} onChange={e => handleDateFromChange(e.target.value)} style={{ height: 34, fontSize: 11 }} />
                <span style={{ opacity: 0.3, fontSize: 10 }}>→</span>
                <input type="date" className="filter-date" value={dateTo} onChange={e => handleDateToChange(e.target.value)} style={{ height: 34, fontSize: 11 }} />
              </>
            )}
          </div>
        </div>
      </div>

      <TableCard title={`${filteredToCollect.length} produit(s)`}>
        {filteredToCollect.length === 0 ? <EmptyState icon="🔍" title="Aucun résultat" description="Essayez de modifier vos filtres." /> : (
          <table>
            <thead><tr><th>Commande</th><th>Produit</th><th>Variation</th><th>Qté</th><th>Emplacement</th><th>Actions</th></tr></thead>
            <tbody>{filteredToCollect.map((tc, i) => <CollectionRow key={i} {...tc} isPending={isPending} onMark={handleMark} onPreview={setPreviewImage} onEditStock={() => setEditingVariants({ product: tc.product, variants: tc.product.variants })} />)}</tbody>
          </table>
        )}
      </TableCard>

      {/* LIGHTBOX PORTAL (DESKTOP) */}
      {previewImage && typeof document !== 'undefined' && createPortal(
        <div className="lightbox-overlay" onClick={() => setPreviewImage(null)} style={{ position: 'fixed', inset: 0, zIndex: 99999, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.9)', backdropFilter: 'blur(5px)', cursor: 'zoom-out' }}>
          <img src={previewImage} style={{ maxWidth: '90%', maxHeight: '90%', objectFit: 'contain', borderRadius: 12, boxShadow: '0 20px 60px rgba(0,0,0,0.5)' }} alt="Zoomed" />
        </div>,
        document.body
      )}

      {editingVariants && <VariantsEditorModal product={editingVariants.product} variants={editingVariants.variants} onClose={() => setEditingVariants(null)} onSave={(vars: any[]) => { showToast('Variantes mises à jour ✓', 'success'); router.refresh(); setEditingVariants(null); }} />}
    </motion.div>
  );
}

function CollectionRow({ order, item, product, isPending, onMark, onPreview, onEditStock }: any) {
  const h = Array.isArray(order.history) ? order.history : [];
  const collector = h.filter((l: any) => {
    const act = (l.action || '').toLowerCase();
    const hasIdTag = act.includes(`[item_id:${item.id.toLowerCase()}]`);
    const hasNameMatch = act.includes((item.name || '').toLowerCase());

    return isCollectionHistoryAction(act) && (hasIdTag || hasNameMatch);
  }).sort((a: any, b: any) => new Date(b.at).getTime() - new Date(a.at).getTime())[0];

  return (
    <tr>
      <td>
        <div className="cell-mono" style={{ fontWeight: 800 }}>{order.ref}</div>
        <div className="cell-muted" style={{ fontSize: 11 }}>{order.customerName}</div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2, marginTop: 4 }}>
          {order.commercialName && <span style={{ fontSize: 9, fontWeight: 700, color: '#0A84FF' }}>Comm: {order.commercialName}</span>}
          {collector?.byName && <span style={{ fontSize: 9, fontWeight: 700, color: '#34C759' }}>Coll: {collector.byName}</span>}
          {order.packedByName && <span style={{ fontSize: 9, fontWeight: 700, color: '#FF3B30' }}>Emb: {order.packedByName}</span>}
        </div>
      </td>
      <td>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div onClick={() => onPreview(item.image || product.images?.[0]?.url)} style={{ width: 44, height: 44, background: 'var(--cream-2)', borderRadius: 10, overflow: 'hidden', border: '1px solid var(--line)', cursor: 'zoom-in' }}>
            {item.image || product.images?.[0]?.url ? <img src={item.image || product.images[0].url} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : (item.emoji || '📦')}
          </div>
          <div><span className="cell-strong" style={{ fontSize: 13 }}>{item.name}</span><div style={{ fontSize: 10, color: 'var(--brown-soft)' }}>{product.category?.name}</div></div>
        </div>
      </td>
      <td><span className="size-dot">{item.size}</span> <strong style={{ fontSize: 12 }}>{item.color}</strong></td>
      <td><strong style={{ fontSize: 14 }}>x{item.qty}</strong></td>
      <td>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          {product.variants.find((v: any) => v.size === item.size && v.color === item.color)?.stockLevels?.map((sl: any) => (
            <div key={sl.id} style={{ fontSize: 9, background: 'var(--cream-2)', padding: '2px 6px', borderRadius: 4, display: 'flex', alignItems: 'center', gap: 4 }}><Warehouse size={10} className="text-orange" /><span>{sl.warehouse.name}</span>{sl.position && <span style={{ fontWeight: 800 }}>• {sl.position}</span>}</div>
          ))}
        </div>
      </td>
      <td style={{ width: 120 }}>
        <div className="row-actions">
          <button className="action-btn" onClick={() => onMark(order.id, product.id, 'collected', item.id)} style={{ background: 'var(--green-soft)', color: 'var(--green)' }} title="Collecté"><Check size={16} /></button>
          <button className="action-btn" onClick={() => { const note = window.prompt(`Alternative pour "${item.name}" :`); if (note) onMark(order.id, product.id, 'alternative', item.id, note); }} style={{ background: 'var(--orange-soft)', color: 'var(--orange)' }} title="Alternative"><ArrowLeftRight size={16} /></button>
          <button className="action-btn" onClick={() => onMark(order.id, product.id, 'unavailable', item.id)} style={{ background: 'var(--red-soft)', color: 'var(--red)' }} title="Indisponible"><X size={16} /></button>
          {product.id !== 'CUSTOM' && (
            <button className="action-btn" onClick={onEditStock} style={{ background: 'var(--cream)', color: 'var(--brown-soft)' }} title="Modifier Stock"><Edit2 size={16} /></button>
          )}
        </div>
      </td>
    </tr>
  );
}

"use server";

import prisma from "@/lib/prisma";
import { ensureAuth } from "@/lib/auth";
import { revalidatePath } from "next/cache";
import type { Prisma } from "@prisma/client";
import { restockVariant } from "@/modules/orders/actions/stock";
import { buildCollectionItems, getCollectionLabel } from "./helpers";
import { MarkCollectionSchema } from "./types";

type OrderHistoryEntry = {
  at?: string;
  action: string;
  by?: string;
  byName?: string;
};

export async function getCollectionRecords(filters?: { byName?: string }) {
  await ensureAuth(["admin", "collection", "point_relais"]);
  const where: Prisma.CollectionRecordWhereInput = {};
  if (filters?.byName) where.byName = filters.byName;

  return prisma.collectionRecord.findMany({
    where,
    orderBy: { createdAt: "desc" },
  });
}

export async function markCollection(input: unknown) {
  const session = await ensureAuth(["admin", "collection", "point_relais"]);

  const parsed = MarkCollectionSchema.safeParse(input);
  if (!parsed.success) {
    throw new Error("Donnees de collecte invalides.");
  }

  const { orderId, productId, status, orderItemId, note } = parsed.data;

  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: { items: true },
  });
  if (!order) throw new Error("Commande introuvable");

  const orderItem = orderItemId ? order.items.find((item) => item.id === orderItemId) : null;
  const effectiveProductId = orderItem?.productId || (productId === "CUSTOM" ? null : productId);

  await prisma.$transaction(async (tx) => {
    await tx.collectionRecord.create({
      data: {
        orderId,
        productId,
        status,
        by: session.email,
        byName: session.name,
      },
    });

    let productName = productId;
    if (orderItem) {
      productName = orderItem.name;
    } else if (effectiveProductId) {
      const product = await tx.product.findUnique({ where: { id: effectiveProductId } });
      productName = product?.name || effectiveProductId;
    }

    const history = Array.isArray(order.history) ? [...(order.history as OrderHistoryEntry[])] : [];
    history.push({
      at: new Date().toISOString(),
      action: `${session.name} a ${getCollectionLabel(status, note)} [ITEM_ID:${orderItemId || ""}] : ${productName}`,
      by: session.email,
      byName: session.name,
    });

    await tx.order.update({
      where: { id: orderId },
      data: { history },
    });

    if (status !== "collected" || !effectiveProductId) return;

    const variant = orderItem?.variantId
      ? await tx.productVariant.findUnique({ where: { id: orderItem.variantId } })
      : orderItem
        ? await tx.productVariant.findFirst({
            where: {
              productId: effectiveProductId,
              size: orderItem.size,
              color: orderItem.color,
            },
          })
      : null;

    if (!variant) {
      await tx.product.update({
        where: { id: effectiveProductId },
        data: { stock: { increment: 1 } },
      });
      return;
    }

    const warehouse = await tx.warehouse.upsert({
      where: { name: "Entrepôt Principal" },
      update: {},
      create: { name: "Entrepôt Principal", location: "Siège Zangochap" },
    });
    await restockVariant({
      variantId: variant.id,
      warehouseId: warehouse.id,
      quantity: orderItem?.qty || 1,
      type: "RESTOCK",
      orderId,
      session,
      reason: `Collecte fournisseur: ${orderItem?.name || effectiveProductId}`,
    }, tx as any);
  });

  if (status === "collected" && effectiveProductId) {
    await notifyOrderIfFullyAvailable(orderId);
  }

  revalidateCollectionPaths();
  return { success: true };
}

export async function getItemsToCollect() {
  await ensureAuth(["admin", "collection", "point_relais"]);
  const orders = await prisma.order.findMany({
    where: { status: { notIn: ["CANCELLED", "DELIVERED"] } },
    include: { items: true },
  });

  const productIds = Array.from(
    new Set(orders.flatMap((order) => order.items.map((item) => item.productId)).filter(Boolean)),
  ) as string[];

  const products = productIds.length
    ? await prisma.product.findMany({
        where: { id: { in: productIds } },
        include: { variants: true },
      })
    : [];

  return buildCollectionItems(orders, products);
}

async function notifyOrderIfFullyAvailable(orderId: string) {
  const updatedOrder = await prisma.order.findUnique({
    where: { id: orderId },
    include: {
      items: {
        include: {
          product: { include: { variants: true } },
        },
      },
    },
  });

  if (!updatedOrder || updatedOrder.status !== "CONFIRMED") return;

  const allAvailable = updatedOrder.items.every((item) => {
    if (!item.productId) return true;
    const requestedQty = Number(item.qty) || 1;
    const variant = item.variantId
      ? item.product?.variants.find((v: any) => v.id === item.variantId)
      : item.product?.variants.find((v: any) => v.size === item.size && v.color === item.color);
    if (variant) return Number(variant.stock || 0) >= requestedQty;
    return Number(item.product?.stock || 0) >= requestedQty;
  });
  if (!allAvailable) return;

  const history = Array.isArray(updatedOrder.history) ? [...(updatedOrder.history as OrderHistoryEntry[])] : [];
  const alreadyNotified = history.some((entry) => entry.action.includes("disponibles (Auto)"));
  if (alreadyNotified) return;

  history.push({
    at: new Date().toISOString(),
    action: "Systeme : Tous les articles de la commande sont desormais disponibles en stock.",
    by: "system",
    byName: "Systeme Zango",
  });

  await prisma.order.update({
    where: { id: orderId },
    data: { history },
  });
}

function revalidateCollectionPaths() {
  revalidatePath("/zangochap-manager/logistics");
  revalidatePath("/zangochap-manager/logistics/packing");
  revalidatePath("/zangochap-manager/logistics/collection");
  revalidatePath("/zangochap-manager/orders");
  revalidatePath("/zangochap-manager/dashboard");
}

import { z } from "zod";

export const CollectionStatusSchema = z.enum(["collected", "unavailable", "alternative"]);

export const MarkCollectionSchema = z.object({
  orderId: z.string().min(1),
  productId: z.string().min(1),
  status: CollectionStatusSchema,
  orderItemId: z.string().min(1).optional(),
  note: z.string().trim().max(500).optional(),
});

export type CollectionStatus = z.infer<typeof CollectionStatusSchema>;
export type MarkCollectionInput = z.infer<typeof MarkCollectionSchema>;

export type CollectionPageData = {
  toCollect: CollectionItem[];
  user: unknown;
  categories: unknown[];
  warehouses: unknown[];
};

export type CollectionItem = {
  order: any;
  item: any;
  product: any;
};

"use client";

import React, { useState, useTransition, useMemo } from "react";
import { Printer, Check, CheckSquare, Square, Tag, RefreshCw, CheckCircle2, Repeat } from "lucide-react";
import { toggleLabelStatus, checkAllLabels } from "./actions";

interface OrderItemLabel {
  id: string;
  name: string;
  qty: number;
  image: string | null;
  emoji: string | null;
  size: string;
  color: string;
}

interface OrderLabel {
  id: string;
  ref: string;
  isLabeled: boolean;
  labeledAt: Date | null;
  labeledByName: string | null;
  createdAt: Date;
  items: OrderItemLabel[];
}

interface LabelsClientProps {
  initialOrders: OrderLabel[];
  currentUser: {
    name: string;
    role: string;
  };
}

export default function LabelsClient({ initialOrders, currentUser }: LabelsClientProps) {
  const [orders, setOrders] = useState<OrderLabel[]>(initialOrders);
  const [isPending, startTransition] = useTransition();
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);

  const totalCount = orders.length;
  const labeledCount = orders.filter((o) => o.isLabeled).length;
  const progressPercent = totalCount > 0 ? Math.round((labeledCount / totalCount) * 100) : 0;

  // Calculate frequencies of each ref
  const refCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    orders.forEach((o) => {
      counts[o.ref] = (counts[o.ref] || 0) + 1;
    });
    return counts;
  }, [orders]);

  const getDisplayRef = (ref: string) => {
    if (ref.startsWith("REPROGRAMME")) {
      return {
        prefix: "REPROG",
        code: ref.replace("REPROGRAMME", ""),
      };
    }
    if (ref.startsWith("ECHANGE")) {
      return {
        prefix: "ECHANGE",
        code: ref.replace("ECHANGE", ""),
      };
    }
    if (ref.startsWith("[SUPPRIMÉ] ")) {
      return {
        prefix: "SUPPRIMÉ",
        code: ref.replace("[SUPPRIMÉ] ", ""),
      };
    }
    return {
      prefix: null,
      code: ref,
    };
  };

  const handleToggle = (id: string, currentStatus: boolean) => {
    const nextStatus = !currentStatus;
    // Optimistic update
    setOrders((prev) =>
      prev.map((o) =>
        o.id === id
          ? {
              ...o,
              isLabeled: nextStatus,
              labeledAt: nextStatus ? new Date() : null,
              labeledByName: nextStatus ? currentUser.name : null,
            }
          : o
      )
    );

    startTransition(async () => {
      try {
        await toggleLabelStatus(id, nextStatus);
      } catch (error) {
        // Revert on failure
        setOrders((prev) =>
          prev.map((o) =>
            o.id === id
              ? {
                  ...o,
                  isLabeled: currentStatus,
                  labeledAt: o.labeledAt,
                  labeledByName: o.labeledByName,
                }
              : o
          )
        );
      }
    });
  };

  const handleCheckAll = (status: boolean) => {
    const orderIds = orders.map((o) => o.id);
    setOrders((prev) =>
      prev.map((o) => ({
        ...o,
        isLabeled: status,
        labeledAt: status ? new Date() : null,
        labeledByName: status ? currentUser.name : null,
      }))
    );

    startTransition(async () => {
      try {
        await checkAllLabels(orderIds, status);
      } catch (error) {
        // Refresh page or handle error
      }
    });
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="labels-module-container">
      {/* HEADER SECTION (Hidden during print) */}
      <div className="labels-no-print">
        <div className="labels-header">
          <div className="labels-title-area">
            <div className="labels-icon-box">
              <Tag size={24} className="text-[#FF6B2C]" />
            </div>
            <div>
              <h1 className="labels-title">Étiquettes du Jour</h1>
              <p className="labels-subtitle">
                Cochez les étiquettes imprimées ou vérifiées. Liste propre pour impression directe.
              </p>
            </div>
          </div>
          <div className="labels-actions">
            <button
              className="btn-secondary flex items-center gap-2"
              onClick={() => handleCheckAll(labeledCount < totalCount)}
              disabled={isPending || totalCount === 0}
              style={{ height: 42, borderRadius: 12, padding: "0 16px", fontSize: 13, fontWeight: 700 }}
            >
              {labeledCount < totalCount ? <CheckSquare size={18} /> : <Square size={18} />}
              {labeledCount < totalCount ? "Tout cocher" : "Tout décocher"}
            </button>
            <button
              className="btn-orange flex items-center gap-2"
              onClick={handlePrint}
              disabled={totalCount === 0}
              style={{
                height: 42,
                borderRadius: 12,
                padding: "0 20px",
                fontSize: 13,
                fontWeight: 800,
                boxShadow: "0 4px 12px rgba(255, 107, 44, 0.2)",
              }}
            >
              <Printer size={18} />
              Imprimer les Étiquettes
            </button>
          </div>
        </div>

        {/* PROGRESS BAR SECTION */}
        <div className="labels-progress-card">
          <div className="labels-progress-header">
            <div className="flex items-center gap-2">
              <CheckCircle2 size={18} className={progressPercent === 100 ? "text-emerald-500" : "text-[#FF6B2C]"} />
              <span className="labels-progress-title">Progression de l'étiquetage</span>
            </div>
            <span className="labels-progress-stats">
              {labeledCount} / {totalCount} étiquetées ({progressPercent}%)
            </span>
          </div>
          <div className="labels-progress-track">
            <div
              className={`labels-progress-bar ${progressPercent === 100 ? "bg-emerald-500" : "bg-[#FF6B2C]"}`}
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </div>
      </div>

      {/* PRINTABLE CONTENT: ONLY REFERENCES */}
      {totalCount === 0 ? (
        <div className="labels-empty labels-no-print">
          <Tag size={48} className="text-gray-300 mb-3" />
          <p>Aucune commande enregistrée pour cette journée.</p>
        </div>
      ) : (
        <div className="labels-grid">
          {orders.map((order) => {
            const count = refCounts[order.ref] || 1;
            const isRepeat = count > 1;
            const display = getDisplayRef(order.ref);
            return (
              <div
                key={order.id}
                onClick={() => handleToggle(order.id, order.isLabeled)}
                className={`label-tile ${order.isLabeled ? "labeled" : ""} ${isRepeat ? "repeated" : ""}`}
              >
                <div className="label-tile-top">
                  <div className="label-ref-container">
                    {display.prefix ? (
                      <div className="label-ref-split">
                        <span className="label-prefix">{display.prefix}</span>
                        <span className="label-code">{display.code}</span>
                      </div>
                    ) : (
                      <div className="label-ref">{order.ref}</div>
                    )}
                    {isRepeat && (
                      <>
                        <span className="repeat-badge labels-no-print" title={`Cette référence apparaît ${count} fois aujourd'hui`}>
                          <Repeat size={12} /> x{count}
                        </span>
                        <span className="print-repeat-badge">[🔄 x{count}]</span>
                      </>
                    )}
                  </div>
                  <div className="label-check-indicator labels-no-print">
                    {order.isLabeled ? (
                      <div className="label-checked-badge">
                        <Check size={14} className="text-white" />
                      </div>
                    ) : (
                      <div className="label-unchecked-box" />
                    )}
                  </div>
                </div>

                {/* ITEMS DISPLAY (Web only, hidden during print) */}
                {order.items && order.items.length > 0 && (
                  <div className="label-items-list labels-no-print">
                    {order.items.map((item) => (
                      <div key={item.id} className="label-item-row">
                        <div
                          className="label-item-img-box"
                          onClick={(e) => {
                            if (item.image) {
                              e.stopPropagation();
                              setLightboxImage(item.image);
                            }
                          }}
                          style={{ cursor: item.image ? "pointer" : "default" }}
                        >
                          {item.image ? (
                            <img src={item.image} alt={item.name} className="label-item-img" />
                          ) : (
                            <span className="label-item-emoji">{item.emoji || "📦"}</span>
                          )}
                        </div>
                        <div className="label-item-details">
                          <div className="label-item-name">{item.name}</div>
                          <div className="label-item-meta">
                            {item.size !== "-" && <span>Taille: {item.size}</span>}
                            {item.color !== "-" && <span>Couleur: {item.color}</span>}
                          </div>
                        </div>
                        <div className="label-item-qty">x{item.qty}</div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* STYLES FOR LABELS MODULE & PRINT */}
      <style jsx global>{`
        .labels-module-container {
          padding: 24px;
          max-width: 1400px;
          margin: 0 auto;
          width: 100%;
        }

        .labels-header {
          display: flex;
          align-items: center;
          justify-content: space-between;
          margin-bottom: 24px;
          gap: 16px;
          flex-wrap: wrap;
        }

        .labels-title-area {
          display: flex;
          align-items: center;
          gap: 16px;
        }

        .labels-icon-box {
          width: 48px;
          height: 48px;
          background: rgba(255, 107, 44, 0.1);
          border-radius: 14px;
          display: flex;
          align-items: center;
          justify-content: center;
        }

