"use client";

import React, { useState, useMemo, useTransition, useEffect, useRef, useCallback } from "react";
import { createPortal } from "react-dom";
import { TableCard } from "@/components/UI";
import { useToast } from "@/components/Toast";
import { addOrderHistoryEntry } from "@/modules/orders/actions";
import { updateOrderStatus } from "@/modules/orders/actions/status-actions";
import { useRouter, useSearchParams } from "next/navigation";
import { Check, Package, X, Search } from "lucide-react";
import { markItemNotPacked, toggleItemPacking } from "@/modules/logistics/verification/actions";
import { useResponsiveMode } from "@/lib/hooks";
import LogisticsMobileStyles from "@/modules/logistics/components/LogisticsMobileStyles";
import { motion, AnimatePresence } from "framer-motion";
import PackingOrderModal from "./components/PackingOrderModal";
import VariantsEditorModal from "./components/VariantsEditorModal";
import PackingItem from "./components/PackingItem";
import { PackingOrder, PackingOrderItem, PackingProductVariant, PackingUser, ProductWithVariants } from "./types";
import "./packing.css";

// --- HOOKS ---
type DatePreset = 'today' | 'yesterday' | 'custom' | 'all';

const STATUS_FILTERS = [
  { key: 'CONFIRMED', label: 'Confirmées' },
  { key: 'PREPARING', label: 'Suivies' },
  { key: 'NOT_PACKED', label: 'Pas emballées' },
  { key: 'ALTERNATIVE', label: 'Alternatives' },
  { key: 'PARTIAL', label: 'Part. emballées' },
  { key: 'UNAVAILABLE', label: 'Indisponibles' },
  { key: 'PACKED', label: 'Emballées' },
  { key: 'all', label: 'Toutes' },
] as const;

function toLocalDateInputValue(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/**
 * Hook pour la gestion du polling stabilisé
 */
function usePackingPolling(initialOrders: PackingOrder[], initialProducts: ProductWithVariants[], savingCount: number) {
  const [orders, setOrders] = useState<PackingOrder[]>(initialOrders);
  const [products, setProducts] = useState<ProductWithVariants[]>(initialProducts);
  const savingCountRef = useRef(savingCount);

  useEffect(() => {
    savingCountRef.current = savingCount;
  }, [savingCount]);

  useEffect(() => {
    if (savingCountRef.current === 0) {
      setOrders(initialOrders);
      setProducts(initialProducts);
    }
  }, [initialOrders, initialProducts]);

  useEffect(() => {
    const controller = new AbortController();

    const poll = async () => {
      try {
        // Ne pas rafraîchir si on est en train de sauvegarder
        if (savingCountRef.current > 0) return;

        const res = await fetch('/api/orders/packing', {
          cache: 'no-store',
          signal: controller.signal,
        });
        if (res.ok) {
          const json = await res.json();
          if (Array.isArray(json.orders)) {
            setOrders(json.orders);
          }
          if (Array.isArray(json.products)) {
            setProducts(json.products);
          }
        }
      } catch (e: unknown) {
        if (e instanceof Error && e.name === 'AbortError') return;
      }
    };

    poll();
    const interval = setInterval(poll, 20000);
    return () => {
      clearInterval(interval);
      controller.abort();
    };
  }, []);

  return { orders, setOrders, products };
}

/**
 * Hook pour la gestion des filtres et du tri performant
 */
function usePackingFilters(orders: PackingOrder[], products: ProductWithVariants[], searchParams: URLSearchParams) {
  const [filter, setFilter] = useState(searchParams.get('status') || 'CONFIRMED');
  const [search, setSearch] = useState('');
  const today = toLocalDateInputValue();
  const [dateFrom, setDateFrom] = useState(today);
  const [dateTo, setDateTo] = useState(today);
  const [warehouseFilter, setWarehouseFilter] = useState('all');
  const [datePreset, setDatePreset] = useState<DatePreset>('today');

  // Indexation des variantes pour lookup O(1)
  const variantWarehouseMap = useMemo(() => {
    const map = new Map<string, string[]>();
    products.forEach((p) => {
      p.variants?.forEach((v) => {
        const key = `${p.id}_${v.size}_${v.color}`;
        map.set(key, v.stockLevels?.flatMap((sl) => sl.warehouse?.name ? [sl.warehouse.name] : []) || []);
      });
    });
    return map;
  }, [products]);

  // Pré-parsing des dates pour éviter new Date() dans le loop
  const timeRange = useMemo(() => {
    return {
      from: dateFrom ? new Date(dateFrom).getTime() : null,
      to: dateTo ? new Date(dateTo + 'T23:59:59').getTime() : null
    };
  }, [dateFrom, dateTo]);

  const filtered = useMemo(() => {
    const s = search.toLowerCase();

    return orders
      .filter((o) => {
        // Filtre Statut / Alternative
        if (filter === 'ALTERNATIVE') {
          if (o.status !== 'ALTERNATIVE' && !o.history?.some(h => h.action.includes('Alternative proposée'))) return false;
        } else if (filter === 'NOT_PACKED') {
          if (!o.items.some(item => item.packingStatus === 'NOT_PACKED')) return false;
        } else if (filter === 'PREPARING') {
          // Suivies = commandes dont au moins un article a été coché, mais pas encore emballées
          if (o.status === 'PACKED') return false;
          if (!o.items.some(i => i.packingStatus === 'PACKED')) return false;
        } else if (filter !== 'all' && o.status !== filter) return false;

        // Filtre Recherche
        if (search && !o.ref?.toLowerCase().includes(s) && !o.customerName.toLowerCase().includes(s)) return false;

        // Filtre Date
        // Pour l'emballage, une commande web entre dans la file le jour de sa
        // prise en charge, même si le client l'a passée la veille.
        const packingQueueDate = new Date(o.confirmedAt || o.createdAt).getTime();
        if (timeRange.from && packingQueueDate < timeRange.from) return false;
        if (timeRange.to && packingQueueDate > timeRange.to) return false;

        // Filtre Entrepôt (Lookup performant)
        if (warehouseFilter !== 'all') {
          const hasWarehouse = o.items.some(item => {
            const key = `${item.productId}_${item.size}_${item.color}`;
            const warehouses = variantWarehouseMap.get(key);
            return warehouses?.includes(warehouseFilter);
          });
          if (!hasWarehouse) return false;
        }

        return true;
      })
      .sort((a, b) => {
        // Priorité aux alternatives, puis LIFO
        const aAlt = a.history?.some(h => h.action.includes('Alternative proposée'));
        const bAlt = b.history?.some(h => h.action.includes('Alternative proposée'));
        if (aAlt && !bAlt) return -1;
        if (!aAlt && bAlt) return 1;
        return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      });
  }, [orders, filter, search, timeRange, warehouseFilter, variantWarehouseMap]);

  return {
    filter, setFilter,
    search, setSearch,
    dateFrom, setDateFrom,
    dateTo, setDateTo,
    warehouseFilter, setWarehouseFilter,
    datePreset, setDatePreset,
    filtered
  };
}

export default function PackingClient({ initialOrders, products: initialProducts, user }: { initialOrders: PackingOrder[], products: ProductWithVariants[], user: PackingUser }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { isMobile, isReady: isViewportReady } = useResponsiveMode();
  const { showToast } = useToast();
  const [mounted, setMounted] = useState(false);

  // --- STATE ---
  const [savingChecks, setSavingChecks] = useState<Set<string>>(new Set());
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);
  const [packingNote, setPackingNote] = useState('');
  const [previewItem, setPreviewItem] = useState<{ url: string, name: string, size?: string | null, color?: string | null } | null>(null);
  const [editingVariants, setEditingVariants] = useState<{ product: ProductWithVariants, variants: PackingProductVariant[] } | null>(null);
  const [isPending, startTransition] = useTransition();

  // --- CUSTOM HOOKS ---
  const { orders, setOrders, products } = usePackingPolling(initialOrders, initialProducts, savingChecks.size);
  const {
    filter, setFilter, search, setSearch, dateFrom, setDateFrom, dateTo, setDateTo, warehouseFilter, setWarehouseFilter, datePreset, setDatePreset, filtered
  } = usePackingFilters(orders, products, searchParams);

  // Security for Hydration
  useEffect(() => { setMounted(true); }, []);

  const selectedOrder = useMemo(() => orders.find(o => o.id === selectedOrderId), [orders, selectedOrderId]);

  // Indexation simple des produits pour le modal
  const productMap = useMemo(() => {
    const map = new Map<string, ProductWithVariants>();
    products.forEach((p) => map.set(p.id, p));
    return map;
  }, [products]);

  const warehouses = useMemo(() => {
    const set = new Set<string>();
    products.forEach((p) => {
      p.variants?.forEach((v) => {
        v.stockLevels?.forEach((sl) => {
          if (sl.warehouse?.name) set.add(sl.warehouse.name);
        });
      });
    });
    return Array.from(set).sort();
  }, [products]);

  // --- HANDLERS (useCallback to avoid prop drill re-renders) ---
  const toggleSelect = useCallback((id: string) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const toggleAll = useCallback(() => {
    setSelectedIds(prev => {
      const visibleIds = filtered.map(order => order.id);
      const allVisibleSelected = visibleIds.length > 0 && visibleIds.every(id => prev.has(id));
      const next = new Set(prev);
      visibleIds.forEach(id => allVisibleSelected ? next.delete(id) : next.add(id));
      return next;
    });
  }, [filtered]);

  const toggleCheckItem = useCallback((orderId: string, item: PackingOrderItem) => {
    const newStatus = item.packingStatus !== 'PACKED';

    setOrders(prev => prev.map(o => {
      if (o.id !== orderId) return o;
      return {
        ...o,
        items: o.items.map(i => i.id === item.id ? { ...i, packingStatus: newStatus ? 'PACKED' : 'PENDING' } : i)
      };
    }));

    setSavingChecks(prev => {
      const next = new Set(prev);
      next.add(item.id);
      return next;
    });

    toggleItemPacking(item.id, newStatus)
      .catch((error: unknown) => {
        showToast(error instanceof Error ? error.message : "Erreur de sauvegarde", "error");
        setOrders(prev => prev.map(o => {
          if (o.id !== orderId) return o;
          return {
            ...o,
            items: o.items.map(i => i.id === item.id ? { ...i, packingStatus: item.packingStatus } : i)
          };
        }));
      })
      .finally(() => {
        setSavingChecks(prev => {
          const next = new Set(prev);
          next.delete(item.id);
          return next;
        });
      });
  }, [setOrders, showToast]);

  const handleItemNotPacked = useCallback((orderId: string, item: PackingOrderItem) => {
    setSavingChecks(prev => new Set(prev).add(item.id));
    markItemNotPacked(item.id)
      .then((result) => {
        setOrders(prev => prev.map(order => order.id !== orderId ? order : {
          ...order,
          items: order.items.map(current => current.id === item.id
            ? { ...current, packingStatus: result.packingStatus }
            : current),
        }));
        showToast(result.packingStatus === 'NOT_PACKED'
          ? `« ${item.name} » marqué pas emballé`
          : `« ${item.name} » remis en attente`, 'success');
      })
      .catch((error: unknown) => showToast(error instanceof Error ? error.message : "Erreur de sauvegarde", 'error'))
      .finally(() => setSavingChecks(prev => {
        const next = new Set(prev);
        next.delete(item.id);
        return next;
      }));
  }, [setOrders, showToast]);

  const handleMarkPacking = useCallback((orderId: string, status: string) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    if (status === 'PACKED') {
      const unverifiedCount = order.items.filter(i => i.packingStatus !== 'PACKED').length;
      if (unverifiedCount > 0) {
        showToast(`${unverifiedCount} article(s) doivent encore être emballés.`, 'error');
        return;
      }
    }

    let effectiveNote = packingNote.trim();
    if ((status === 'PARTIAL' || status === 'UNAVAILABLE') && !effectiveNote) {
      effectiveNote = prompt(status === 'PARTIAL'
        ? 'Quels articles ou quantités manquent ?'
        : "Pourquoi la commande n'est-elle pas disponible ?")?.trim() || '';
      if (!effectiveNote) return;
    }

    startTransition(async () => {
      try {
        const result = await updateOrderStatus(orderId, status, effectiveNote || undefined);
        if (!result.success) {
          showToast(result.error, 'error');
          return;
        }
        showToast('Statut mis à jour ✓', 'success');
        setOrders(prev => prev.map(o => {
          if (o.id !== orderId) return o;
          return result?.order ? { ...o, ...result.order } : { ...o, status };
        }));
        setSelectedOrderId(null);
        setPackingNote('');
      } catch (error: unknown) {
        showToast(error instanceof Error ? error.message : 'Erreur lors du marquage', 'error');
      }
    });
  }, [orders, packingNote, setOrders, showToast]);

  const handleBulkMark = useCallback((status: string) => {
    if (selectedIds.size === 0) return;
    const selectedOrders = orders.filter(order => selectedIds.has(order.id));
    const eligibleOrders = status === 'PACKED'
      ? selectedOrders.filter(order => order.items.every(item => item.packingStatus === 'PACKED'))
      : selectedOrders;
    const blockedCount = selectedOrders.length - eligibleOrders.length;
    if (eligibleOrders.length === 0) {
      showToast('Aucune commande sélectionnée n’est entièrement emballée.', 'error');
      return;
    }
    const warning = blockedCount > 0 ? ` ${blockedCount} commande(s) incomplète(s) seront ignorées.` : '';
    if (!confirm(`Marquer ${eligibleOrders.length} commande(s) comme emballée(s) ?${warning}`)) return;

    startTransition(async () => {
      try {
        const orderIds = eligibleOrders.map(order => order.id);
        const settledResults = await Promise.allSettled(orderIds.map(id => updateOrderStatus(id, status)));
        const successfulResults = settledResults.flatMap(result =>
          result.status === 'fulfilled' && result.value.success ? [result.value] : []
        );
        const failedIds = new Set([
          ...selectedOrders.filter(order => !eligibleOrders.some(eligible => eligible.id === order.id)).map(order => order.id),
          ...orderIds.filter((_, index) => {
            const result = settledResults[index];
            return result.status === 'rejected' || !result.value.success;
          }),
        ]);
        const updatedById = new Map(successfulResults.map(result => [result.order.id, result.order]));
        if (failedIds.size > 0) {
          const firstFailure = settledResults.find(result => result.status === 'rejected' || !result.value.success);
          const failureMessage = firstFailure?.status === 'rejected'
            ? (firstFailure.reason instanceof Error ? firstFailure.reason.message : '')
            : firstFailure && !firstFailure.value.success ? firstFailure.value.error : '';
          showToast(`${successfulResults.length} mise(s) à jour, ${failedIds.size} bloquée(s). ${failureMessage}`, 'error');
        } else {
          showToast(`${eligibleOrders.length} commandes mises à jour ✓`, 'success');
        }
        setOrders(prev => prev.map(o => {
          const updated = updatedById.get(o.id);
          if (updated) return { ...o, ...updated };
          return o;
        }));
        setSelectedIds(failedIds);
      } catch (error: unknown) {
        showToast(error instanceof Error ? error.message : 'Erreur lors du traitement groupé', 'error');
      }
    });
  }, [orders, selectedIds, setOrders, showToast]);

  const handleProposeAlternative = useCallback((orderId: string, itemName: string) => {
    const alt = prompt(`Alternative pour "${itemName}" ?`);
    if (!alt) return;

    startTransition(async () => {
      try {
        await addOrderHistoryEntry(orderId, `Alternative proposée pour "${itemName}" : ${alt}`);
        showToast('Alternative enregistrée ✓', 'success');
        setOrders(prev => prev.map(o => {
          if (o.id !== orderId) return o;
          const history = Array.isArray(o.history) ? [...o.history] : [];
          history.push({
            at: new Date().toISOString(),
            action: `Alternative proposée pour "${itemName}" : ${alt}`,
            byName: "Système"
          });
          return { ...o, history };
        }));
      } catch {
        showToast('Erreur lors de l\'enregistrement', 'error');
      }
    });
  }, [setOrders, showToast]);

  const handleEditStock = useCallback((product: ProductWithVariants) => {
    setEditingVariants({ product, variants: product.variants });
  }, []);

  const applyDatePreset = useCallback((preset: DatePreset) => {
    setDatePreset(preset);
    if (preset === 'custom') return;
    if (preset === 'all') {
      setDateFrom('');
      setDateTo('');
      return;
    }

    const today = new Date();
    const from = new Date(today);
    if (preset === 'yesterday') from.setDate(today.getDate() - 1);

    const to = preset === 'yesterday' ? from : today;
    setDateFrom(toLocalDateInputValue(from));
    setDateTo(toLocalDateInputValue(to));
  }, [setDateFrom, setDatePreset, setDateTo]);

  const handleDateFromChange = useCallback((value: string) => {
    setDatePreset('custom');
    setDateFrom(value);
  }, [setDateFrom, setDatePreset]);

  const handleDateToChange = useCallback((value: string) => {
    setDatePreset('custom');
    setDateTo(value);
  }, [setDateTo, setDatePreset]);

  // --- RENDER ---
  const commonProps = {
    productMap,
    onEditStock: handleEditStock,
    onPreviewImage: (url: string, name: string, size?: string | null, color?: string | null) =>
      setPreviewItem({ url, name, size, color }),
    onToggleCheckItem: toggleCheckItem,
    onMarkItemNotPacked: handleItemNotPacked,
    canEditStock: ['ADMIN', 'DEVELOPER', 'PACKING', 'STOCK', 'COLLECTION'].includes(user.role?.toUpperCase()),
  };

  const viewMotion = {
    initial: { opacity: 0, y: 12, scale: 0.985 },
    animate: { opacity: 1, y: 0, scale: 1 },
    transition: { duration: 0.24, ease: [0.22, 1, 0.36, 1] },
  } as const;

  if (!isViewportReady) {
    return (
      <>
        <LogisticsMobileStyles />
        <div className="content logistics-responsive-pending" role="status" aria-live="polite">
          Chargement de l&apos;interface…
        </div>
      </>
    );
  }

  if (isMobile) {
    return (
      <motion.div key="packing-mobile" className="logistics-mobile-root logistics-view-mobile packing-mobile-root" {...viewMotion}>
        <LogisticsMobileStyles />
        <div className="logistics-mobile-header packing-mobile-header">
          <div className="packing-mobile-titlebar">
            <div className="packing-mobile-title-icon"><Package size={21} strokeWidth={2.4} /></div>
            <div className="packing-mobile-title-copy">
              <h1>Emballage</h1>
            </div>
            <div className="packing-mobile-count" aria-label={`${filtered.length} commandes affichées`}>{filtered.length}</div>
          </div>

          <div className="mobile-search-bar packing-search">
            <Search size={16} style={{ position: 'absolute', left: 12, top: 12, color: '#AEAEB2' }} />
            <input
              type="text"
              placeholder="Réf ou client..."
              className="mobile-search-input"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            {search && <button className="packing-search-clear" onClick={() => setSearch('')} aria-label="Effacer la recherche"><X size={16} /></button>}
          </div>

          <div className="mobile-status-tabs packing-status-tabs">
            {STATUS_FILTERS.map(f => (
              <button key={f.key} className={`status-tab ${filter === f.key ? 'active' : ''}`} onClick={() => setFilter(f.key)}>
                {f.label}
              </button>
            ))}
          </div>

          <div className="packing-date-presets" style={{ display: 'flex', gap: 4, background: '#F2F2F7', padding: '2px', borderRadius: 10, marginBottom: 12 }}>
            {[
              { label: 'Auj.', val: 'today' },
              { label: 'Hier', val: 'yesterday' },
              { label: 'Perso', val: 'custom' },
              { label: 'Tout', val: 'all' }
            ].map(d => (
              <button
                key={d.val}
                onClick={() => applyDatePreset(d.val as DatePreset)}
                className={`packing-date-preset ${datePreset === d.val ? 'active' : ''}`}
                style={{
                  flex: 1, fontSize: 10, fontWeight: 800, padding: '6px 0', borderRadius: 8, border: 'none',
                  background: datePreset === d.val ? 'white' : 'transparent',
                  boxShadow: 'none'
                }}
              >
                {d.label}
              </button>
            ))}
          </div>
          {datePreset === 'custom' && (
            <div className="packing-mobile-extra-filters" style={{ marginBottom: 8 }}>
              <input type="date" className="packing-mobile-filter" aria-label="Date de début" value={dateFrom} onChange={e => handleDateFromChange(e.target.value)} />
              <input type="date" className="packing-mobile-filter" aria-label="Date de fin" value={dateTo} onChange={e => handleDateToChange(e.target.value)} />
            </div>
          )}
          {warehouses.length > 1 && <div className="packing-mobile-extra-filters single">
            <select className="packing-mobile-filter" aria-label="Filtrer par entrepôt" value={warehouseFilter} onChange={e => setWarehouseFilter(e.target.value)}>
              <option value="all">Tous les entrepôts</option>
              {warehouses.map(warehouse => <option key={warehouse} value={warehouse}>{warehouse}</option>)}
            </select>
          </div>}
        </div>

        <div className="logistics-mobile-content packing-mobile-content">
          <AnimatePresence mode="popLayout">
            {filtered.length === 0 ? (
              <motion.div className="packing-mobile-empty" initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ padding: '40px 0', textAlign: 'center' }}>
                <Package size={48} style={{ margin: '0 auto 12px', opacity: 0.2 }} />
                <p style={{ color: '#8E8E93', fontSize: 14 }}>Aucune commande</p>
              </motion.div>
            ) : (
              filtered.map((o, idx) => (
                <PackingItem
                  key={o.id}
                  order={o}
                  isMobile={true}
                  idx={idx}
                  isSelected={selectedIds.has(o.id)}
                  onToggleSelect={toggleSelect}
                  onSelect={(order) => { setSelectedOrderId(order.id); setPackingNote(''); }}
                  onMarkPacking={handleMarkPacking}
                  savingChecks={savingChecks}
                  {...commonProps}
                />
              ))
            )}
          </AnimatePresence>
        </div>

        {selectedIds.size > 0 && <div className="packing-mobile-bulkbar">
          <span>{selectedIds.size} sélectionnée(s)</span>
          <button onClick={() => handleBulkMark('PACKED')} disabled={isPending}><Check size={15} /> Emballer</button>
        </div>}

        <PackingOrderModal
          order={selectedOrder}
          isMobile={true}
          isPending={isPending}
          packingNote={packingNote}
          setPackingNote={setPackingNote}
          onClose={() => setSelectedOrderId(null)}
          onMarkPacking={handleMarkPacking}
          onProposeAlternative={handleProposeAlternative}
          savingChecks={savingChecks}
          {...commonProps}
        />

        {editingVariants && (
          <VariantsEditorModal
            product={editingVariants.product}
            variants={editingVariants.variants}
            onClose={() => setEditingVariants(null)}
            onSave={() => {
              showToast('Stock mis a jour', 'success');
              setEditingVariants(null);
              router.refresh();
            }}
          />
        )}

        {mounted && previewItem !== null && createPortal(
          <div
            className="lightbox-root"
            onClick={() => setPreviewItem(null)}
            style={{
              position: 'fixed',
              inset: 0,
              zIndex: 999999,
              background: 'rgba(0,0,0,0.95)',
              backdropFilter: 'blur(15px)',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              cursor: 'zoom-out',
              padding: '20px',
              animation: 'fadeIn 0.2s ease-out'
            }}
          >
            <style>{`
              @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
              @keyframes zoomIn { from { transform: scale(0.9); opacity: 0; } to { transform: scale(1); opacity: 1; } }
            `}</style>

            <div style={{ position: 'relative', maxWidth: '98vw', maxHeight: '95vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', animation: 'zoomIn 0.3s cubic-bezier(0.16, 1, 0.3, 1)' }}>
              <img
                src={previewItem.url}
                alt="Preview"
                style={{
                  display: 'block',
                  maxWidth: '100%',
                  maxHeight: '80vh',
                  borderRadius: 16,
                  border: '2px solid rgba(255,255,255,0.2)',
                  boxShadow: '0 50px 100px rgba(0,0,0,0.8)',
                  objectFit: 'contain'
                }}
              />

              <div style={{ marginTop: 24, textAlign: 'center', color: 'white' }}>
                <h2 style={{ fontSize: 24, fontWeight: 900, marginBottom: 8, letterSpacing: '-0.02em' }}>{previewItem.name}</h2>
                <div style={{ display: 'flex', gap: 12, justifyContent: 'center' }}>
                  {previewItem.size && <span style={{ background: 'white', color: 'black', padding: '6px 16px', borderRadius: 8, fontWeight: 900, fontSize: 18 }}>Taille {previewItem.size}</span>}
                  {previewItem.color && <span style={{ background: 'rgba(255,255,255,0.2)', color: 'white', padding: '6px 16px', borderRadius: 8, fontWeight: 800, fontSize: 18, border: '1px solid rgba(255,255,255,0.3)' }}>{previewItem.color}</span>}
                </div>
              </div>

              <button
                onClick={(e) => { e.stopPropagation(); setPreviewItem(null); }}
                style={{
                  position: 'fixed', top: 40, right: 40, background: 'white', border: 'none', color: 'black', width: 60, height: 60, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', boxShadow: '0 20px 40px rgba(0,0,0,0.5)', zIndex: 20
                }}
              >
                <X size={36} strokeWidth={3} />
              </button>
            </div>
          </div>,
          document.body
        )}
      </motion.div>
    );
  }

  return (
    <motion.div key="packing-desktop" className="content logistics-view-desktop" {...viewMotion}>
      <div className="filters-bar packing-desktop-filters" style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center', background: 'white', padding: '12px 16px', borderRadius: 12, marginBottom: 20, border: '1px solid var(--line)' }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
          {STATUS_FILTERS.map(f => (
            <button key={f.key} className={`filter-chip ${filter === f.key ? 'active' : ''}`} onClick={() => setFilter(f.key)}>
              {f.label}
            </button>
          ))}
        </div>
        <div style={{ position: 'relative', flex: 1, minWidth: 200 }}>
          <input type="text" placeholder="Rechercher..." className="field-input" style={{ paddingLeft: 36, height: 36, fontSize: 13 }} value={search} onChange={e => setSearch(e.target.value)} />
          <span style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', opacity: 0.4 }}><Search size={16} /></span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <select className="filter-date" value={warehouseFilter} onChange={e => setWarehouseFilter(e.target.value)}>
            <option value="all">Tous les entrepôts</option>
            {warehouses.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
          <div style={{ display: 'flex', gap: 4, background: 'var(--cream)', padding: 3, borderRadius: 10, border: '1px solid var(--line)' }}>
            {[
              { label: "Aujourd'hui", val: 'today' },
              { label: 'Hier', val: 'yesterday' },
              { label: 'Perso', val: 'custom' },
              { label: 'Tout', val: 'all' },
            ].map(d => (
              <button key={d.val} className={`shortcut-btn ${datePreset === d.val ? 'active' : ''}`} onClick={() => applyDatePreset(d.val as DatePreset)}>
                {d.label}
              </button>
            ))}
          </div>
          {datePreset === 'custom' && (
            <>
              <input type="date" className="filter-date" value={dateFrom} onChange={e => handleDateFromChange(e.target.value)} />
              <input type="date" className="filter-date" value={dateTo} onChange={e => handleDateToChange(e.target.value)} />
            </>
          )}
        </div>
      </div>

      <TableCard
        title={`${filtered.length} commande(s)`}
        actions={selectedIds.size > 0 && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <span className="cell-muted">{selectedIds.size} sélectionnée(s)</span>
            <button className="btn-orange" onClick={() => handleBulkMark('PACKED')} disabled={isPending}>
              Emballé
            </button>
          </div>
        )}
      >
        <table>
          <thead>
            <tr>
              <th style={{ width: 40 }}><input type="checkbox" checked={filtered.length > 0 && filtered.every(order => selectedIds.has(order.id))} onChange={toggleAll} /></th>
              <th>Référence</th><th>Articles</th><th>Entrepôts</th><th>Statut</th><th></th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((o) => (
              <PackingItem
                key={o.id}
                order={o}
                isMobile={false}
                isSelected={selectedIds.has(o.id)}
                onToggleSelect={toggleSelect}
                onSelect={(order) => { setSelectedOrderId(order.id); setPackingNote(''); }}
                onMarkPacking={handleMarkPacking}
                savingChecks={savingChecks}
                {...commonProps}
              />
            ))}
          </tbody>
        </table>
      </TableCard>

      <PackingOrderModal
        order={selectedOrder}
        isMobile={false}
        isPending={isPending}
        packingNote={packingNote}
        setPackingNote={setPackingNote}
        onClose={() => setSelectedOrderId(null)}
        onMarkPacking={handleMarkPacking}
        onProposeAlternative={handleProposeAlternative}
        savingChecks={savingChecks}
        {...commonProps}
      />

      {mounted && previewItem !== null && createPortal(
        <div
          className="lightbox-root"
          onClick={() => setPreviewItem(null)}
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 999999,
            background: 'rgba(0,0,0,0.95)',
            backdropFilter: 'blur(15px)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'zoom-out',
            padding: '20px',
            animation: 'fadeIn 0.2s ease-out'
          }}
        >
          <style>{`
            @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
            @keyframes zoomIn { from { transform: scale(0.9); opacity: 0; } to { transform: scale(1); opacity: 1; } }
          `}</style>

          <div style={{ position: 'relative', maxWidth: '98vw', maxHeight: '95vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', animation: 'zoomIn 0.3s cubic-bezier(0.16, 1, 0.3, 1)' }}>
            <img
              src={previewItem.url}
              alt="Preview"
              style={{
                display: 'block',
                maxWidth: '100%',
                maxHeight: '80vh',
                borderRadius: 16,
                border: '2px solid rgba(255,255,255,0.2)',
                boxShadow: '0 50px 100px rgba(0,0,0,0.8)',
                objectFit: 'contain'
              }}
            />

            {/* Infos de l'article en grand sous l'image */}
            <div style={{ marginTop: 24, textAlign: 'center', color: 'white' }}>
              <h2 style={{ fontSize: 24, fontWeight: 900, marginBottom: 8, letterSpacing: '-0.02em' }}>{previewItem.name}</h2>
              <div style={{ display: 'flex', gap: 12, justifyContent: 'center' }}>
                {previewItem.size && <span style={{ background: 'white', color: 'black', padding: '6px 16px', borderRadius: 8, fontWeight: 900, fontSize: 18 }}>Taille {previewItem.size}</span>}
                {previewItem.color && <span style={{ background: 'rgba(255,255,255,0.2)', color: 'white', padding: '6px 16px', borderRadius: 8, fontWeight: 800, fontSize: 18, border: '1px solid rgba(255,255,255,0.3)' }}>{previewItem.color}</span>}
              </div>
            </div>

            <button
              onClick={(e) => { e.stopPropagation(); setPreviewItem(null); }}
              style={{
                position: 'fixed',
                top: 40,
                right: 40,
                background: 'white',
                border: 'none',
                color: 'black',
                width: 60,
                height: 60,
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                cursor: 'pointer',
                boxShadow: '0 20px 40px rgba(0,0,0,0.5)',
                zIndex: 20
              }}
            >
              <X size={36} strokeWidth={3} />
            </button>
          </div>
        </div>,
        document.body
      )}

      {editingVariants && (
        <VariantsEditorModal
          product={editingVariants.product}
          variants={editingVariants.variants}
          onClose={() => setEditingVariants(null)}
          onSave={() => {
            showToast('Stock mis a jour', 'success');
            setEditingVariants(null);
            router.refresh();
          }}
        />
      )}
    </motion.div>
  );
}

"use client";

import React from "react";
import { StatusBadge } from "@/components/UI";
import { formatDay } from "@/lib/constants";
import { Check, Edit2, Eye, Warehouse, Loader2 } from "lucide-react";
import { motion } from "framer-motion";

import { PackingOrder, PackingOrderItem, ProductWithVariants } from "../types";

interface PackingItemProps {
  order: PackingOrder;
  isMobile: boolean;
  productMap: Map<string, ProductWithVariants>;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
  onSelect: (order: PackingOrder) => void;
  onEditStock: (product: ProductWithVariants) => void;
  canEditStock: boolean;
  onMarkPacking: (orderId: string, status: string) => void;
  onPreviewImage: (url: string, name: string, size?: string | null, color?: string | null) => void;
  onToggleCheckItem: (orderId: string, item: PackingOrderItem) => void;
  onMarkItemNotPacked: (orderId: string, item: PackingOrderItem) => void;
  savingChecks?: Set<string>;
  idx?: number;
}

const PackingItem = React.memo(({
  order: o,
  isMobile,
  productMap,
  isSelected,
  onToggleSelect,
  onSelect,
  onEditStock,
  canEditStock,
  onMarkPacking,
  onPreviewImage,
  onToggleCheckItem,
  onMarkItemNotPacked,
  savingChecks = new Set(),
  idx = 0
}: PackingItemProps) => {
  
  const totalItems = o.items.length;
  const checkedCount = o.items.filter((i: PackingOrderItem) => (i.packingStatus === 'PACKED')).length;
  const progress = totalItems > 0 ? (checkedCount / totalItems) * 100 : 0;

  if (isMobile) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: idx * 0.05 }}
        className="mobile-card packing-order-card"
        onClick={() => onSelect(o)}
        style={{
          padding: 0,
          overflow: 'hidden',
          borderLeft: o.status === 'PREPARING' ? '4px solid #FB7185' : '1px solid #E5E5EA',
          background: 'white',
          display: 'flex',
          flexDirection: 'column'
        }}
      >
        <div className="packing-order-main" style={{ display: 'flex', padding: '12px', gap: 14 }}>
          {/* IMAGE LEFT */}
          <div style={{ position: 'relative', flexShrink: 0 }}>
            <div
              onClick={(e) => {
                const img = o.items[0]?.image;
                if (img) {
                  e.stopPropagation();
                  onPreviewImage(img, o.items[0].name, o.items[0].size, o.items[0].color);
                }
              }}
              className="packing-order-image"
              style={{
                width: 100,
                height: 100,
                background: '#F2F2F7',
                borderRadius: 14,
                overflow: 'hidden',
                border: '1.5px solid #E5E5EA',
                boxShadow: '0 4px 10px rgba(0,0,0,0.05)'
              }}
            >
              {o.items[0]?.image ? (
                <img 
                  src={o.items[0].image} 
                  style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
                  alt="" 
                  onError={(e: React.SyntheticEvent<HTMLImageElement>) => {
                    const target = e.currentTarget;
                    target.onerror = null;
                    target.style.display = 'none';
                    if (target.parentElement) {
                      target.parentElement.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;font-size:32px;">📦</div>';
                    }
                  }}
                />
              ) : (
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', fontSize: 32 }}>{o.items[0]?.emoji || '📦'}</div>
              )}
            </div>
            {totalItems > 1 && (
              <div style={{ position: 'absolute', bottom: -6, right: -6, background: '#1C1C1E', color: 'white', fontSize: 10, fontWeight: 800, padding: '2px 8px', borderRadius: 10, border: '2px solid white' }}>
                +{totalItems - 1}
              </div>
            )}
          </div>

          {/* INFO RIGHT */}
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 4 }}>
              <div className="packing-order-ref" style={{ fontFamily: 'var(--font-mono)', fontWeight: 800, fontSize: 14, color: '#1C1C1E' }}>{o.ref}</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <StatusBadge status={o.status} size="sm" />
                <button
                  type="button"
                  className={`packing-select-btn ${isSelected ? 'selected' : ''}`}
                  aria-label={isSelected ? `Désélectionner ${o.ref}` : `Sélectionner ${o.ref}`}
                  onClick={(event) => { event.stopPropagation(); onToggleSelect(o.id); }}
                >
                  {isSelected && <Check size={15} strokeWidth={3} />}
                </button>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <div>
                <div className="packing-order-customer" style={{ fontSize: 12, fontWeight: 700, color: '#1C1C1E', marginBottom: 2, display: 'flex', alignItems: 'center', gap: 6 }}>
                  {o.customerName}
                  {o.items.some((i: PackingOrderItem) => i.isGift) && <span style={{ fontSize: 8, background: 'var(--orange-soft)', color: 'var(--orange)', padding: '1px 5px', borderRadius: 4, fontWeight: 800 }}>CADEAU</span>}
                </div>
                <div className="packing-order-meta" style={{ fontSize: 10, color: '#8E8E93', fontWeight: 600 }}>{o.commune || 'Abidjan'} • {formatDay(o.createdAt)}</div>
                <div style={{ display: 'flex', gap: 6, marginTop: 4, flexWrap: 'wrap' }}>
                  {o.commercialName && <span style={{ fontSize: 9, fontWeight: 700, background: '#E8F4FD', color: '#0A84FF', padding: '2px 6px', borderRadius: 6 }}>🛒 {o.commercialName}</span>}
                  {o.packedByName && <span style={{ fontSize: 9, fontWeight: 700, background: '#F2FBF4', color: '#34C759', padding: '2px 6px', borderRadius: 6 }}>📦 {o.packedByName}</span>}
                </div>
              </div>
              {canEditStock && <button
                onClick={(e) => {
                  e.stopPropagation();
                  const productId = o.items[0]?.productId;
                  if (productId) {
                    const p = productMap.get(productId);
                    if (p) onEditStock(p);
                  }
                }}
                style={{
                  background: 'var(--cream)',
                  border: '1px solid var(--line)',
                  borderRadius: 10,
                  padding: '6px 12px',
                  fontSize: 12,
                  fontWeight: 800,
                  color: 'var(--brown-soft)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6
                }}
              >
                <Edit2 size={14} /> Stock
              </button>}
            </div>

            <div className="packing-order-progress" style={{ background: '#F2F2F7', padding: '8px', borderRadius: 8 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 9, fontWeight: 800, color: '#8E8E93', marginBottom: 4 }}>
                <span>PROGRESSION</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  {o.items.some(i => savingChecks.has(i.id)) && <Loader2 size={10} className="animate-spin" color="var(--orange)" />}
                  <span style={{ color: progress === 100 ? '#34C759' : '#1C1C1E' }}>{checkedCount}/{totalItems}</span>
                </div>
              </div>
              <div className="progress-bar-bg" style={{ height: 4 }}>
                <div className="progress-bar-fill" style={{ width: `${progress}%`, background: progress === 100 ? '#34C759' : '#FF6B2C' }} />
              </div>
            </div>
          </div>
        </div>

        {/* ACTIONS BOTTOM */}
        <div className="packing-card-actions" style={{ display: 'flex', borderTop: '1px solid #E5E5EA' }}>
          <button
            className="packing-card-action primary"
             onClick={(e) => { e.stopPropagation(); onMarkPacking(o.id, 'PACKED'); }}
             disabled={progress < 100}
            style={{ flex: 1.5, height: 44, background: progress === 100 ? '#34C759' : '#C7C7CC', color: 'white', border: 'none', fontWeight: 800, fontSize: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, cursor: progress === 100 ? 'pointer' : 'not-allowed' }}
          >
            <Check size={16} strokeWidth={3} /> PACKER
          </button>
          <button
            className="packing-card-action partial"
            onClick={(e) => { e.stopPropagation(); onMarkPacking(o.id, 'PARTIAL'); }}
            style={{ flex: 1, height: 44, background: '#FF9500', color: 'white', border: 'none', fontWeight: 800, fontSize: 12, borderLeft: '1px solid rgba(255,255,255,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >
            PARTIEL
          </button>
          <button
            className="packing-card-action unavailable"
            onClick={(e) => { e.stopPropagation(); onMarkPacking(o.id, 'UNAVAILABLE'); }}
            style={{ flex: 1, height: 44, background: '#FF3B30', color: 'white', border: 'none', fontWeight: 800, fontSize: 12, borderLeft: '1px solid rgba(255,255,255,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >
            STOCK
          </button>
        </div>
      </motion.div>
    );
  }

  // DESKTOP ROW
  return (
    <tr
      style={{
        background: o.status === 'PREPARING' ? '#FFF1F2' : isSelected ? 'var(--cream-2)' : '',
        borderLeft: o.status === 'PREPARING' ? '4px solid #FB7185' : ''
      }}
    >
      <td><input type="checkbox" checked={isSelected} onChange={() => onToggleSelect(o.id)} /></td>
      <td>
        <span className="cell-mono" style={{ fontWeight: 800 }}>{o.ref}</span>
        <div className="cell-muted">{formatDay(o.createdAt)}</div>
      </td>
      <td>
        {o.items.map((i: PackingOrderItem, idx: number) => {
          const isChecked = (i.packingStatus === 'PACKED');
          const imageUrl = i.image;
          const isSaving = savingChecks.has(i.id);
          const giftBlocked = i.isGift && i.giftApprovalStatus !== 'APPROVED';
          
          return (
            <div key={idx} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, margin: '2px 0', opacity: isChecked ? 0.4 : 1, transition: 'opacity 0.2s', pointerEvents: isSaving ? 'none' : 'auto' }}>
              <div
                onClick={(e) => { e.stopPropagation(); if (!giftBlocked) onToggleCheckItem(o.id, i); }}
                title={giftBlocked ? "Autorisation administrateur requise" : undefined}
                style={{ width: 16, height: 16, borderRadius: 4, border: '1px solid var(--line)', background: isChecked ? 'var(--green)' : giftBlocked ? '#FEE2E2' : 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: giftBlocked ? 'not-allowed' : 'pointer' }}
              >
                {isSaving ? (
                  <Loader2 size={10} className="animate-spin" color={isChecked ? "white" : "var(--orange)"} />
                ) : (
                  isChecked && <Check size={10} color="white" />
                )}
              </div>
              {imageUrl ? (
                <img
                  src={imageUrl}
                  alt=""
                  style={{ width: 22, height: 22, borderRadius: 4, objectFit: 'cover', cursor: 'zoom-in' }}
                  onClick={(e) => { e.stopPropagation(); onPreviewImage(imageUrl, i.name, i.size, i.color); }}
                  onError={(e: React.SyntheticEvent<HTMLImageElement>) => {
                    const target = e.currentTarget;
                    target.onerror = null;
                    target.style.display = 'none';
                    const span = document.createElement('span');
                    span.innerText = i.emoji || '📦';
                    target.parentElement?.appendChild(span);
                  }}
                />
              ) : (
                <span>{i.emoji || '📦'}</span>
              )}
              <span style={{ fontWeight: 600, textDecoration: isChecked ? 'line-through' : 'none', display: 'flex', alignItems: 'center', gap: 4 }}>
                {i.name}
                {i.isGift && <span style={{ fontSize: 8, background: 'var(--orange-soft)', color: 'var(--orange)', padding: '0 4px', borderRadius: 4, fontWeight: 800 }}>CADEAU</span>}
                {giftBlocked && <span style={{ fontSize: 8, background: '#FEE2E2', color: '#B91C1C', padding: '1px 4px', borderRadius: 4, fontWeight: 900 }}>{i.giftApprovalStatus === 'REJECTED' ? 'REFUSÉ' : 'ATTENTE ADMIN'}</span>}
              </span>
              <span className="size-dot">{i.size}</span>
              <strong style={{ fontSize: 11 }}>{i.color}</strong>
              <button
                type="button"
                className={`packing-item-state-btn ${i.packingStatus === 'NOT_PACKED' ? 'active' : ''}`}
                aria-pressed={i.packingStatus === 'NOT_PACKED'}
                disabled={isSaving}
                onClick={(event) => { event.stopPropagation(); onMarkItemNotPacked(o.id, i); }}
              >
                {i.packingStatus === 'NOT_PACKED' ? 'Retirer “Pas emballé”' : 'Pas emballé'}
              </button>

              {o.history?.filter((h) => h.action.includes(`Alternative proposée pour "${i.name}"`)).map((h, hi: number) => (
                <div key={hi} style={{ fontSize: 10, color: 'var(--orange)', background: 'var(--orange-soft)', padding: '1px 6px', borderRadius: 4, fontWeight: 700, marginTop: 2 }}>
                  {h.action.split(' : ')[1]}
                </div>
              ))}
            </div>
          );
        })}
      </td>
      <td>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          {o.items.map((item: PackingOrderItem, idx: number) => {
            const productId = item.productId;
            if (!productId) return null;
            const p = productMap.get(productId);
            if (!p) return null;
            const variant = p.variants.find((v) => v.size === item.size && v.color === item.color);
            return (
              <div key={idx} style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                {variant?.stockLevels?.map((sl) => (
                  <div key={sl.id} style={{ fontSize: 9, background: 'var(--cream-2)', padding: '1px 5px', borderRadius: 4, display: 'flex', alignItems: 'center', gap: 3 }}>
                    <Warehouse size={8} className="text-orange" />
                    <span>{sl.warehouse.name}</span>
                    {sl.position && <span style={{ fontWeight: 800 }}>• {sl.position}</span>}
                  </div>
                ))}
              </div>
            );
          })}
        </div>
      </td>
      <td>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {o.commercialName && <span style={{ fontSize: 10, fontWeight: 700 }}>🛒 {o.commercialName}</span>}
          {o.packedByName && <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--green)' }}>📦 {o.packedByName}</span>}
          {!o.commercialName && !o.packedByName && <span className="cell-muted">—</span>}
        </div>
      </td>
      <td><StatusBadge status={o.status} /></td>
      <td>
        <div style={{ display: 'flex', gap: 6 }}>
          <button className="action-btn" title="Détail emballage" onClick={() => onSelect(o)}>
            <Eye size={14} />
          </button>
        </div>
      </td>
    </tr>
  );
});

PackingItem.displayName = "PackingItem";

export default PackingItem;

"use client";

import React from "react";
import Modal from "@/components/Modal";
import { SectionLabel, DetailCard } from "@/components/UI";
import { Check, ArrowLeftRight, Warehouse, Edit2, Loader2 } from "lucide-react";

import { PackingOrder, PackingOrderItem, ProductWithVariants } from "../types";

interface PackingOrderModalProps {
  order: PackingOrder | null | undefined;
  isMobile: boolean;
  isPending: boolean;
  productMap: Map<string, ProductWithVariants>;
  packingNote: string;
  setPackingNote: (note: string) => void;
  onClose: () => void;
  onMarkPacking: (orderId: string, status: string) => void;
  onProposeAlternative: (orderId: string, itemName: string) => void;
  onEditStock: (product: ProductWithVariants) => void;
  canEditStock: boolean;
  onToggleCheckItem: (orderId: string, item: PackingOrderItem) => void;
  onMarkItemNotPacked: (orderId: string, item: PackingOrderItem) => void;
  onPreviewImage: (url: string, name: string, size?: string | null, color?: string | null) => void;
  savingChecks?: Set<string>;
}

export default function PackingOrderModal({
  order,
  isMobile,
  isPending,
  productMap,
  packingNote,
  setPackingNote,
  onClose,
  onMarkPacking,
  onProposeAlternative,
  onEditStock,
  canEditStock,
  onToggleCheckItem,
  onMarkItemNotPacked,
  onPreviewImage,
  savingChecks = new Set()
}: PackingOrderModalProps) {

  if (!order) return null;

  const progress = order.items.filter((i) => (i.packingStatus === 'PACKED')).length;
  const total = order.items.length;
  const isComplete = total > 0 && progress === total;
  const isPartial = progress > 0 && progress < total;

  if (isMobile) {
    return (
      <Modal
        isOpen={true}
        onClose={onClose}
        title={`Détails · ${order.ref}`}
        large
        footer={
          <div className="packing-mobile-order-footer">
            {order.status === 'PACKED' ? (
              <>
                <button className="btn-secondary" onClick={onClose}>Fermer</button>
                <button className="btn-secondary" onClick={() => onMarkPacking(order.id, 'CONFIRMED')} disabled={isPending} style={{ color: '#B33A32', borderColor: '#F3C5C1' }}>Annuler l&apos;emballage</button>
              </>
            ) : (
              <>
                <button className="btn-secondary" onClick={() => onMarkPacking(order.id, 'UNAVAILABLE')} disabled={isPending} style={{ color: 'var(--red)', borderColor: '#F3C5C1' }}>Indisponible</button>
                <button className="btn-secondary" onClick={() => onMarkPacking(order.id, 'PARTIAL')} disabled={isPending || !isPartial} style={{ color: '#9A5A00', borderColor: '#F1D49D' }}>Partiel</button>
                <button className="btn-secondary" onClick={onClose}>Fermer</button>
                <button className="btn-orange" onClick={() => onMarkPacking(order.id, 'PACKED')} disabled={isPending || !isComplete} title={!isComplete ? "Emballez tous les articles avant de valider" : undefined} style={{ gridColumn: '1 / -1' }}>
                  <Check size={16} /> Emballé
                </button>
              </>
            )}
          </div>
        }
      >
        <div className="packing-modal-progress" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <div>
            <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 800, color: 'var(--orange)', fontSize: 18 }}>{order.ref}</div>
            <div style={{ fontWeight: 700, fontSize: 14, marginTop: 2 }}>{order.customerName}</div>
          </div>
            <div style={{ textAlign: 'right' }}>
              <div style={{ fontSize: 9, fontWeight: 800, color: '#8E8E93', marginBottom: 2 }}>PROGRESSION</div>
              <div style={{ fontWeight: 900, fontSize: 16 }}>{progress} / {total}</div>
            </div>
          </div>
          <div className="progress-bar-bg" style={{ height: 7, marginTop: -10, marginBottom: 18 }} aria-label={`${progress} articles emballés sur ${total}`}>
            <div className="progress-bar-fill" style={{ width: `${total > 0 ? (progress / total) * 100 : 0}%`, background: isComplete ? '#24A967' : '#F15A24' }} />
          </div>

        <SectionLabel spaced>Checklist Articles</SectionLabel>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {order.items.map((item, idx: number) => {
            const p = productMap.get(item.productId || "");
            const isChecked = (item.packingStatus === 'PACKED');
            const isSaving = savingChecks.has(item.id);
            const giftBlocked = item.isGift && item.giftApprovalStatus !== 'APPROVED';
            return (
              <DetailCard
                key={idx}
                className={`packing-checklist-card ${isChecked ? 'checked' : ''}`}
                style={{
                  padding: 0,
                  overflow: 'hidden',
                  borderRadius: 14,
                  border: isSaving
                    ? '1.5px solid var(--orange)'
                    : isChecked ? '1.5px solid #34C759' : '1px solid #E5E5EA',
                  background: isChecked ? '#F2FBF4' : 'white',
                  transition: 'all 0.2s ease',
                  opacity: isSaving ? 0.75 : 1,
                  animation: isSaving ? 'pulse-border 1s ease infinite' : 'none',
                  position: 'relative' as const,
                  pointerEvents: isSaving ? 'none' as const : 'auto' as const,
                }}
                onClick={() => { if (!giftBlocked) onToggleCheckItem(order.id, item); }}
              >
                {isSaving && (
                  <div style={{
                    position: 'absolute', top: 0, right: 0,
                    padding: '4px 10px',
                    background: 'var(--orange)',
                    color: 'white',
                    fontSize: 9,
                    fontWeight: 800,
                    borderBottomLeftRadius: 8,
                    zIndex: 2,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 4,
                    letterSpacing: '0.05em',
                  }}>
                    <Loader2 size={10} style={{ animation: 'spin 0.8s linear infinite' }} />
                    ENREGISTREMENT
                  </div>
                )}
                <div style={{ display: 'flex', minHeight: 90 }}>
                  <div style={{ position: 'relative', width: 90, flexShrink: 0, background: '#F2F2F7', borderRight: '1px solid #E5E5EA' }}>
                    {item.image ? (
                      <img
                        src={item.image}
                        style={{ width: '100%', height: '100%', objectFit: 'cover', opacity: isChecked ? 0.3 : 1 }}
                        onClick={(e) => { e.stopPropagation(); onPreviewImage(item.image!, item.name, item.size, item.color); }}
                        alt=""
                      />
                    ) : (
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', fontSize: 28 }}>{item.emoji || '📦'}</div>
                    )}
                    {isChecked && !savingChecks.has(item.id) && (
                      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(52, 199, 89, 0.1)' }}>
                        <Check size={36} color="#34C759" strokeWidth={5} />
                      </div>
                    )}
                    {savingChecks.has(item.id) && (
                      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.05)' }}>
                        <Loader2 size={20} color="#8E8E93" style={{ animation: 'spin 0.8s linear infinite' }} />
                      </div>
                    )}
                    <div style={{ position: 'absolute', top: 6, left: 6, width: 20, height: 20, borderRadius: 5, border: '2px solid', borderColor: isChecked ? '#34C759' : '#C7C7CC', background: isChecked ? '#34C759' : 'rgba(255,255,255,0.8)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      {isChecked && !savingChecks.has(item.id) && <Check size={14} color="white" strokeWidth={4} />}
                      {savingChecks.has(item.id) && <Loader2 size={12} color={isChecked ? 'white' : '#8E8E93'} style={{ animation: 'spin 0.8s linear infinite' }} />}
                    </div>
                  </div>

                  <div style={{ flex: 1, padding: '10px 14px', display: 'flex', flexDirection: 'column', justifyContent: 'center', minWidth: 0 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 2 }}>
                      <div style={{ fontWeight: 800, fontSize: 14, color: isChecked ? '#8E8E93' : '#1C1C1E', textDecoration: isChecked ? 'line-through' : 'none', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: 6 }}>
                        {item.name}
                        {item.isGift && <span style={{ fontSize: 9, background: 'var(--orange-soft)', color: 'var(--orange)', padding: '1px 6px', borderRadius: 10, fontWeight: 800, textTransform: 'uppercase' }}>Cadeau</span>}
                        {giftBlocked && <span style={{ fontSize: 8, background: '#FEE2E2', color: '#B91C1C', padding: '2px 6px', borderRadius: 8, fontWeight: 900 }}>{item.giftApprovalStatus === 'REJECTED' ? 'REFUSÉ' : 'EN ATTENTE ADMIN'}</span>}
                      </div>
                      <div style={{ fontWeight: 900, fontSize: 16, color: isChecked ? '#8E8E93' : 'var(--orange)', marginLeft: 6 }}>
                        x{item.qty}
                      </div>
                    </div>

                    <div style={{ display: 'flex', gap: 6, alignItems: 'center', marginBottom: 6 }}>
                      <span className="size-dot" style={{ background: '#1C1C1E', color: 'white', border: 'none', scale: '0.8' }}>{item.size}</span>
                      <span style={{ fontSize: 11, color: '#8E8E93', fontWeight: 700 }}>{item.color}</span>
                    </div>

                    <div style={{ marginTop: 'auto' }}>
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                        {p?.variants?.find((v) => v.size === item.size && v.color === item.color)?.stockLevels?.map((sl) => (
                          <div key={sl.id} style={{ fontSize: 9, background: '#F2F2F7', padding: '2px 6px', borderRadius: 5, display: 'flex', alignItems: 'center', gap: 3 }}>
                            <Warehouse size={9} color="#FF6B2C" />
                            <span style={{ fontWeight: 700 }}>{sl.position || sl.warehouse.name}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
                <div className="packing-mobile-item-actions" onClick={(event) => event.stopPropagation()}>
                  <button
                    type="button"
                    className={`packing-item-choice packed ${item.packingStatus === 'PACKED' || isChecked ? 'active' : ''}`}
                    disabled={isSaving || giftBlocked}
                    onClick={(event) => { event.preventDefault(); event.stopPropagation(); if (!isChecked) onToggleCheckItem(order.id, item); }}
                  >
                    <Check size={15} /> {isChecked ? 'Emballé ✓' : 'Emballé'}
                  </button>
                  <button
                    type="button"
                          className={`packing-item-choice not-packed ${item.packingStatus === 'NOT_PACKED' ? 'active' : ''}`}
                          aria-pressed={item.packingStatus === 'NOT_PACKED'}
                    disabled={isSaving}
                    onClick={(event) => { event.preventDefault(); event.stopPropagation(); onMarkItemNotPacked(order.id, item); }}
                  >
                          {item.packingStatus === 'NOT_PACKED' ? 'Retirer “Pas emballé”' : 'Pas emballé'}
                  </button>
                  {canEditStock && <button
                    type="button"
                    className="packing-mobile-secondary-action stock"
                    disabled={!p || isSaving}
                    onClick={(event) => { event.preventDefault(); event.stopPropagation(); if (p) onEditStock(p); }}
                  >
                    <Edit2 size={15} /> Modifier stock
                  </button>}
                  <button
                    type="button"
                    className="packing-mobile-secondary-action alternative"
                    disabled={isSaving}
                    onClick={(event) => { event.preventDefault(); event.stopPropagation(); onProposeAlternative(order.id, item.name); }}
                  >
                    <ArrowLeftRight size={15} /> Alternative
                  </button>
                </div>
                {order.history?.filter((h) => h.action.includes(`Alternative proposée pour "${item.name}"`)).map((h, hi: number) => (
                  <div key={hi} style={{ margin: '0 12px 10px', padding: '8px 12px', background: 'var(--orange-soft)', borderLeft: '3px solid var(--orange)', borderRadius: 6, fontSize: 12, fontWeight: 700, color: 'var(--ink)' }}>
                    <div style={{ fontSize: 9, textTransform: 'uppercase', opacity: 0.6, marginBottom: 2 }}>Alternative :</div>
                    {h.action.split(' : ')[1]}
                  </div>
                ))}
              </DetailCard>
            );
          })}
        </div>

        <div style={{ marginTop: 20 }}>
          <SectionLabel spaced>{"Note d'emballage"}</SectionLabel>
          <textarea
            className="mobile-search-input packing-note"
            value={packingNote}
            onChange={e => setPackingNote(e.target.value)}
            placeholder="Note optionnelle..."
            style={{ height: 80, padding: 12, fontSize: 13, background: '#F2F2F7', border: 'none', borderRadius: 12, width: '100%' }}
          />
        </div>
      </Modal>
    );
  }

  // DESKTOP VIEW
  return (
    <Modal isOpen={true} onClose={onClose} title={`Emballage · ${order.ref}`} large
      footer={
        <>
          <button className="btn-secondary" onClick={onClose}>Fermer</button>
          {order.status === 'PACKED' ? (
            <button className="btn-secondary" onClick={() => onMarkPacking(order.id, 'CONFIRMED')} disabled={isPending} style={{ background: '#FEE2E2', color: '#EF4444', borderColor: '#FCA5A5' }}>
              <ArrowLeftRight size={14} /> Annuler l&apos;emballage
            </button>
          ) : (
            <>
              <button className="btn-secondary" onClick={() => onMarkPacking(order.id, 'UNAVAILABLE')} disabled={isPending} style={{ borderColor: 'var(--red)', color: 'var(--red)' }}>
                Pas en stock
              </button>
              <button className="btn-secondary" onClick={() => onMarkPacking(order.id, 'PARTIAL')} disabled={isPending || !isPartial} title={!isPartial ? "Cochez au moins un article et laissez les articles manquants décochés" : undefined} style={{ borderColor: 'var(--amber)', color: 'var(--amber)' }}>
                Incomplet
              </button>
              <button className="btn-orange" onClick={() => onMarkPacking(order.id, 'PACKED')} disabled={isPending || !isComplete} title={!isComplete ? "Emballez tous les articles avant de valider" : undefined}>
                <Check size={14} /> Prêt pour livraison ✓
              </button>
            </>
          )}
        </>
      }
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <div>
          <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 800, color: 'var(--orange)', fontSize: 20 }}>{order.ref}</div>
          <div style={{ fontWeight: 700, marginTop: 4 }}>{order.customerName} · {order.commune}</div>
          <div style={{ display: 'flex', gap: 8, marginTop: 6 }}>
            {order.commercialName && <span style={{ fontSize: 10, fontWeight: 700, background: '#E8F4FD', color: '#0A84FF', padding: '2px 8px', borderRadius: 6 }}>🛒 {order.commercialName}</span>}
            {order.packedByName && <span style={{ fontSize: 10, fontWeight: 700, background: '#F2FBF4', color: '#34C759', padding: '2px 8px', borderRadius: 6 }}>📦 {order.packedByName}</span>}
          </div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--brown-soft)', marginBottom: 4 }}>PROGRESSION</div>
          <div style={{ fontWeight: 800, fontSize: 18 }}>{progress} / {total}</div>
        </div>
      </div>

      <SectionLabel>{"Checklist de l'emballeur"}</SectionLabel>
      {order.items.map((item, idx: number) => {
        const p = productMap.get(item.productId || "");
        const isChecked = (item.packingStatus === 'PACKED');
        const isSaving = savingChecks.has(item.id);
        const giftBlocked = item.isGift && item.giftApprovalStatus !== 'APPROVED';
        return (
          <DetailCard
            key={idx}
            className={`packing-checklist-card ${isChecked ? 'checked' : ''}`}
            style={{
              marginBottom: 12,
              border: isSaving ? '1.5px solid var(--orange)' : undefined,
              opacity: isSaving ? 0.75 : 1,
              animation: isSaving ? 'pulse-border 1s ease infinite' : 'none',
              transition: 'all 0.2s ease',
              position: 'relative' as const,
              pointerEvents: isSaving ? 'none' as const : 'auto' as const,
            }}
            onClick={() => { if (!giftBlocked) onToggleCheckItem(order.id, item); }}
          >
            {isSaving && (
              <div style={{
                position: 'absolute', top: 8, right: 10,
                padding: '3px 8px',
                background: 'var(--orange)',
                color: 'white',
                fontSize: 9,
                fontWeight: 800,
                borderRadius: 6,
                zIndex: 2,
                display: 'flex',
                alignItems: 'center',
                gap: 4,
                letterSpacing: '0.05em',
              }}>
                <Loader2 size={10} style={{ animation: 'spin 0.8s linear infinite' }} />
                ENREGISTREMENT
              </div>
            )}
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 28, height: 28, borderRadius: 8, border: '2px solid', borderColor: isChecked ? 'var(--green)' : 'var(--line)', background: isChecked ? 'var(--green-soft)' : 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, marginTop: 4 }}>
                {savingChecks.has(item.id)
                  ? <Loader2 size={16} color="var(--brown-soft)" style={{ animation: 'spin 0.8s linear infinite' }} />
                  : isChecked && <Check size={18} color="var(--green)" />
                }
              </div>
              <div style={{ width: 60, height: 60, background: 'var(--cream-2)', borderRadius: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 28, flexShrink: 0, overflow: 'hidden', border: '1px solid var(--line)' }}>
                {item.image ? <img src={item.image} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} onClick={(e) => { e.stopPropagation(); onPreviewImage(item.image!, item.name, item.size, item.color); }} /> : (item.emoji || '📦')}
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 15, textDecoration: isChecked ? 'line-through' : 'none', display: 'flex', alignItems: 'center', gap: 6 }}>
                      {item.name}
                      {item.isGift && <span style={{ fontSize: 9, background: 'var(--orange-soft)', color: 'var(--orange)', padding: '1px 6px', borderRadius: 10, fontWeight: 800, textTransform: 'uppercase' }}>Cadeau</span>}
                      {giftBlocked && <span style={{ fontSize: 8, background: '#FEE2E2', color: '#B91C1C', padding: '2px 6px', borderRadius: 8, fontWeight: 900 }}>{item.giftApprovalStatus === 'REJECTED' ? 'REFUSÉ' : 'EN ATTENTE ADMIN'}</span>}
                    </div>
                    <div style={{ fontSize: 13, color: 'var(--brown-soft)', marginTop: 4 }}>
                      Taille : {item.size} | Couleur : {item.color} | Qté : x{item.qty}
                    </div>
                    {order.history?.filter((h) => h.action.includes(`Alternative proposée pour "${item.name}"`)).map((h, hi: number) => (
                      <div key={hi} style={{ fontSize: 10, color: 'var(--orange)', background: 'var(--orange-soft)', padding: '1px 6px', borderRadius: 4, fontWeight: 700, marginTop: 4 }}>
                        {h.action.split(' : ')[1]}
                      </div>
                    ))}
                  </div>
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button
                      type="button"
                      className={`packing-item-choice packed ${item.packingStatus === 'PACKED' || isChecked ? 'active' : ''}`}
                      disabled={isSaving || giftBlocked}
                      onClick={(event) => { event.stopPropagation(); if (!isChecked) onToggleCheckItem(order.id, item); }}
                    >
                      {isChecked ? 'Emballé ✓' : 'Emballé'}
                    </button>
                    <button
                      type="button"
                    className={`packing-item-choice not-packed ${item.packingStatus === 'NOT_PACKED' ? 'active' : ''}`}
                    aria-pressed={item.packingStatus === 'NOT_PACKED'}
                      disabled={isSaving}
                      onClick={(event) => { event.stopPropagation(); onMarkItemNotPacked(order.id, item); }}
                    >
                    {item.packingStatus === 'NOT_PACKED' ? 'Retirer “Pas emballé”' : 'Pas emballé'}
                    </button>
                    {canEditStock && <button
                      className="action-btn"
                      onClick={(e) => { e.stopPropagation(); if (p) onEditStock(p); }}
                      title="Modifier Stock"
                    >
                      <Edit2 size={14} />
                    </button>}
                    <button className="action-btn" onClick={(e) => { e.stopPropagation(); onProposeAlternative(order.id, item.name); }}><ArrowLeftRight size={14} /></button>
                  </div>
                </div>
              </div>
            </div>
          </DetailCard>
        );
      })}

      <div style={{ marginTop: 20 }}>
        <SectionLabel>{"Note d'emballage"}</SectionLabel>
        <textarea className="field-input packing-note" value={packingNote} onChange={e => setPackingNote(e.target.value)} style={{ minHeight: 80 }} placeholder="Ajoutez une précision utile pour l'équipe…" />
      </div>
    </Modal>
  );
}

"use client";

import React, { useState } from "react";
import Modal from "@/components/Modal";
import { PackingProductVariant, ProductWithVariants } from "../types";
import { getProductVariantsById, updateProductVariantStockLevels } from "@/modules/products/actions/actions";
import { getMediaFiles, uploadMediaFile } from "@/modules/media/actions";
import { processImageFile } from "@/lib/image-upload-helper";
import { AlertTriangle, Image as ImageIcon, MapPin, Minus, Plus, RefreshCw, Search, Upload, Warehouse, X } from "lucide-react";
import { getImageUrl } from "@/lib/utils";
import { clearStaleServerActionReloadFlag, reloadOnStaleServerAction } from "@/lib/stale-server-action";

type EditableStockLevel = {
  id?: string;
  warehouseId?: string;
  warehouseName: string;
  quantity: number;
  position?: string;
};

type EditableVariant = Omit<PackingProductVariant, "stockLevels"> & {
  stockLevels: EditableStockLevel[];
  image?: string | null;
};

type MediaFile = {
  name: string;
  url: string;
  size: number;
  createdAt: string | Date;
};

interface VariantsEditorModalProps {
  product: ProductWithVariants;
  variants?: PackingProductVariant[];
  onClose: () => void;
  onSave?: (variants: EditableVariant[]) => void;
}

export default function VariantsEditorModal({ product, variants: initialVariants, onClose, onSave }: VariantsEditorModalProps) {
  const hasInitialStockLevels = (initialVariants || []).some((variant) => Array.isArray(variant.stockLevels));

  const normalizeVariant = React.useCallback((variant: PackingProductVariant): EditableVariant => {
    const stockLevels = variant.stockLevels?.length
      ? variant.stockLevels.map((level) => ({
        id: level.id,
        warehouseId: level.warehouseId,
        warehouseName: level.warehouse?.name || "Entrepot",
        quantity: Math.max(0, Number(level.quantity) || 0),
        position: level.position || "",
      }))
      : [{
        warehouseId: undefined,
        warehouseName: "Magasin Principal",
        quantity: Math.max(0, Number(variant.stock) || 0),
        position: variant.location || "",
      }];

    return {
      ...variant,
      stock: stockLevels.reduce((sum, level) => sum + level.quantity, 0),
      location: stockLevels.find((level) => level.position)?.position || variant.location || "",
      stockLevels,
    };
  }, []);

  const [variants, setVariants] = useState<EditableVariant[]>(() => (initialVariants || []).map(normalizeVariant));
  const [lowStockThreshold, setLowStockThreshold] = useState(product.lowStockThreshold || 5);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [mediaFiles, setMediaFiles] = useState<MediaFile[]>([]);
  const [galleryVariantIndex, setGalleryVariantIndex] = useState<number | null>(null);
  const [gallerySearch, setGallerySearch] = useState("");
  const [uploadingVariantIndex, setUploadingVariantIndex] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  React.useEffect(() => {
    let active = true;
    setIsLoading(true);
    setError(null);

    getProductVariantsById(product.id)
      .then((fetchedVariants) => {
        if (!active) return;
        clearStaleServerActionReloadFlag();
        setVariants(fetchedVariants.map((variant: PackingProductVariant) => normalizeVariant(variant)));
      })
      .catch((error) => {
        if (reloadOnStaleServerAction(error)) return;
        if (!active) return;
        setError(hasInitialStockLevels ? null : "Impossible de charger les stocks en direct.");
      })
      .finally(() => {
        if (active) setIsLoading(false);
      });

    getMediaFiles()
      .then((files) => {
        if (active) {
          clearStaleServerActionReloadFlag();
          setMediaFiles(files as MediaFile[]);
        }
      })
      .catch((error) => {
        reloadOnStaleServerAction(error);
      });

    return () => {
      active = false;
    };
  }, [hasInitialStockLevels, normalizeVariant, product.id]);

  const updateStockLevel = (
    variantIndex: number,
    stockLevelIndex: number,
    field: "quantity" | "position",
    value: string | number,
  ) => {
    setVariants((current) => current.map((variant, currentVariantIndex) => {
      if (currentVariantIndex !== variantIndex) return variant;

      const stockLevels = variant.stockLevels.map((level, currentLevelIndex) => {
        if (currentLevelIndex !== stockLevelIndex) return level;
        return {
          ...level,
          [field]: field === "quantity" ? Math.max(0, parseInt(String(value), 10) || 0) : String(value),
        };
      });

      return {
        ...variant,
        stockLevels,
        stock: stockLevels.reduce((sum, level) => sum + level.quantity, 0),
        location: stockLevels.find((level) => level.position)?.position || "",
      };
    }));
  };

  const updateVariantImage = (variantIndex: number, image: string) => {
    setVariants((current) => current.map((variant, currentVariantIndex) => (
      currentVariantIndex === variantIndex ? { ...variant, image } : variant
    )));
  };

  const handleVariantImageUpload = (variantIndex: number, file: File) => {
    if (!file.type.startsWith("image/")) {
      setError("Seules les images sont autorisees.");
      return;
    }

    const reader = new FileReader();
    setUploadingVariantIndex(variantIndex);
    setError(null);

    reader.onload = async () => {
      try {
        const { dataUrl, fileName } = await processImageFile(file);
        const result = await uploadMediaFile(dataUrl, fileName);

        if (!result.success || !result.url) {
          setError(result.error || "Erreur lors de l'upload de l'image.");
          return;
        }

        const uploaded: MediaFile = {
          name: result.url.split("/").pop() || file.name,
          url: result.url,
          size: file.size,
          createdAt: new Date(),
        };

        setMediaFiles((current) => [uploaded, ...current]);
        updateVariantImage(variantIndex, result.url);
      } catch (error) {
        if (reloadOnStaleServerAction(error)) return;
        setError("Erreur lors de l'upload de l'image.");
      } finally {
        setUploadingVariantIndex(null);
      }
    };

    reader.onerror = () => {
      setUploadingVariantIndex(null);
      setError("Erreur lors de la lecture de l'image.");
    };

    reader.readAsDataURL(file);
  };

  const filteredMediaFiles = React.useMemo(() => (
    mediaFiles.filter((file) => file.name.toLowerCase().includes(gallerySearch.toLowerCase()))
  ), [gallerySearch, mediaFiles]);

  const totalQty = variants.reduce(
    (sum, variant) => sum + variant.stockLevels.reduce((levelSum, level) => levelSum + level.quantity, 0),
    0,
  );

  const handleSave = async () => {
    setIsSaving(true);
    setError(null);

    try {
      await updateProductVariantStockLevels(product.id, {
        lowStockThreshold,
        variants: variants.map((variant) => ({
          id: variant.id,
          size: variant.size,
          color: variant.color,
          image: variant.image || null,
          stock: variant.stock,
          location: variant.location || undefined,
          stockLevels: variant.stockLevels.map((level) => ({
            id: level.id,
            warehouseId: level.warehouseId,
            warehouseName: level.warehouseName,
            quantity: level.quantity,
            position: level.position || undefined,
          })),
        })),
      });

      if (onSave) onSave(variants);
      else onClose();
    } catch (error) {
      if (reloadOnStaleServerAction(error)) return;
      setError("Erreur lors de l'enregistrement des stocks.");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Modal
      isOpen={true}
      onClose={onClose}
      title={
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <RefreshCw size={18} className="text-orange" />
          <span>Gestion du Stock</span>
        </div>
      }
      large
      footer={
        <div style={{ display: "flex", gap: 12, width: "100%" }}>
          <button className="btn-secondary" style={{ flex: 1 }} onClick={onClose} disabled={isLoading || isSaving}>
            Annuler
          </button>
          <button
            className="btn-orange"
            onClick={handleSave}
            disabled={isLoading || isSaving}
            style={{ flex: 1, display: "flex", alignItems: "center", gap: 6, justifyContent: "center" }}
          >
            {isSaving && <span className="animate-spin" style={{ display: "inline-block", width: 14, height: 14, border: "2px solid white", borderTopColor: "transparent", borderRadius: "50%" }} />}
            <span className="stock-save-label-full">{isSaving ? "Sauvegarde..." : "Enregistrer les modifications"}</span>
            <span className="stock-save-label-short">{isSaving ? "..." : "Enregistrer"}</span>
          </button>
        </div>
      }
    >
      <div className="variants-editor-header">
        <div className="editor-product-info">
          {product.images?.[0] ? (
            <img src={getImageUrl(product.images[0].url)} className="editor-thumb" alt={product.name} />
          ) : (
            <div className="editor-thumb-placeholder">PKG</div>
          )}
          <div>
            <h3>{product.name}</h3>
            <p>
              Stock total : <span className={totalQty === 0 ? "text-red" : "text-green"}>{totalQty} unités</span>
            </p>
          </div>
        </div>
        <div className="threshold-config">
          <label>Seuil d&apos;alerte</label>
          <div className="threshold-input-wrapper">
            <input
              type="number"
              min={0}
              value={lowStockThreshold}
              onChange={(event) => setLowStockThreshold(Math.max(0, parseInt(event.target.value, 10) || 0))}
            />
            <AlertTriangle size={14} className="threshold-icon" />
          </div>
        </div>
      </div>

      {isLoading ? (
        <div style={{ padding: "40px 0", textAlign: "center", color: "var(--brown-soft)", fontSize: 13, display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
          <span className="animate-spin" style={{ display: "inline-block", width: 16, height: 16, border: "2px solid var(--orange)", borderTopColor: "transparent", borderRadius: "50%" }} />
          Chargement des stocks en direct...
        </div>
      ) : error ? (
        <div style={{ padding: "18px 20px", background: "#FEE2E2", color: "#B91C1C", borderRadius: 12, fontWeight: 700, fontSize: 13 }}>
          {error}
        </div>
      ) : (
        <div className="variants-editor-grid">
          {variants.map((variant, variantIndex) => (
            <div key={variant.id || `${variant.size}-${variant.color}-${variantIndex}`} className="variant-edit-card">
              <div className="v-card-header">
                <div style={{ width: 42, height: 48, borderRadius: 8, overflow: "hidden", background: "var(--cream-2)", border: "1px solid var(--border)", flexShrink: 0 }}>
                  {variant.image ? (
                    <img src={getImageUrl(variant.image)} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  ) : product.images?.[0] ? (
                    <img src={getImageUrl(product.images[0].url)} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", opacity: 0.45 }} />
                  ) : (
                    <span style={{ width: "100%", height: "100%", display: "grid", placeItems: "center", fontSize: 10, fontWeight: 900, color: "var(--muted)" }}>IMG</span>
                  )}
                </div>
                <span className="v-card-tag">{variant.size}</span>
                <span className="v-card-color-name">{variant.color}</span>
                <span className="variant-total-pill">
                  {variant.stockLevels.reduce((sum, level) => sum + level.quantity, 0)} u.
                </span>
              </div>

              <div className="v-card-controls">
                <div className="stock-level-editor" data-first="true">
                  <div className="stock-level-warehouse">
                    <ImageIcon size={14} className="text-orange" />
                    <span>Image de la variante</span>
                  </div>
                  <div style={{ display: "grid", gap: 8 }}>
                    <input
                      type="text"
                      value={variant.image || ""}
                      onChange={(event) => updateVariantImage(variantIndex, event.target.value)}
                      placeholder="URL image ou selection galerie"
                      className="field-input"
                    />
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                      <label className="btn-secondary" style={{ cursor: uploadingVariantIndex === variantIndex ? "not-allowed" : "pointer" }}>
                        <input
                          type="file"
                          accept="image/*"
                          disabled={uploadingVariantIndex === variantIndex}
                          style={{ display: "none" }}
                          onChange={(event) => {
                            const file = event.target.files?.[0];
                            if (file) handleVariantImageUpload(variantIndex, file);
                            event.target.value = "";
                          }}
                        />
                        <Upload size={14} /> {uploadingVariantIndex === variantIndex ? "Upload..." : "Uploader"}
                      </label>
                      <button type="button" className="btn-secondary" onClick={() => setGalleryVariantIndex(variantIndex)}>
                        <ImageIcon size={14} /> Galerie
                      </button>
                      {variant.image && (
                        <button type="button" className="btn-secondary" onClick={() => updateVariantImage(variantIndex, "")}>
                          <X size={14} /> Retirer
                        </button>
                      )}
                    </div>
                  </div>
                </div>
                {variant.stockLevels.map((level, stockLevelIndex) => (
                  <div
                    key={level.id || `${level.warehouseName}-${stockLevelIndex}`}
                    className="stock-level-editor"
                    data-first={stockLevelIndex === 0 ? "true" : "false"}
                  >
                    <div className="stock-level-warehouse">
                      <Warehouse size={14} className="text-orange" />
                      <span>{level.warehouseName}</span>
                    </div>

                    <div className="control-group">
                      <label>Quantité en stock</label>
                      <div className="qty-stepper">
                        <button onClick={() => updateStockLevel(variantIndex, stockLevelIndex, "quantity", level.quantity - 1)}><Minus size={14} /></button>
                        <input
                          type="number"
                          min={0}
                          value={level.quantity}
                          onChange={(event) => updateStockLevel(variantIndex, stockLevelIndex, "quantity", event.target.value)}
                        />
                        <button onClick={() => updateStockLevel(variantIndex, stockLevelIndex, "quantity", level.quantity + 1)}><Plus size={14} /></button>
                      </div>
                    </div>

                    <div className="control-group">
                      <label>Emplacement (Rayon/Casier)</label>
                      <div className="location-input-wrapper">
                        <MapPin size={14} className="loc-icon" />
                        <input
                          type="text"
                          value={level.position || ""}
                          onChange={(event) => updateStockLevel(variantIndex, stockLevelIndex, "position", event.target.value)}
                          placeholder="Ex: A1-02"
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
      {galleryVariantIndex !== null && (
        <div style={{ position: "fixed", inset: 0, zIndex: 3000, background: "rgba(26,20,16,0.52)", backdropFilter: "blur(4px)", display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
          <div style={{ width: "min(900px, 100%)", maxHeight: "84vh", background: "#fff", borderRadius: 12, overflow: "hidden", display: "grid", gridTemplateRows: "auto auto minmax(0, 1fr)", boxShadow: "0 24px 80px rgba(0,0,0,0.25)" }}>
            <div style={{ padding: 18, borderBottom: "1px solid var(--border)", display: "flex", justifyContent: "space-between", gap: 12, alignItems: "center" }}>
              <div>
                <div className="table-title">Choisir une image de variante</div>
                <div className="table-meta">{filteredMediaFiles.length} image(s)</div>
              </div>
              <button className="btn-secondary" onClick={() => setGalleryVariantIndex(null)}>
                <X size={14} /> Fermer
              </button>
            </div>
            <div style={{ margin: 14, height: 42, border: "1px solid var(--border)", borderRadius: 8, display: "flex", alignItems: "center", gap: 10, padding: "0 12px", color: "var(--muted)" }}>
              <Search size={16} />
              <input
                value={gallerySearch}
                onChange={(event) => setGallerySearch(event.target.value)}
                placeholder="Rechercher dans la galerie..."
                style={{ flex: 1, border: "none", outline: "none", color: "var(--ink)", fontSize: 13 }}
              />
            </div>
            <div style={{ padding: "0 14px 14px", overflowY: "auto", display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(130px, 1fr))", gap: 10 }}>
              {filteredMediaFiles.map((file) => (
                <button
                  key={file.url}
                  type="button"
                  onClick={() => {
                    updateVariantImage(galleryVariantIndex, file.url);
                    setGalleryVariantIndex(null);
                  }}
                  style={{ border: "1px solid var(--border)", borderRadius: 8, background: "#fff", overflow: "hidden", padding: 0, cursor: "pointer", textAlign: "left" }}
                >
                  <img src={file.url} alt={file.name} style={{ width: "100%", aspectRatio: "1 / 1", objectFit: "cover", display: "block" }} />
                  <span style={{ display: "block", padding: 8, fontSize: 10, fontWeight: 800, color: "var(--muted)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{file.name}</span>
                </button>
              ))}
              {filteredMediaFiles.length === 0 && (
                <div style={{ gridColumn: "1 / -1", padding: 28, textAlign: "center", color: "var(--muted)", border: "1px dashed var(--border)", borderRadius: 8 }}>
                  Aucune image trouvee.
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </Modal>
  );
}

