"use server";

import { S3Client, ListObjectsV2Command, DeleteObjectCommand } from "@aws-sdk/client-s3";
import { ensureAuth } from "../../lib/auth";
import { revalidatePath } from "next/cache";
import { uploadImage } from "../../lib/upload";

/**
 * Cloudflare R2 Client Configuration for Media Actions
 */
const r2Client = new S3Client({
  region: "auto",
  endpoint: `https://${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`,
  credentials: {
    accessKeyId: process.env.R2_ACCESS_KEY_ID || "",
    secretAccessKey: process.env.R2_SECRET_ACCESS_KEY || "",
  },
});

/**
 * Récupère la liste des fichiers depuis Cloudflare R2.
 */
export async function getMediaFiles() {
  await ensureAuth(["admin", "stock", "commercial"]);
  
  try {
    const command = new ListObjectsV2Command({
      Bucket: process.env.R2_BUCKET_NAME,
    });

    const response = await r2Client.send(command);
    
    if (!response.Contents) return [];

    const mediaFiles = response.Contents.map((file) => ({
      name: file.Key!,
      url: `${process.env.R2_PUBLIC_URL}/${file.Key}`,
      size: file.Size || 0,
      createdAt: file.LastModified || new Date(),
    }));

    // Trier par date décroissante
    return mediaFiles.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  } catch (error) {
    console.error("Erreur lors de la lecture des médias R2:", error);
    return [];
  }
}

/**
 * Supprime un fichier média depuis Cloudflare R2.
 */
export async function deleteMediaFile(fileName: string) {
  await ensureAuth(["admin", "stock"]);
  
  try {
    const command = new DeleteObjectCommand({
      Bucket: process.env.R2_BUCKET_NAME,
      Key: fileName,
    });

    await r2Client.send(command);
    
    revalidatePath("/zangochap-manager/media");
    return { success: true };
  } catch (error: any) {
    console.error("Erreur suppression média R2:", error);
    return { success: false, error: error.message };
  }
}

/**
 * Upload un fichier média vers Cloudflare R2.
 */
export async function uploadMediaFile(dataUrl: string, fileName: string) {
  await ensureAuth(["admin", "stock", "commercial"]);
  
  try {
    const url = await uploadImage(dataUrl, fileName);
    revalidatePath("/zangochap-manager/media");
    return { success: true, url };
  } catch (error: any) {
    console.error("Erreur upload média R2:", error);
    return { success: false, error: error.message };
  }
}

"use server";

import prisma from "@/lib/prisma";
import { ensureAuth } from "@/lib/auth";
import { randomUUID } from "crypto";
import {
  MAX_STAFF_NOTES,
  normalizeStaffNote,
  normalizeStaffNotes,
  StaffNote,
  StaffNotePriority,
} from "./types";

const NOTES_ROLES = ["admin", "commercial"];
const notesKey = (userId: string) => `staff-notes:${userId}`;

async function readNotes(userId: string): Promise<StaffNote[]> {
  const row = await prisma.cmsContent.findUnique({
    where: { key: notesKey(userId) },
    select: { data: true },
  });
  return normalizeStaffNotes(row?.data);
}

async function writeNotes(userId: string, email: string, notes: StaffNote[]) {
  const clean = normalizeStaffNotes(notes);
  await prisma.cmsContent.upsert({
    where: { key: notesKey(userId) },
    update: { data: clean as any, updatedBy: email },
    create: { key: notesKey(userId), data: clean as any, updatedBy: email },
  });
  return clean;
}

export async function getMyStaffNotes(): Promise<StaffNote[]> {
  const session = await ensureAuth(NOTES_ROLES);
  return readNotes(session.id);
}

export async function upsertMyStaffNote(input: {
  id?: string;
  text: string;
  priority?: StaffNotePriority;
  reminderAt?: string | null;
  pinned?: boolean;
  contextUrl?: string | null;
  contextLabel?: string | null;
}): Promise<{ success: true; note: StaffNote; notes: StaffNote[] }> {
  const session = await ensureAuth(NOTES_ROLES);
  const text = (input.text || "").trim();
  if (!text) throw new Error("La note ne peut pas être vide.");

  const notes = await readNotes(session.id);
  const now = new Date().toISOString();
  const existing = input.id ? notes.find((n) => n.id === input.id) : undefined;

  const note = normalizeStaffNote({
    ...(existing || {
      id: randomUUID(),
      done: false,
      pinned: false,
      createdAt: now,
    }),
    text,
    priority: input.priority ?? existing?.priority ?? "normal",
    reminderAt: input.reminderAt === undefined ? existing?.reminderAt ?? null : input.reminderAt,
    // Un nouveau rappel repart non-acquitté
    reminderDone: input.reminderAt !== undefined && input.reminderAt !== existing?.reminderAt
      ? false
      : existing?.reminderDone ?? false,
    pinned: input.pinned ?? existing?.pinned ?? false,
    contextUrl: input.contextUrl === undefined ? existing?.contextUrl ?? null : input.contextUrl,
    contextLabel: input.contextLabel === undefined ? existing?.contextLabel ?? null : input.contextLabel,
    updatedAt: now,
  });
  if (!note) throw new Error("Note invalide.");

  const next = existing
    ? notes.map((n) => (n.id === note.id ? note : n))
    : [note, ...notes];

  if (next.length > MAX_STAFF_NOTES) {
    throw new Error(`Limite de ${MAX_STAFF_NOTES} notes atteinte. Supprime des notes terminées.`);
  }

  const saved = await writeNotes(session.id, session.email, next);
  return { success: true, note, notes: saved };
}

export async function patchMyStaffNote(id: string, patch: {
  done?: boolean;
  pinned?: boolean;
  reminderDone?: boolean;
  reminderAt?: string | null;
}): Promise<{ success: true; notes: StaffNote[] }> {
  const session = await ensureAuth(NOTES_ROLES);
  const notes = await readNotes(session.id);
  const target = notes.find((n) => n.id === id);
  if (!target) throw new Error("Note introuvable.");

  const now = new Date().toISOString();
  const next = notes.map((n) => {
    if (n.id !== id) return n;
    const updated: StaffNote = { ...n, updatedAt: now };
    if (patch.done !== undefined) {
      updated.done = patch.done;
      // Marquer terminé acquitte aussi le rappel
      if (patch.done) updated.reminderDone = true;
    }
    if (patch.pinned !== undefined) updated.pinned = patch.pinned;
    if (patch.reminderDone !== undefined) updated.reminderDone = patch.reminderDone;
    if (patch.reminderAt !== undefined) {
      updated.reminderAt = patch.reminderAt;
      // Nouveau rappel (snooze) => non-acquitté
      if (patch.reminderAt) updated.reminderDone = false;
    }
    return updated;
  });

  const saved = await writeNotes(session.id, session.email, next);
  return { success: true, notes: saved };
}

export async function deleteMyStaffNote(id: string): Promise<{ success: true; notes: StaffNote[] }> {
  const session = await ensureAuth(NOTES_ROLES);
  const notes = await readNotes(session.id);
  const saved = await writeNotes(session.id, session.email, notes.filter((n) => n.id !== id));
  return { success: true, notes: saved };
}

export type StaffNotePriority = "normal" | "important" | "urgent";

export type StaffNote = {
  id: string;
  text: string;
  priority: StaffNotePriority;
  /** ISO date du rappel, null si pas de rappel */
  reminderAt: string | null;
  /** Rappel acquitté (vu / snoozé traité) */
  reminderDone: boolean;
  done: boolean;
  pinned: boolean;
  /** Lien optionnel vers la page liée (ex: fiche commande) */
  contextUrl: string | null;
  contextLabel: string | null;
  createdAt: string;
  updatedAt: string;
};

export const STAFF_NOTE_PRIORITIES: StaffNotePriority[] = ["normal", "important", "urgent"];

/** Limite le poids du JSON stocké en CmsContent */
export const MAX_STAFF_NOTES = 200;

const toIsoOrNull = (value: unknown): string | null => {
  if (typeof value !== "string" || !value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
};

export function normalizeStaffNote(raw: any): StaffNote | null {
  if (!raw || typeof raw !== "object") return null;
  const text = typeof raw.text === "string" ? raw.text.trim() : "";
  const id = typeof raw.id === "string" ? raw.id : "";
  if (!id || !text) return null;

  const priority: StaffNotePriority = STAFF_NOTE_PRIORITIES.includes(raw.priority)
    ? raw.priority
    : "normal";

  const now = new Date().toISOString();
  return {
    id,
    text: text.slice(0, 2000),
    priority,
    reminderAt: toIsoOrNull(raw.reminderAt),
    reminderDone: Boolean(raw.reminderDone),
    done: Boolean(raw.done),
    pinned: Boolean(raw.pinned),
    contextUrl: typeof raw.contextUrl === "string" && raw.contextUrl.startsWith("/") ? raw.contextUrl.slice(0, 500) : null,
    contextLabel: typeof raw.contextLabel === "string" ? raw.contextLabel.slice(0, 120) : null,
    createdAt: toIsoOrNull(raw.createdAt) || now,
    updatedAt: toIsoOrNull(raw.updatedAt) || now,
  };
}

export function normalizeStaffNotes(data: unknown): StaffNote[] {
  if (!Array.isArray(data)) return [];
  return data
    .map(normalizeStaffNote)
    .filter((note): note is StaffNote => note !== null)
    .slice(0, MAX_STAFF_NOTES);
}

"use server";

import prisma from "@/lib/prisma";
import { Role } from "@prisma/client";
import { createOrderWithContext, type OrderCreationInput } from "./order-creation-service";
import { requestOrderReprogramming } from "./reprogramming-actions";
import { revalidatePath as nextRevalidatePath } from "next/cache";

function revalidatePath(path: string) {
  try {
    nextRevalidatePath(path);
  } catch (e) {
    // Safely ignore Next.js context errors in script/CLI environments
  }
}

import { getSession } from "@/modules/auth/actions";
import { ensureAuth } from "@/lib/auth";
import { uploadImage } from "@/lib/upload";
import { checkOrderAccess, generateUniqueRef } from "../helpers";
import { decrementStockForOrder, restoreStockForOrder } from "./stock";
import { recordDeveloperAudit } from "@/modules/developer/audit";

// ============ POINT RELAIS ============
// L'attribution relais vit sous forme d'une ligne marqueur dans deliveryNote,
// parsee par regex cote boutique. Ces helpers garantissent qu'une seule ligne
// marqueur existe et que les valeurs injectees ne cassent pas le parsing.
const RELAY_MARKER = "[POINT_RELAIS]";
const RELAY_COMMUNE = "boutique";

function sanitizeRelayMarkerValue(value?: string | null) {
  return String(value || "").replace(/[|\r\n]+/g, " ").trim();
}

function buildRelayMarkerLine(relayPointName: string, note?: string | null) {
  const cleanNote = sanitizeRelayMarkerValue(note);
  return `${RELAY_MARKER} Boutique: ${sanitizeRelayMarkerValue(relayPointName)}${cleanNote ? ` | Note: ${cleanNote}` : ""}`;
}

function getRelayMarkerLine(note?: string | null) {
  return String(note || "").split("\n").find((line) => line.includes(RELAY_MARKER)) || null;
}

function getRelayNameFromMarker(note?: string | null) {
  return getRelayMarkerLine(note)?.match(/Boutique:\s*([^|]+)/)?.[1]?.trim() || null;
}

function stripRelayMarker(note?: string | null) {
  const cleaned = String(note || "")
    .split("\n")
    .filter((line) => !line.includes(RELAY_MARKER))
    .join("\n")
    .trim();
  return cleaned || null;
}

// ============ GET ORDER ============
export async function getOrder(id: string) {
  const session = await ensureAuth();
  const order = await prisma.order.findUnique({
    where: { id },
    include: { items: true }
  });
  if (order && !checkOrderAccess(order, session)) {
    throw new Error("Accès refusé à cette commande.");
  }
  return order;
}

// ============ CREATE ORDER ============
export async function createOrder(data: OrderCreationInput) {
  const session = await getSession();
  if (session?.role === "commercial" && (["reprogrammé", "reprogramme", "repro-dispo"].includes(String(data.type).trim().toLowerCase()) || ["REPROGRAMMED", "REPRO_DISPO"].includes(String(data.status).toUpperCase()))) {
    throw new Error("La reprogrammation nécessite une validation administrateur. Utilisez Reprogrammer sur la commande originale.");
  }
  return createOrderWithContext(data, session);
}
// ============ CREATE PUBLIC ORDER (checkout site) ============
// Enveloppe le checkout public : capture l'erreur COTE SERVEUR et la renvoie comme
// donnee. Sans ca, Next.js masque en production le message des erreurs jetees par
// une Server Action (message generique + digest), et le client voyait une erreur
// opaque "Erreur lors de la commande" sans savoir quoi corriger.
export async function createPublicOrder(
  data: Omit<Parameters<typeof createOrder>[0], "source" | "status">,
) {
  try {
    const result = await createOrder({ ...data, source: "public", status: "TO_PROCESS" });
    return { success: true as const, order: result.order };
  } catch (e: any) {
    return { success: false as const, error: e?.message || "Impossible d'enregistrer la commande. Reessayez." };
  }
}

// ============ DELETE ORDER (SOFT DELETE) ============
export async function deleteOrder(orderId: string) {
  const session = await getSession();
  if (!session || !['ADMIN', 'COMMERCIAL', 'DEVELOPER'].includes(session.role?.toUpperCase())) throw new Error("Accès refusé");

  const order = await prisma.order.findUnique({ where: { id: orderId }, include: { items: true } });
  if (!order) throw new Error("Commande introuvable");
  if (!checkOrderAccess(order, session)) throw new Error("Accès refusé");

  // Restore stock if it was already decremented
  if (order.stockDecremented) {
    await restoreStockForOrder(order, session, 'ADJUSTMENT');
  }

  const history = Array.isArray(order.history) ? [...(order.history as any[])] : [];
  history.push({
    at: new Date().toISOString(),
    action: "Commande SUPPRIMÉE (Soft Delete)",
    by: session.email,
    byName: session.name
  });

  // Soft delete: Update status to CANCELLED and mark the ref
  await prisma.$transaction([
    prisma.order.update({
      where: { id: orderId },
      data: {
        status: 'CANCELLED',
        deletedAt: new Date(),
        ...(order.ref
          ? { ref: order.ref.startsWith('[SUPPRIMÉ]') ? order.ref : `[SUPPRIMÉ] ${order.ref}` }
          : {}),
        history,
        stockDecremented: false,
      },
    }),
    prisma.giftApprovalRequest.updateMany({
      where: { orderId, status: 'PENDING' },
      data: { status: 'CANCELLED' },
    }),
  ]);

  // Trace durable dans le log central : survit à la rotation des 50 dernières
  // commandes de la console et à une éventuelle purge physique ultérieure.
  await recordDeveloperAudit("order.delete", "success", {
    orderId: order.id,
    ref: order.ref,
    customerName: order.customerName,
    customerPhone: order.customerPhone,
    total: order.total,
    status: order.status,
    itemsCount: order.items.length,
  });

  revalidatePath("/zangochap-manager/orders");
  revalidatePath("/zangochap-manager/orders/to-process");
  revalidatePath("/zangochap-manager/dashboard");
  return { success: true };
}

// ============ UPDATE ORDER DETAILS (whitelist) ============
export async function updateOrderDetails(orderId: string, data: any) {
  const session = await getSession();
  if (!session) throw new Error("Non authentifié");
  const order = await prisma.order.findUnique({ where: { id: orderId }, include: { items: true } });
  if (!order || !checkOrderAccess(order, session)) throw new Error("Accès refusé");

  // SECURITY: whitelist only editable fields
  const ALLOWED_FIELDS = ['customerName', 'customerPhone', 'customerPhone2', 'customerLocation', 'commune', 'deliveryFee', 'deliveryNote', 'notes', 'total'] as const;
  const sanitized: Record<string, any> = {};
  for (const key of ALLOWED_FIELDS) {
    if (data[key] !== undefined) {
      sanitized[key] = (key === 'deliveryFee' || key === 'total') ? Number(data[key]) || 0 : String(data[key]);
    }
  }

  // Type de transaction : validé contre la liste connue (le modal d'édition permet de le changer)
  const ALLOWED_ORDER_TYPES = ['Standard', 'Echange', 'Express', 'Recuperation', 'Reprogrammé'];
  if (data.type !== undefined && ALLOWED_ORDER_TYPES.includes(String(data.type))) {
    if (session.role === "commercial" && data.type === "Reprogrammé" && order.type !== "Reprogrammé") {
      throw new Error("La reprogrammation nécessite une validation administrateur. Utilisez Reprogrammer.");
    }
    sanitized.type = String(data.type);
  }

  // Coherence relais : une edition libre ne doit ni orpheliner un colis relais
  // (marqueur [POINT_RELAIS] ecrase) ni passer une commande en "Boutique" sans marqueur.
  const relayFieldsTouched = ["commune", "customerLocation", "deliveryNote"].some((key) => key in sanitized);
  if (relayFieldsTouched) {
    const prevCommune = String(order.commune || "").trim().toLowerCase();
    const nextCommune = String(("commune" in sanitized ? sanitized.commune : order.commune) || "").trim().toLowerCase();
    const nextNote = "deliveryNote" in sanitized ? sanitized.deliveryNote : order.deliveryNote;

    if (nextCommune === RELAY_COMMUNE) {
      let relayName = getRelayNameFromMarker(order.deliveryNote) || String(order.customerLocation || "").trim() || null;
      const locationTouched = "customerLocation" in sanitized || "commune" in sanitized;
      if (locationTouched) {
        const requestedRelay = String(("customerLocation" in sanitized ? sanitized.customerLocation : order.customerLocation) || "").trim();
        if (!requestedRelay) {
          throw new Error("Veuillez sélectionner le point relais de livraison.");
        }
        const relayAccount = await prisma.user.findFirst({
          where: {
            role: Role.POINT_RELAIS,
            serviceLabel: { equals: requestedRelay, mode: "insensitive" },
          },
          select: { serviceLabel: true },
        });
        relayName = relayAccount?.serviceLabel?.trim() || null;
        if (!relayName) {
          throw new Error(`Aucun point relais nommé "${requestedRelay}". Sélectionnez une boutique existante.`);
        }
        sanitized.customerLocation = relayName;
      }
      if (!relayName) {
        throw new Error("Veuillez sélectionner le point relais de livraison.");
      }
      // Conserve la ligne marqueur existante (emplacement, note boutique) tant
      // qu'elle pointe vers la meme boutique ; sinon la reconstruit.
      const existingMarker = getRelayMarkerLine(order.deliveryNote);
      const markerLine = existingMarker && getRelayNameFromMarker(order.deliveryNote)?.toLowerCase() === relayName.toLowerCase()
        ? existingMarker
        : buildRelayMarkerLine(relayName);
      const rest = stripRelayMarker(nextNote);
      sanitized.deliveryNote = rest ? `${markerLine}\n${rest}` : markerLine;
    } else if (prevCommune === RELAY_COMMUNE && "commune" in sanitized) {
      // Sortie explicite du circuit relais : le marqueur ne doit pas survivre.
      sanitized.deliveryNote = stripRelayMarker(nextNote) ?? "";
    } else if ("deliveryNote" in sanitized && getRelayMarkerLine(order.deliveryNote) && !getRelayMarkerLine(nextNote)) {
      // Colis depose en boutique hors commune "Boutique" (conversion au depot) :
      // l'edition de la note ne doit pas effacer le rattachement au gerant.
      const rest = stripRelayMarker(nextNote);
      const markerLine = getRelayMarkerLine(order.deliveryNote) as string;
      sanitized.deliveryNote = rest ? `${markerLine}\n${rest}` : markerLine;
    }
  }

  const history = Array.isArray(order.history) ? [...(order.history as any[])] : [];
  history.push({ at: new Date().toISOString(), action: "Détails modifiés", by: session.email, byName: session.name });

  try {
    // Uploads R2 AVANT la transaction : les appels réseau lents feraient expirer la tx
    if (data.items && Array.isArray(data.items)) {
      for (const item of data.items) {
        if (item.isCustom && !item.image) {
          throw new Error("Une image est obligatoire pour chaque article personnalisé.");
        }
        if (item.image && item.image.startsWith('data:image')) {
          item.image = await uploadImage(item.image, `order-item-${Date.now()}`);
        }
      }
    }

    await prisma.$transaction(async (tx) => {
      const shouldReconcileStock = !!(data.items && Array.isArray(data.items) && order.stockDecremented);
      if (shouldReconcileStock) {
        await restoreStockForOrder(order, session, 'ADJUSTMENT', tx);
      }

      await tx.order.update({
        where: { id: orderId },
        data: {
          ...sanitized,
          history,
          ...(shouldReconcileStock ? { stockDecremented: false } : {}),
        },
      });

      // Handle Items update if provided
      if (data.items && Array.isArray(data.items)) {
        const existingItems = await tx.orderItem.findMany({ where: { orderId: order.id } });
        const existingIds = existingItems.map(i => i.id);
        const incomingIds = data.items.map((i: any) => i.id).filter(Boolean);
        const newlyGiftedItems = data.items.filter((item: any) => {
          if (!item.isGift) return false;
          const existingItem = existingItems.find(existing => existing.id === item.id);
          return !existingItem?.isGift;
        });
        let editGiftDecision: 'APPROVED' | 'PENDING' = 'APPROVED';
        if (session.role?.toUpperCase() === 'COMMERCIAL' && newlyGiftedItems.length > 0) {
          await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${`gift-quota:${session.id}`}))`;
          const commercial = await tx.user.findUnique({ where: { id: session.id }, select: { giftMonthlyQuota: true, giftMonthlyValueQuota: true } });
          if (!commercial) throw new Error("Commercial introuvable.");
          const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0);
          const nextMonth = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 1);
          const approved = await tx.orderItem.findMany({
            where: { isGift: true, giftCountsTowardQuota: true, giftApprovalStatus: 'APPROVED', order: { commercialId: session.id, deletedAt: null, status: { not: 'CANCELLED' }, createdAt: { gte: monthStart, lt: nextMonth } } },
            select: { qty: true, giftUnitValue: true },
          });
          const usedQuantity = approved.reduce((sum, item) => sum + item.qty, 0);
          const usedValue = approved.reduce((sum, item) => sum + item.qty * item.giftUnitValue, 0);
          const requestedQuantity = newlyGiftedItems.reduce((sum: number, item: any) => sum + (parseInt(item.qty) || 1), 0);
          const requestedValue = newlyGiftedItems.reduce((sum: number, item: any) => sum + (parseInt(item.qty) || 1) * (Number(item.originalPrice) || 0), 0);
          const exceeded = usedQuantity + requestedQuantity > commercial.giftMonthlyQuota
            || (commercial.giftMonthlyValueQuota > 0 && usedValue + requestedValue > commercial.giftMonthlyValueQuota);
          if (exceeded) {
            if (!data.giftRequestReason?.trim()) throw new Error("GIFT_APPROVAL_REQUIRED:Quota cadeau dépassé. Une autorisation administrateur est nécessaire.");
            editGiftDecision = 'PENDING';
          }
        }

        // Delete items that were removed
        const toDelete = existingIds.filter(id => !incomingIds.includes(id));
        if (toDelete.length > 0) {
          await tx.orderItem.deleteMany({ where: { id: { in: toDelete } } });
        }

        // Upsert items (images déjà uploadées avant la transaction)
        for (const item of data.items) {
          const imageUrl = item.image;

          const isExisting = item.id && existingIds.includes(item.id);
          const existingItem = existingItems.find(existing => existing.id === item.id);
          const isNewGift = Boolean(item.isGift && !existingItem?.isGift);
          const itemData = {
            productId: item.productId || null,
            variantId: item.variantId || null,
            name: item.name,
            size: item.size || '-',
            color: item.color || '-',
            qty: parseInt(item.qty) || 1,
            price: parseInt(item.price) || 0,
            emoji: item.emoji,
            image: imageUrl,
            isCustom: item.isCustom || false,
            isGift: item.isGift || false,
            ...(!item.isGift ? { giftCountsTowardQuota: false, giftUnitValue: 0, giftApprovalStatus: null } : {}),
            ...(isNewGift ? {
              giftCountsTowardQuota: true,
              giftUnitValue: Number(item.originalPrice) || 0,
              giftApprovalStatus: editGiftDecision,
            } : {}),
          };

          let savedItem;
          if (isExisting) {
            savedItem = await tx.orderItem.update({
              where: { id: item.id },
              data: itemData
            });
          } else {
            savedItem = await tx.orderItem.create({
              data: {
                ...itemData,
                orderId: order.id
              }
            });
          }
          if (!item.isGift && existingItem?.isGift) {
            await tx.giftApprovalRequest.updateMany({ where: { orderItemId: savedItem.id, status: 'PENDING' }, data: { status: 'CANCELLED' } });
          }
          if (isNewGift && editGiftDecision === 'PENDING') {
            await tx.giftApprovalRequest.create({
              data: {
                commercialId: session.id as string,
                commercialName: session.name,
                orderId: order.id,
                orderRef: order.ref,
                orderItemId: savedItem.id,
                giftName: savedItem.name,
                quantity: savedItem.qty,
                unitValue: savedItem.giftUnitValue,
                reason: data.giftRequestReason.trim(),
              },
            });
            await tx.chatMessage.create({
              data: {
                body: `🎁 Demande cadeau de ${session.name} pour la commande ${order.ref || order.id}. Motif : ${data.giftRequestReason.trim()}`,
                scope: 'ROLE', targetRole: 'ADMIN', senderId: session.id,
                senderName: session.name, senderRole: session.role as Role,
              },
            });
          }
        }

        if (shouldReconcileStock) {
          const updatedOrder = await tx.order.findUnique({
            where: { id: order.id },
            include: { items: true },
          });
          if (!updatedOrder) throw new Error("Commande introuvable après mise à jour");
          await decrementStockForOrder(updatedOrder, session, tx);
        }
      }
    }, { timeout: 15000 });
    revalidatePath("/zangochap-manager/orders");
  } catch (e: any) {
    console.error("Order Details Update Error:", e);
    throw new Error(e.message || "Erreur lors de la mise à jour des détails");
  }
}

// ============ ADD HISTORY ENTRY ============
export async function addOrderHistoryEntry(orderId: string, action: string) {
  const session = await getSession();
  if (!session) return;
  const order = await prisma.order.findUnique({ where: { id: orderId } });
  if (!order) return;
  if (!checkOrderAccess(order, session)) return;
  const history = Array.isArray(order.history) ? [...(order.history as any[])] : [];
  history.push({ at: new Date().toISOString(), action, by: session.email, byName: session.name });
  await prisma.order.update({ where: { id: orderId }, data: { history } });
}

// ============ HAND OFF WEB ORDER TO CALL CENTER ============
export async function takeToProcessOrder(orderId: string, commercialId?: string) {
  const session = await getSession();
  if (!session) throw new Error("Non authentifié");

  const role = session.role?.toUpperCase();
  if (!['ADMIN', 'COMMERCIAL'].includes(role)) throw new Error("Accès refusé");

  const assigneeId = role === 'ADMIN' && commercialId ? commercialId : session.id;
  const assignee = await prisma.user.findUnique({
    where: { id: assigneeId },
    select: { id: true, name: true, email: true, role: true },
  });
  if (!assignee || !['ADMIN', 'COMMERCIAL'].includes(assignee.role)) {
    throw new Error("Call center introuvable");
  }

  const order = await prisma.order.findUnique({ where: { id: orderId } });
  if (!order || order.deletedAt) throw new Error("Commande introuvable");
  if (order.status !== 'TO_PROCESS') throw new Error("Cette commande est déjà prise en charge");

  const history = Array.isArray(order.history) ? [...(order.history as any[])] : [];
  history.push({
    at: new Date().toISOString(),
    action: `Commande prise en charge par ${assignee.name}`,
    by: session.email,
    byName: session.name,
  });

  // Les commandes du site sont creees sans date de livraison : au moment de
  // leur prise en charge, planifier le prochain jour livrable (jamais dimanche).
  // Une date deja renseignee reste prioritaire.
  const now = new Date();
  const nextDeliveryOffset = now.getDay() === 6 ? 2 : 1;
  const nextDeliveryDate = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate() + nextDeliveryOffset,
    0,
    0,
    0,
    0,
  );

  let updatedOrder: any = null;
  for (let attempt = 0; attempt < 10; attempt++) {
    const ref = order.ref || await generateUniqueRef(order.commune || undefined, order.type || undefined);
    try {
      updatedOrder = await prisma.order.update({
        where: { id: orderId },
        data: {
          ref,
          status: 'CONFIRMED',
          commercialId: assignee.id,
          commercialName: assignee.name,
          confirmedAt: now,
          confirmedByName: assignee.name,
          deliveryDate: order.deliveryDate ?? nextDeliveryDate,
          history,
        },
        include: { items: true },
      });
      break;
    } catch (e: any) {
      const isRefCollision = e.code === 'P2002' && e.meta?.target?.includes('ref');
      if (isRefCollision && !order.ref && attempt < 9) continue;
      throw e;
    }
  }

  if (!updatedOrder) throw new Error("Impossible de générer une référence unique pour cette commande.");

  revalidatePath("/zangochap-manager/orders");
  revalidatePath("/zangochap-manager/orders/to-process");
  revalidatePath("/zangochap-manager/dashboard");
  return { order: JSON.parse(JSON.stringify(updatedOrder)) };
}

// ============ DUPLICATE ORDER ============
export async function duplicateOrder(orderId: string, data: any) {
  const session = await getSession();
  if (!session) throw new Error("Non authentifié");

  const original = await prisma.order.findUnique({ where: { id: orderId } });
  if (!original) throw new Error("Commande originale introuvable");

  const baseNotes = String(data.notes || "").trim();
  let finalNotes = baseNotes;
  let exchangeRef: string | undefined;
  if (data.type === 'Echange') {
    const originalRef = String(original.ref || "").replace(/^ECHANGE/i, "");
    exchangeRef = `ECHANGE${originalRef}`;
    const exchangeLines = [`ECHANGE - Commande originale: ${original.ref}`];
    if (data.exchangeReason) exchangeLines.push(`MOTIF ECHANGE: ${data.exchangeReason}`);
    finalNotes = `${exchangeLines.join("\n")}${baseNotes ? `\n---\n${baseNotes}` : ''}`;
  }

  const newOrder = await createOrder({
    ...data,
    ref: exchangeRef,
    allowRefRetry: data.type === 'Echange',
    notes: finalNotes || `Dupliquée depuis ${original.ref}`,
  });

  return newOrder;
}

// ============ REPROGRAM ORDER ============
export async function reprogramOrder(orderId: string, data: any) {
  const session = await getSession();
  if (!session) throw new Error("Non authentifié");

  const original = await prisma.order.findUnique({ where: { id: orderId } });
  if (!original || !checkOrderAccess(original, session)) throw new Error("Accès refusé");

  if (original.deletedAt) throw new Error("Commande supprimée.");
  if (session.role === "commercial") return requestOrderReprogramming(orderId, data);
  if (!["admin", "developer"].includes(session.role)) throw new Error("Reprogrammation réservée aux commerciaux et administrateurs.");

  const originalRef = String(original.ref || "").replace(/^REPRO/i, "");
  const reproRef = `REPRO${originalRef}`;
  const baseNotes = String(data.notes || "").trim();
  const finalNotes = `REPROGRAMMATION - Commande originale: ${original.ref}${baseNotes ? `\n---\n${baseNotes}` : ""}`;

  const newOrder = await createOrder({
    ...data,
    ref: reproRef,
    allowRefRetry: true,
    type: "Reprogrammé",
    status: "CONFIRMED",
    notes: finalNotes,
  });

  const history = Array.isArray(original.history) ? [...(original.history as any[])] : [];
  history.push({
    at: new Date().toISOString(),
    action: `Nouvelle commande reprogrammée créée : ${newOrder.order.ref}`,
    by: session.email,
    byName: session.name,
  });
  await prisma.order.update({ where: { id: orderId }, data: { history } });

  revalidatePath("/zangochap-manager/orders");
  revalidatePath("/zangochap-manager/logistics");
  revalidatePath("/zangochap-manager/logistics/collection");
  revalidatePath("/zangochap-manager/logistics/packing");
  return newOrder;
}

// ============ REASSIGN ORDER LEAD ============
export async function reassignOrderLead(orderId: string, newCommercialId: string) {
  const session = await ensureAuth(["admin"]);

  const order = await prisma.order.findUnique({ where: { id: orderId } });
  if (!order || order.deletedAt) throw new Error("Commande introuvable");
  if (order.status !== 'TO_PROCESS') throw new Error("Cette commande n'est plus à traiter");

  const newCommercial = await prisma.user.findUnique({
    where: { id: newCommercialId },
    select: { id: true, name: true, role: true }
  });
  if (!newCommercial || newCommercial.role !== 'COMMERCIAL') {
    throw new Error("Commercial introuvable");
  }

  const oldName = order.commercialName || "Non assigné";
  const history = Array.isArray(order.history) ? [...(order.history as any[])] : [];
  history.push({
    at: new Date().toISOString(),
    action: `Réattribution manuelle du lead de ${oldName} à ${newCommercial.name}`,
    by: session.email,
    byName: session.name
  });

  const updated = await prisma.order.update({
    where: { id: orderId },
    data: {
      commercialId: newCommercial.id,
      commercialName: newCommercial.name,
      history
    }
  });

  revalidatePath("/zangochap-manager/orders/to-process");
  return { order: JSON.parse(JSON.stringify(updated)) };
}

// ============ UPDATE ROUND ROBIN ACTIVE COMMERCIALS ============
export async function updateRoundRobinActiveCommercials(activeCommercialIds: string[]) {
  const session = await ensureAuth(["admin"]);

  await prisma.$transaction(async (tx) => {
    // 1. Get or create RoundRobinState in cmsContent with row-level locking
    let stateRecord: any = null;
    const lockedRows: any[] = await tx.$queryRaw`SELECT * FROM "CmsContent" WHERE key = 'round_robin_state' FOR UPDATE`;
    if (lockedRows && lockedRows.length > 0) {
      stateRecord = lockedRows[0];
    }

    let lastAssignedId = null;
    if (stateRecord) {
      try {
        const data = typeof stateRecord.data === 'string' ? JSON.parse(stateRecord.data) : stateRecord.data;
        lastAssignedId = data?.lastAssignedId || null;
      } catch (e) {
        console.error("Failed to parse round_robin_state data:", e);
      }
    }

    const updatedData = {
      lastAssignedId,
      activeCommercialIds
    };

    await tx.cmsContent.upsert({
      where: { key: 'round_robin_state' },
      create: {
        key: 'round_robin_state',
        data: updatedData,
        updatedBy: session.email
      },
      update: {
        data: updatedData,
        updatedBy: session.email
      }
    });
  });

  revalidatePath("/zangochap-manager/orders/to-process");
  return { success: true };
}

"use server";

import prisma from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { getSession } from "@/modules/auth/actions";
import { ensureAuth } from "@/lib/auth";
import { isRole } from "../helpers";
import type { Prisma } from "@prisma/client";

// Commandes livrees via point relais : l'argent est encaisse par la boutique,
// jamais par le livreur. Elles sont exclues des montants a regler.
// NB: le OR explicite est necessaire car les filtres NOT/notIn de Prisma
// excluent aussi les lignes ou le champ est null (commandes livrees normales).
const BOUTIQUE_CASHED_STATUSES = ["BOUTIQUE_PICKED_UP", "BOUTIQUE_DELIVERED_OTHER"];
const NOT_BOUTIQUE_CASHED: Prisma.OrderWhereInput = {
  OR: [
    { lastDeliveryAttemptStatus: null },
    { lastDeliveryAttemptStatus: { notIn: BOUTIQUE_CASHED_STATUSES } },
  ],
};

type SettlementAmountOrder = {
  total: number | null;
  deliveryFee: number | null;
  discount: number | null;
  amountReceived: number | null;
};

function getOrderSettlementAmounts(order: SettlementAmountOrder) {
  const deliveryFee = Math.max(0, Number(order.deliveryFee || 0));
  const expectedProducts = Math.max(0, Number(order.total || 0) - Number(order.discount || 0));
  const expectedAmount = expectedProducts + deliveryFee;
  const collectedAmount = Math.max(0, Number(order.amountReceived ?? expectedAmount));
  const collectedDeliveryFee = Math.min(deliveryFee, collectedAmount);
  const collectedProducts = Math.max(0, collectedAmount - collectedDeliveryFee);

  return {
    amount: collectedAmount,
    productsAmount: collectedProducts,
    deliveryFeesAmount: collectedDeliveryFee,
  };
}

function getOrdersSettlementTotals(orders: SettlementAmountOrder[]) {
  return orders.reduce(
    (totals, order) => {
      const amounts = getOrderSettlementAmounts(order);
      totals.amount += amounts.amount;
      totals.productsAmount += amounts.productsAmount;
      totals.deliveryFeesAmount += amounts.deliveryFeesAmount;
      return totals;
    },
    { amount: 0, productsAmount: 0, deliveryFeesAmount: 0 },
  );
}

function getDateRange(from?: string, to?: string) {
  const range: { gte?: Date; lte?: Date } = {};

  if (from) {
    range.gte = new Date(`${from}T00:00:00`);
  }

  if (to) {
    range.lte = new Date(`${to}T23:59:59.999`);
  }

  return Object.keys(range).length > 0 ? range : undefined;
}

function getDeliveryIssueDateWhere(range?: { gte?: Date; lte?: Date }): Prisma.OrderWhereInput {
  if (!range) return {};
  return {
    OR: [
      { lastDeliveryAttemptAt: range },
      { lastDeliveryAttemptAt: null, deliveryDate: range },
    ],
  };
}

function getDeliveryIssueRiderWhere(riderId?: string): Prisma.OrderWhereInput {
  if (riderId) {
    return {
      OR: [
        { lastDeliveryAttemptRiderId: riderId },
        { lastDeliveryAttemptRiderId: null, deliverymanId: riderId },
      ],
    };
  }

  return {
    OR: [
      { lastDeliveryAttemptRiderId: { not: null } },
      { lastDeliveryAttemptRiderId: null, deliverymanId: { not: null } },
    ],
  };
}

const deliverySettlementOrderSelect = {
  id: true,
  ref: true,
  total: true,
  deliveryFee: true,
  discount: true,
  amountReceived: true,
  paymentMethod: true,
  customerName: true,
  customerPhone: true,
  customerLocation: true,
  commune: true,
  deliveryDate: true,
  deliveredAt: true,
  updatedAt: true,
  deliverymanId: true,
  deliverymanName: true,
  lastDeliveryAttemptAt: true,
  lastDeliveryAttemptRiderId: true,
  lastDeliveryAttemptRiderName: true,
  lastDeliveryAttemptStatus: true,
  lastDeliveryAttemptReason: true,
  settlementId: true,
  status: true,
  returnReason: true,
  isCommercialContacted: true,
} satisfies Prisma.OrderSelect;

type DeliverySettlementOrder = Prisma.OrderGetPayload<{
  select: typeof deliverySettlementOrderSelect;
}>;

function serializeSettlementOrder(order: DeliverySettlementOrder) {
  const amounts = getOrderSettlementAmounts(order);

  return {
    ...order,
    amountToSettle: amounts.amount,
    productsAmount: amounts.productsAmount,
    deliveryFeesAmount: amounts.deliveryFeesAmount,
  };
}

function groupOrdersByRider(orders: ReturnType<typeof serializeSettlementOrder>[]) {
  const riderMap = new Map<string, {
    id: string;
    name: string;
    orders: ReturnType<typeof serializeSettlementOrder>[];
    totalDeliveryFees: number;
    totalProducts: number;
    totalGrandTotal: number;
    cashTotal: number;
    orderCount: number;
  }>();

  orders.forEach((order) => {
    const riderId = String(order.deliverymanId || "unknown");
    const rider = riderMap.get(riderId) || {
      id: riderId,
      name: String(order.deliverymanName || "Livreur inconnu"),
      orders: [],
      totalDeliveryFees: 0,
      totalProducts: 0,
      totalGrandTotal: 0,
      cashTotal: 0,
      orderCount: 0,
    };

    rider.orders.push(order);
    rider.totalDeliveryFees += order.deliveryFeesAmount;
    rider.totalProducts += order.productsAmount;
    rider.totalGrandTotal += order.amountToSettle;
    rider.orderCount += 1;

    if (String(order.paymentMethod || "").toLowerCase().includes("cash")) {
      rider.cashTotal += order.amountToSettle;
    }

    riderMap.set(riderId, rider);
  });

  return Array.from(riderMap.values()).sort((a, b) => b.totalGrandTotal - a.totalGrandTotal);
}

function getIssueRiderId(order: ReturnType<typeof serializeSettlementOrder>) {
  return String(order.lastDeliveryAttemptRiderId || order.deliverymanId || "unknown");
}

function getIssueRiderName(order: ReturnType<typeof serializeSettlementOrder>) {
  return String(order.lastDeliveryAttemptRiderName || order.deliverymanName || "Livreur inconnu");
}

function buildSummary(
  collectableOrders: ReturnType<typeof serializeSettlementOrder>[],
  returnOrders: ReturnType<typeof serializeSettlementOrder>[],
  settlements: {
    amount: number;
    productsAmount: number;
    deliveryFeesAmount: number;
    ordersCount: number;
    deliverymanId: string | null;
  }[],
) {
  return {
    toSettleTotal: collectableOrders.reduce((sum, order) => sum + order.amountToSettle, 0),
    productsTotal: collectableOrders.reduce((sum, order) => sum + order.productsAmount, 0),
    deliveryFeesTotal: collectableOrders.reduce((sum, order) => sum + order.deliveryFeesAmount, 0),
    cashTotal: collectableOrders.reduce((sum, order) => (
      String(order.paymentMethod || "").toLowerCase().includes("cash") ? sum + order.amountToSettle : sum
    ), 0),
    collectableOrdersCount: collectableOrders.length,
    returnOrdersCount: returnOrders.length,
    uncontactedReturnsCount: returnOrders.filter((order) => !order.isCommercialContacted).length,
    historyTotal: settlements.reduce((sum, settlement) => sum + Number(settlement.amount || 0), 0),
    historyOrdersCount: settlements.reduce((sum, settlement) => sum + Number(settlement.ordersCount || 0), 0),
    historyRidersCount: new Set(settlements.map((settlement) => settlement.deliverymanId).filter(Boolean)).size,
  };
}

// ============ PENDING SETTLEMENTS ============
export async function getPendingSettlements() {
  await ensureAuth(["admin"]);
  const orders = await prisma.order.findMany({
    where: {
      status: { in: ['DELIVERED', 'PARTIALLY_DELIVERED'] },
      settlementId: null,
      deliverymanId: { not: null },
      // L'encaissement en point relais est fait par la boutique, pas par le
      // livreur : ces commandes ne doivent jamais entrer dans son reglement.
      ...NOT_BOUTIQUE_CASHED,
    },
    include: {
      items: { select: { name: true, qty: true, price: true } },
    },
    orderBy: { createdAt: 'desc' }
  });
  return orders;
}

// ============ SETTLEMENT HISTORY ============
export async function getSettlementHistory() {
  await ensureAuth(["admin"]);
  const settlements = await prisma.settlement.findMany({
    where: { status: 'COMPLETED' },
    select: {
      id: true,
      deliverymanId: true,
      amount: true,
      productsAmount: true,
      deliveryFeesAmount: true,
      ordersCount: true,
      status: true,
      notes: true,
      by: true,
      createdAt: true,
      deliveryman: { select: { name: true } },
      orders: { select: { id: true, ref: true, customerName: true, total: true, deliveryFee: true, discount: true, amountReceived: true } },
    },
    orderBy: { createdAt: 'desc' },
    take: 50,
  });
  return settlements.map((settlement) => {
    const totals = getOrdersSettlementTotals(settlement.orders);
    return {
      ...settlement,
      amount: totals.amount,
      productsAmount: totals.productsAmount,
      deliveryFeesAmount: totals.deliveryFeesAmount,
    };
  });
}

// ============ CREATE SETTLEMENT ============
export async function createSettlement(deliverymanId: string, orderIds: string[], amount: number, notes?: string) {
  const session = await getSession();
  if (!session || !isRole(session, 'admin')) throw new Error("Accès refusé");

  if (!deliverymanId || orderIds.length === 0) throw new Error("Aucune commande à régler.");

  const orders = await prisma.order.findMany({
    where: {
      id: { in: orderIds },
      deliverymanId,
      settlementId: null,
      status: { in: ['DELIVERED', 'PARTIALLY_DELIVERED'] },
      ...NOT_BOUTIQUE_CASHED,
    }
  });
  if (orders.length !== orderIds.length) {
    throw new Error("Certaines commandes sont déjà réglées ou ne sont pas éligibles.");
  }

  const {
    amount: computedAmount,
    productsAmount,
    deliveryFeesAmount,
  } = getOrdersSettlementTotals(orders);

  const settlement = await prisma.settlement.create({
    data: {
      deliverymanId,
      amount: computedAmount,
      productsAmount,
      deliveryFeesAmount,
      ordersCount: orderIds.length,
      notes: notes || (amount !== computedAmount ? `Montant recalculé côté serveur: ${computedAmount}` : undefined),
      by: session.name,
      status: 'COMPLETED',
      orders: {
        connect: orderIds.map(id => ({ id })),
      },
    },
  });

  revalidatePath("/zangochap-manager/admin/delivery");
  revalidatePath("/zangochap-manager/admin/delivery/settlement");
  revalidatePath("/zangochap-manager/admin/settlements");
  return settlement;
}

// ============ SETTLEMENT STATS BY PAYMENT METHOD ============
export async function getSettlementStats(from?: string, to?: string, commercialId?: string, method?: string) {
  const session = await getSession();
  if (session && isRole(session, 'comptable')) {
    // Comptable can inspect payment-method settlements without admin account-management access.
  } else
  if (!session || !isRole(session, 'admin')) throw new Error("Accès refusé");

  const where: Prisma.OrderWhereInput = {
    deletedAt: null,
    paymentMethod: method ? method : { not: null },
  };

  if (commercialId) where.commercialId = commercialId;

  // Parsing en heure locale via le helper partage (coherent avec la comptabilite).
  const deliveryRange = getDateRange(from, to);
  if (deliveryRange) where.deliveryDate = deliveryRange;

  const orders = await prisma.order.findMany({
    where,
    select: {
      id: true,
      ref: true,
      total: true,
      deliveryFee: true,
      discount: true,
      amountReceived: true,
      paymentMethod: true,
      customerName: true,
      createdAt: true,
      commercialName: true,
      status: true,
    },
    orderBy: { createdAt: 'desc' }
  });

  const stats: Record<string, { count: number, total: number }> = {};

  orders.forEach((o) => {
    const method = String(o.paymentMethod || 'Inconnu');
    if (!stats[method]) stats[method] = { count: 0, total: 0 };
    stats[method].count += 1;
    stats[method].total += (Number(o.total || 0) + Number(o.deliveryFee || 0) - Number(o.discount || 0));
  });

  const methods = Object.entries(stats).map(([method, data]) => ({
    method,
    count: data.count,
    total: data.total
  })).sort((a, b) => b.total - a.total);

  return { methods, orders };
}

export async function getDeliverySettlementDashboard(from?: string, to?: string, riderId?: string) {
  const session = await getSession();
  if (!session || !isRole(session, 'admin', 'comptable')) throw new Error("AccÃ¨s refusÃ©");

  const deliveryDateRange = getDateRange(from, to);
  const riderFilter: Prisma.OrderWhereInput = riderId ? { deliverymanId: riderId } : { deliverymanId: { not: null } };
  const issueRiderFilter = getDeliveryIssueRiderWhere(riderId);
  const settlementRiderFilter: Prisma.SettlementWhereInput = riderId ? { deliverymanId: riderId } : {};

  const [collectableRawOrders, returnRawOrders, settlements, deliverymen] = await Promise.all([
    prisma.order.findMany({
      where: {
        deletedAt: null,
        ...riderFilter,
        status: { in: ['DELIVERED', 'PARTIALLY_DELIVERED'] },
        settlementId: null,
        ...NOT_BOUTIQUE_CASHED,
        ...(deliveryDateRange ? { deliveryDate: deliveryDateRange } : {}),
      },
      select: deliverySettlementOrderSelect,
      orderBy: [{ deliverymanName: 'asc' }, { updatedAt: 'desc' }],
    }),
    prisma.order.findMany({
      where: {
        deletedAt: null,
        status: { in: ['RETURNED', 'CANCELLED', 'REPRO_DISPO'] },
        AND: [
          issueRiderFilter,
          getDeliveryIssueDateWhere(deliveryDateRange),
        ],
      },
      select: deliverySettlementOrderSelect,
      orderBy: [{ isCommercialContacted: 'asc' }, { updatedAt: 'desc' }],
    }),
    prisma.settlement.findMany({
      where: {
        status: 'COMPLETED',
        ...settlementRiderFilter,
        ...(deliveryDateRange ? { orders: { some: { deliveryDate: deliveryDateRange } } } : {}),
      },
      select: {
        id: true,
        deliverymanId: true,
        amount: true,
        productsAmount: true,
        deliveryFeesAmount: true,
        ordersCount: true,
        status: true,
        notes: true,
        by: true,
        createdAt: true,
        deliveryman: { select: { name: true } },
        orders: {
          ...(deliveryDateRange ? { where: { deliveryDate: deliveryDateRange } } : {}),
          select: {
            id: true,
            ref: true,
            customerName: true,
            status: true,
            total: true,
            deliveryFee: true,
            discount: true,
            amountReceived: true,
            paymentMethod: true,
            deliveryDate: true,
          },
          orderBy: { updatedAt: 'desc' },
        },
      },
      orderBy: { createdAt: 'desc' },
      take: 200,
    }),
    prisma.user.findMany({
      where: { role: 'LIVREUR' },
      select: { id: true, name: true },
      orderBy: { name: 'asc' },
    }),
  ]);

  const collectableOrders = collectableRawOrders.map(serializeSettlementOrder);
  const returnOrders = returnRawOrders.map(serializeSettlementOrder);
  const riders = groupOrdersByRider(collectableOrders);

  const deliveryDateHistory = settlements.map((settlement) => {
    const totals = getOrdersSettlementTotals(settlement.orders);
    return {
      ...settlement,
      amount: totals.amount,
      productsAmount: totals.productsAmount,
      deliveryFeesAmount: totals.deliveryFeesAmount,
      ordersCount: settlement.orders.length,
    };
  });

  return {
    filters: { from: from || "", to: to || "", riderId: riderId || "" },
    riderOptions: deliverymen,
    collectable: {
      riders,
      orders: collectableOrders,
    },
    returns: {
      orders: returnOrders,
      byRider: Object.values(returnOrders.reduce<Record<string, {
        id: string;
        name: string;
        orders: typeof returnOrders;
        uncontactedCount: number;
      }>>((acc, order) => {
        const id = getIssueRiderId(order);
        if (!acc[id]) {
          acc[id] = {
            id,
            name: getIssueRiderName(order),
            orders: [],
            uncontactedCount: 0,
          };
        }
        acc[id].orders.push(order);
        if (!order.isCommercialContacted) acc[id].uncontactedCount += 1;
        return acc;
      }, {})).sort((a, b) => b.uncontactedCount - a.uncontactedCount || a.name.localeCompare(b.name)),
    },
    history: deliveryDateHistory,
    summary: buildSummary(collectableOrders, returnOrders, deliveryDateHistory),
  };
}

// ============ RIDER SETTLEMENT STATS ============
export async function getRiderSettlementStats(from?: string, to?: string, riderId?: string) {
  const session = await getSession();
  if (!session || !isRole(session, 'admin')) throw new Error("Accès refusé");

  const where: Prisma.OrderWhereInput = { deletedAt: null };
  where.OR = [
    {
      ...(riderId ? { deliverymanId: riderId } : { deliverymanId: { not: null } }),
      status: { in: ['DELIVERED', 'PARTIALLY_DELIVERED'] },
      settlementId: null,
      ...NOT_BOUTIQUE_CASHED,
    },
    {
      ...getDeliveryIssueRiderWhere(riderId),
      status: { in: ['RETURNED', 'CANCELLED', 'REPRO_DISPO'] },
    },
  ];

  if (from || to) {
    const deliveryDateRange = getDateRange(from, to);
    where.AND = [
      {
        OR: [
          { status: { in: ['DELIVERED', 'PARTIALLY_DELIVERED'] }, deliveryDate: deliveryDateRange },
          { status: { in: ['RETURNED', 'CANCELLED', 'REPRO_DISPO'] }, ...getDeliveryIssueDateWhere(deliveryDateRange) },
        ],
      },
    ];
  }

  const orders = await prisma.order.findMany({
    where,
    select: {
      id: true,
      ref: true,
      total: true,
      deliveryFee: true,
      discount: true,
      amountReceived: true,
      paymentMethod: true,
      customerName: true,
      updatedAt: true,
      deliverymanId: true,
      deliverymanName: true,
      lastDeliveryAttemptAt: true,
      lastDeliveryAttemptRiderId: true,
      lastDeliveryAttemptRiderName: true,
      lastDeliveryAttemptStatus: true,
      lastDeliveryAttemptReason: true,
      settlementId: true,
      status: true,
      returnReason: true,
      isCommercialContacted: true,
    },
    orderBy: { updatedAt: 'desc' }
  });

  type RiderSettlementOrder = (typeof orders)[number];

  const riderMap: Record<string, {
    id: string,
    name: string,
    orders: RiderSettlementOrder[],
    totalDeliveryFees: number,
    totalProducts: number,
    totalGrandTotal: number,
    totalCashToCollect: number,
    returnedCount: number
  }> = {};

  orders.forEach((o) => {
    const isIssue = ['RETURNED', 'CANCELLED', 'REPRO_DISPO'].includes(o.status);
    const rId = isIssue ? String(o.lastDeliveryAttemptRiderId || o.deliverymanId || 'unknown') : String(o.deliverymanId || 'unknown');
    if (!riderMap[rId]) {
      riderMap[rId] = {
        id: rId,
        name: isIssue ? String(o.lastDeliveryAttemptRiderName || o.deliverymanName || 'Inconnu') : String(o.deliverymanName || 'Inconnu'),
        orders: [],
        totalDeliveryFees: 0,
        totalProducts: 0,
        totalGrandTotal: 0,
        totalCashToCollect: 0,
        returnedCount: 0
      };
    }

    const rider = riderMap[rId];
    rider.orders.push(o);

    if (['DELIVERED', 'PARTIALLY_DELIVERED'].includes(o.status)) {
      const {
        amount: collectedTotal,
        productsAmount,
        deliveryFeesAmount,
      } = getOrderSettlementAmounts(o);

      rider.totalProducts += productsAmount;
      rider.totalDeliveryFees += deliveryFeesAmount;
      rider.totalGrandTotal += collectedTotal;

      if (o.paymentMethod?.toLowerCase().includes('cash')) {
        rider.totalCashToCollect += collectedTotal;
      }
    } else if (['RETURNED', 'CANCELLED', 'REPRO_DISPO'].includes(o.status)) {
      rider.returnedCount += 1;
    }
  });

  const riders = Object.values(riderMap).sort((a, b) => b.totalGrandTotal - a.totalGrandTotal);

  return { riders, orders };
}

