  }[activeOrderMode];

  const handleOrderTypeChange = (type: string | null) => {
    const currentNote = deliveryNote.trim();
    const isAutomaticNote = Object.values(ORDER_TYPE_DEFAULT_NOTES).includes(currentNote);

    setOrderType(type);

    if (!type) {
